mkdir -p test src/lang && cat > test/interpreter.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { run } from "../src/lang";

describe("ruch żółwia", () => {
  test("np rysuje odcinek od początku wzdłuż +Y domyślnym kolorem i grubością", () => {
    const r = run("np 100", "2d");
    expect(r.error).toBeNull();
    expect(r.segments).toEqual([
      { from: [0, 0, 0], to: [0, 100, 0], color: "#16866a", width: 3 },
    ]);
  });
});
EOF
