cat > src/lang/types.ts <<'EOF'
export type Mode = "2d" | "3d";
export type Vec3 = [number, number, number];

export interface Segment {
  from: Vec3;
  to: Vec3;
  color: string;
  width: number;
}

export interface LangError {
  message: string;
  line: number;
  column: number;
}

export interface RunResult {
  segments: Segment[];
  error: LangError | null;
}
EOF
cat > src/lang/index.ts <<'EOF'
import type { Mode, RunResult, Segment } from "./types";
export type { Mode, RunResult, Segment, LangError, Vec3 } from "./types";

export function run(source: string, _mode: Mode): RunResult {
  const m = /^np\s+(\d+)$/i.exec(source.trim());
  const d = m ? Number(m[1]) : 0;
  const segments: Segment[] = [{ from: [0, 0, 0], to: [0, d, 0], color: "#16866a", width: 3 }];
  return { segments, error: null };
}
EOF
