cat >> test/interpreter.test.ts <<'EOF'

describe("obroty, aliasy i pióro", () => {
  test("kwadrat z czterech np i pw wraca dokładnie do początku", () => {
    const r = run("np 10 pw 90 np 10 pw 90 np 10 pw 90 np 10", "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to)).toEqual([
      [0, 10, 0],
      [10, 10, 0],
      [10, 0, 0],
      [0, 0, 0],
    ]);
  });

  test("polskie i angielskie aliasy są równoważne, wielkość liter nie ma znaczenia", () => {
    const a = run("np 10 pw 90 np 5 lw 90 ws 2", "2d");
    const b = run("FORWARD 10 Right 90 Naprzód 5 LEFT 90 back 2", "2d");
    expect(b).toEqual(a);
    expect(a.segments.map((s) => s.to)).toEqual([[0, 10, 0], [5, 10, 0], [5, 8, 0]]);
  });

  test("podniesione pióro przesuwa żółwia bez rysowania, opuszczone znowu rysuje", () => {
    const r = run("pod np 10 opu np 5", "2d");
    expect(r.segments).toEqual([{ from: [0, 10, 0], to: [0, 15, 0], color: "#16866a", width: 3 }]);
  });

  test("ruch o zero niczego nie rysuje", () => {
    expect(run("np 0 ws 0", "2d").segments).toEqual([]);
  });
});
EOF
