import type { Segment, Vec3 } from "./types";

export interface TurtleState {
  pos: Vec3;
  /** heading, right and up unit vectors */
  h: Vec3;
  r: Vec3;
  u: Vec3;
  pen: boolean;
  color: string;
  width: number;
}

/** sin/cos in degrees, exact at multiples of 90 so flat drawings stay clean. */
export function sinCos(deg: number): [number, number] {
  const m = ((deg % 360) + 360) % 360;
  if (m === 0) return [0, 1];
  if (m === 90) return [1, 0];
  if (m === 180) return [0, -1];
  if (m === 270) return [-1, 0];
  const rad = (m * Math.PI) / 180;
  return [Math.sin(rad), Math.cos(rad)];
}

export function initialTurtle(): TurtleState {
  return {
    pos: [0, 0, 0],
    h: [0, 1, 0],
    r: [1, 0, 0],
    u: [0, 0, 1],
    pen: true,
    color: "#16866a",
    width: 3,
  };
}

const combine = (a: Vec3, ca: number, b: Vec3, cb: number): Vec3 => [
  a[0] * ca + b[0] * cb,
  a[1] * ca + b[1] * cb,
  a[2] * ca + b[2] * cb,
];

/** Rotate the pair (a, b) so that a' = a cos + b sin, b' = b cos − a sin. */
export function rotatePair(a: Vec3, b: Vec3, deg: number): [Vec3, Vec3] {
  const [s, c] = sinCos(deg);
  return [combine(a, c, b, s), combine(b, c, a, -s)];
}

export function samePoint(a: Vec3, b: Vec3): boolean {
  return a[0] === b[0] && a[1] === b[1] && a[2] === b[2];
}

export type { Segment };
