import { LangFault } from "./fault";
import { initialTurtle, rotatePair, samePoint, type TurtleState } from "./machine";
import type { Program, Stmt } from "./ast";
import type { Segment, Vec3 } from "./types";

export interface StepInfo {
  line: number;
  column: number;
}

export class Execution {
  readonly turtle: TurtleState = initialTurtle();
  segments: Segment[] = [];
  private readonly gen: Generator<StepInfo, void, void>;
  finished = false;
  error: ReturnType<LangFault["toError"]> | null = null;

  constructor(private readonly program: Program) {
    this.gen = this.runBlock(program.body);
  }

  /** Execute up to the next operation. Returns the step, or null when the program is over. */
  step(): StepInfo | null {
    if (this.finished) return null;
    try {
      const r = this.gen.next();
      if (r.done) {
        this.finished = true;
        return null;
      }
      return r.value;
    } catch (e) {
      this.finished = true;
      if (e instanceof LangFault) {
        this.error = e.toError();
        return null;
      }
      throw e;
