import { LangFault } from "./fault";
import { initialTurtle, rotatePair, samePoint, type TurtleState } from "./machine";
import type { Program, Stmt } from "./ast";
import type { Segment, Vec3 } from "./types";

export interface StepInfo {
  line: number;
  column: number;
}

export class Execution {
  readonly turtle: TurtleState = initialTurtle();
  segments: Segment[] = [];
  private readonly gen: Generator<StepInfo, void, void>;
  finished = false;
  error: ReturnType<LangFault["toError"]> | null = null;

  constructor(private readonly program: Program) {
    this.gen = this.runBlock(program.body);
  }

  /** Execute up to the next operation. Returns the step, or null when the program is over. */
  step(): StepInfo | null {
    if (this.finished) return null;
    try {
      const r = this.gen.next();
      if (r.done) {
        this.finished = true;
        return null;
      }
      return r.value;
    } catch (e) {
      this.finished = true;
      if (e instanceof LangFault) {
        this.error = e.toError();
        return null;
      }
      throw e;
    }
  }

  private *runBlock(stmts: Stmt[]): Generator<StepInfo, void, void> {
    for (const s of stmts) yield* this.exec(s);
  }

  private *exec(s: Stmt): Generator<StepInfo, void, void> {
    if (s.t === "cmd") {
      const t = this.turtle;
      const d = s.arg && s.arg.e.k === "num" ? s.arg.e.v : 0;
      switch (s.name) {
        case "fd":
          this.move(d);
          break;
        case "bk":
          this.move(-d);
          break;
        case "rt":
          [t.h, t.r] = rotatePair(t.h, t.r, d);
          break;
        case "lt":
          [t.h, t.r] = rotatePair(t.h, t.r, -d);
          break;
        case "pu":
          t.pen = false;
          break;
        case "pd":
          t.pen = true;
          break;
      }
      yield { line: s.tok.line, column: s.tok.col };
    }
  }

  private move(d: number): void {
    const t = this.turtle;
    const to: Vec3 = [t.pos[0] + t.h[0] * d, t.pos[1] + t.h[1] * d, t.pos[2] + t.h[2] * d];
    if (t.pen && !samePoint(t.pos, to)) {
      this.segments.push({ from: t.pos, to, color: t.color, width: t.width });
    }
    t.pos = to;
  }
}
