const lastY = (src: string) => {
  const r = run(src, "2d");
  expect(r.error).toBeNull();
  return r.segments[r.segments.length - 1].to[1];
};

describe("wyrażenia", () => {
  test("* i / wiążą mocniej niż + i -", () => {
    expect(lastY("np 2 + 3 * 4")).toBe(14);
  });
  test("operatory o równym priorytecie łączą się od lewej", () => {
    expect(lastY("np 20 - 5 - 3")).toBe(12);
    expect(lastY("np 100 / 10 / 5")).toBe(2);
  });
  test("nawiasy grupują, a liczby mogą zaczynać się od kropki", () => {
    expect(lastY("np (1 + 2) * 3")).toBe(9);
    expect(lastY("np .5 + 12.5")).toBe(13);
  });
  test("znaki jednoargumentowe można piętrzyć wszędzie, gdzie oczekiwany jest operand", () => {
    expect(lastY("np -(3 - 5)")).toBe(2);
    expect(lastY("np - -2")).toBe(2);
    expect(lastY("np + +3")).toBe(3);
    expect(lastY("np 10 - -2")).toBe(12);
  });
  test("operator binarny ma spacje po obu stronach albo po żadnej", () => {
    expect(lastY("np 10 - 5")).toBe(5);
    expect(lastY("np 10-5")).toBe(5);
    expect(lastY("np 6*2")).toBe(12);
    expect(lastY("np 6 / 4")).toBe(1.5);
  });
  test("np 10 -5 to np 10 i zbłąkany token -5, zgłoszony na minusie", () => {
    const r = run("np 10 -5", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error?.line).toBe(1);
    expect(r.error?.column).toBe(7);
    expect(r.error?.message).toContain("-");
  });
  test("spacja tylko po jednej stronie operatora też go unieważnia", () => {
    expect(run("np 10- 5", "2d").error?.column).toBe(6);
    expect(run("np 10 *3", "2d").error?.column).toBe(7);
  });
  test("porównania nie podlegają regule spacji (patrz warunki)", () => {
    expect(run("np 10", "2d").error).toBeNull();
  });
  test("dzielenie przez zero to błąd wykonania na pierwszym tokenie argumentu, rysunek zostaje", () => {
    const r = run("np 10\nnp 5 + 1 / 0", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
    expect(r.error?.message.toLowerCase()).toContain("zero");
  });
});
