describe("powtórz i nrpowt", () => {
  test("powtórz wykonuje ciało n razy; kwadrat zamyka się w początku", () => {
    const r = run("powtorz 4 [np 10 pw 90]", "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to)).toEqual([[0, 10, 0], [10, 10, 0], [10, 0, 0], [0, 0, 0]]);
  });
  test("powtórz 0 nic nie robi, a pętle można zagnieżdżać", () => {
    expect(run("powtorz 0 [np 10]", "2d").segments).toEqual([]);
    expect(run("powtorz 3 [powtorz 2 [np 1]]", "2d").segments).toHaveLength(6);
  });
  test("nrpowt to numer iteracji najbliższego powtórz, od 1", () => {
    const r = run("powtorz 3 [np nrpowt]", "2d");
    expect(r.segments.map((s) => s.to[1])).toEqual([1, 3, 6]);
    const inner = run("powtorz 2 [powtorz 3 [np nrpowt]]", "2d");
    expect(inner.segments.map((s) => s.to[1])).toEqual([1, 3, 6, 7, 9, 12]);
  });
  test("REPCOUNT to to samo co nrpowt", () => {
    expect(run("repeat 2 [fd REPCOUNT]", "2d").segments.map((s) => s.to[1])).toEqual([1, 3]);
  });
  test("nrpowt poza powtórz to błąd parsowania i nic się nie rysuje", () => {
    const r = run("np 5\nnp nrpowt", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
  });
  test("literalna liczba powtórzeń musi być całkowita z 0–10000: błąd parsowania na liczbie", () => {
    for (const bad of ["2.5", "-1", "10001", "1 / 3"]) {
      const r = run(`np 10 powtorz ${bad} [np 1]`, "2d");
      expect(r.segments).toEqual([]);
      expect(r.error).toMatchObject({ line: 1, column: 15 });
    }
    expect(run("powtorz 10000 [ ]", "2d").error).toBeNull();
  });
  test("brak nawiasu otwierającego jest zgłaszany na znalezionym tokenie", () => {
    expect(run("powtorz 4 np 10", "2d").error).toMatchObject({ line: 1, column: 11 });
  });
  test("niedomknięty [ jest zgłaszany na nim samym, nadmiarowy ] na sobie", () => {
    expect(run("np 1\npowtorz 2 [ np 1", "2d").error).toMatchObject({ line: 2, column: 11 });
    expect(run("np 1 ]", "2d").error).toMatchObject({ line: 1, column: 6 });
  });
  test("brak argumentu na końcu programu jest zgłaszany na poleceniu", () => {
    expect(run("np 1\n  pw", "2d").error).toMatchObject({ line: 2, column: 3 });
    expect(run("np ]", "2d").error).toMatchObject({ line: 1, column: 4 });
  });
  test("zagnieżdżenie nawiasów głębsze niż 32 to błąd na 33. nawiasie", () => {
    const ok = "powtorz 1 [".repeat(32) + "]".repeat(32);
    expect(run(ok, "2d").error).toBeNull();
    const deep = "powtorz 1 [".repeat(33) + "]".repeat(33);
    expect(run(deep, "2d").error).toMatchObject({ line: 1, column: 10 * 32 + 1 + 9 });
  });
});
