    expect(run("dom", "2d").segments).toEqual([]);
    expect(run("np 3 pod pw 90 np 4 dom", "2d").segments).toHaveLength(1);
  });
  test("dom nie zmienia koloru, grubości ani stanu pióra", () => {
    const r = run('kolor "#2b6fb3" grubosc 9 pod np 4 dom np 2', "2d");
    expect(r.segments).toEqual([]);
    const r2 = run('kolor "#2b6fb3" grubosc 9 np 4 dom np 2', "2d");
    expect(r2.segments.map((s) => [s.color, s.width])).toEqual([["#2b6fb3", 9], ["#2b6fb3", 9], ["#2b6fb3", 9]]);
  });
  test("czyść usuwa wcześniejsze odcinki, nie zmieniając reszty stanu", () => {
    const r = run('kolor "#2b6fb3" np 10 czysc np 5', "2d");
    expect(r.segments).toEqual([{ from: [0, 10, 0], to: [0, 15, 0], color: "#2b6fb3", width: 3 }]);
  });
  test("stop na poziomie programu kończy program", () => {
    expect(run("np 1 stop np 2", "2d").segments).toHaveLength(1);
    expect(run("powtorz 5 [np 1 stop]", "2d").segments).toHaveLength(1);
  });
});
