describe("obroty przestrzenne (3D)", () => {
  const end = (src: string) => run(src, "3d").segments.at(-1)!.to.map((v) => Math.round(v * 1e9) / 1e9 + 0);
  test("gora 90 kieruje nos wzdłuż dawnego „góra”, dol 90 w przeciwną stronę", () => {
    expect(end("gora 90 np 10")).toEqual([0, 0, 10]);
    expect(end("dol 90 np 10")).toEqual([0, 0, -10]);
    expect(end("pitchup 90 np 10")).toEqual([0, 0, 10]);
  });
  test("pp 90 obraca „górę” żółwia ku jego prawej; potem gora 90 prowadzi w stronę +X", () => {
    expect(end("pp 90 gora 90 np 10")).toEqual([10, 0, 0]);
    expect(end("pl 90 gora 90 np 10")).toEqual([-10, 0, 0]);
  });
  test("po pp 90 prawa strona żółwia jest dawnym dołem, więc pw 90 prowadzi w dół", () => {
    expect(end("pp 90 pw 90 np 10")).toEqual([0, 0, -10]);
    expect(end("rollright 90 rt 90 np 10")).toEqual([0, 0, -10]);
  });
  test("przechylenie nie zmienia kierunku ruchu", () => {
    expect(end("pp 37 np 10")).toEqual([0, 10, 0]);
  });
  test("w trybie 2D gora, dol, pp i pl to błędy parsowania na poleceniu i nic się nie rysuje", () => {
    for (const cmd of ["gora", "dol", "pp", "pl", "pitchdown", "rollleft"]) {
      const r = run(`np 5\n  ${cmd} 10`, "2d");
      expect(r.segments).toEqual([]);
      expect(r.error).toMatchObject({ line: 2, column: 3 });
      expect(r.error?.message).toContain("3D");
    }
  });
  test("program z samych płaskich poleceń daje te same współrzędne w 2D i 3D", () => {
    const src = "powtorz 5 [np 180 pw 144] pod pw 17 np 33 opu lw 100 ws 5.5";
    expect(run(src, "3d")).toEqual(run(src, "2d"));
  });
  test("okrąg przechylony o 30° zamyka się i wychodzi z płaszczyzny", () => {
    const r = run("gora 30 powtorz 36 [np 12 pw 10]", "3d");
    const last = r.segments.at(-1)!.to;
    expect(Math.hypot(...last)).toBeLessThan(1e-9);
    const zs = r.segments.map((s) => s.to[2]);
    expect(Math.max(...zs)).toBeGreaterThan(20);
    expect(Math.min(...zs)).toBeLessThan(-0.01);
  });
});
