describe("zmienne", () => {
  test("niech przypisuje, kolejne niech przypisuje ponownie; :nazwa to to samo co nazwa", () => {
    expect(lastY("niech x 5 np x")).toBe(5);
    expect(lastY("niech x 5 niech x x + 1 np :x")).toBe(6);
    expect(lastY("LET Bok 7 np BOK")).toBe(7);
  });
  test("nazwa bez deklaracji to błąd parsowania na tej nazwie; nic się nie rysuje", () => {
    const r = run("np 5\nnp bok", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
  });
  test("zmienna przypisana dopiero później na górze jest zadeklarowana, ale czytana za wcześnie to błąd wykonania", () => {
    const r = run("np 5 np x niech x 1", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 1, column: 9 });
  });
  test("niech nie przyjmuje słów-poleceń ani nrpowt jako nazw", () => {
    for (const name of ["np", "forward", "powtorz", "niech", "nrpowt", "oto", "stop"]) {
      expect(run(`niech ${name} 1`, "2d").error).toMatchObject({ line: 1, column: 7 });
    }
  });
  test("niech bez wartości: błąd na poleceniu, gdy program się kończy", () => {
    expect(run("np 1\n  niech x", "2d").error).toMatchObject({ line: 2, column: 3 });
  });
});

describe("warunki", () => {
  const segs = (src: string) => run(src, "2d").segments.length;
  test("jeśli wykonuje ciało, gdy warunek zachodzi", () => {
    expect(segs("jeśli 1 < 2 [np 5]")).toBe(1);
    expect(segs("jesli 2 < 1 [np 5]")).toBe(0);
    expect(segs("if 3 <= 3 [np 5]")).toBe(1);
    expect(segs("if 3 >= 4 [np 5]")).toBe(0);
    expect(segs("if 3 <> 4 [np 5]")).toBe(1);
    expect(segs("if 3 = 3 [np 5]")).toBe(1);
    expect(segs("if 3 > 2 [np 5]")).toBe(1);
  });
  test("porównania są dokładne: 0.1 + 0.2 nie równa się 0.3", () => {
    expect(segs("jeśli 0.1 + 0.2 = 0.3 [np 5]")).toBe(0);
    expect(segs("jeśli 0.1 + 0.2 <> 0.3 [np 5]")).toBe(1);
  });
  test("jeżeli wybiera pierwsze albo drugie ciało", () => {
    expect(run("jeżeli 1 > 2 [np 1] [np 2]", "2d").segments[0].to[1]).toBe(2);
    expect(run("jezeli 2 > 1 [np 1] [np 2]", "2d").segments[0].to[1]).toBe(1);
    expect(run("ifelse 2 > 1 [np 1] [np 2]", "2d").segments[0].to[1]).toBe(1);
  });
  test("warunek korzysta ze zmiennych i nrpowt", () => {
    const r = run("niech z 1 powtorz 4 [jeśli nrpowt > z + 1 [np nrpowt]]", "2d");
    expect(r.segments.map((s) => s.to[1])).toEqual([3, 7]);
  });
  test("brak operatora porównania: błąd na znalezionym tokenie", () => {
    expect(run("jeśli 1 [np 1]", "2d").error).toMatchObject({ line: 1, column: 9 });
  });
  test("jeżeli bez drugiego ciała jest błędem", () => {
    expect(run("jeżeli 1 < 2 [np 1]", "2d").error).not.toBeNull();
    expect(run("jeżeli 1 < 2 [np 1] np 2", "2d").error).toMatchObject({ line: 1, column: 22 });
  });
  test("błąd obliczenia warunku wskazuje pierwszy token tej strony porównania", () => {
    const r = run("np 1\njeśli 1 < 5 / 0 [np 2]", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 2, column: 11 });
  });
});
EOF
