1	import { LangFault } from "./fault";
2	import { LIMITS } from "./limits";
3	import { COLOUR, constantValue, repeatCountProblem, widthProblem } from "./validate";
4	import { lex, type Token } from "./lexer";
5	import type { Arg, CmdName, Cond, Expr, Program, Stmt } from "./ast";
6	import { COMMANDS, IF, IFELSE, LET, REPCOUNT, REPEAT, RESERVED } from "./keywords";
7	import type { Mode } from "./types";
8	
9	const SPATIAL: ReadonlySet<CmdName> = new Set(["pitchup", "pitchdown", "rr", "rl"]);
10	const NO_ARG: ReadonlySet<CmdName> = new Set(["pu", "pd", "home", "cs", "stop"]);
11	
12	class Parser {
13	  private pos = 0;
14	  private readonly globals = new Set<string>();
15	
16	  constructor(
17	    private readonly toks: Token[],
18	    private readonly mode: Mode,
19	  ) {
20	    this.scan();
21	  }
22	
23	  /** First pass: names assigned by `niech`, so uses may come before the assignment. */
24	  private scan(): void {
25	    for (let i = 0; i + 1 < this.toks.length; i++) {
26	      const t = this.toks[i];
27	      const next = this.toks[i + 1];
28	      if (t.kind === "word" && LET.has(t.name) && (next.kind === "word" || next.kind === "cname")) {
29	        this.globals.add(next.name);
30	      }
31	    }
32	  }
33	
34	  program(): Program {
35	    const body: Stmt[] = [];
36	    while (this.pos < this.toks.length) body.push(this.statement());
37	    return { procs: new Map(), body };
38	  }
39	
40	  private peek(): Token | undefined {
41	    return this.toks[this.pos];
42	  }
43	
44	  private fault(msg: string, tok: Token): never {
45	    throw new LangFault(msg, tok.line, tok.col);
46	  }
47	
48	  private statement(): Stmt {
49	    const tok = this.toks[this.pos++];
50	    if (tok.kind === "bad") this.fault(tok.problem, tok);
51	    if (tok.kind === "word") {
52	      if (REPEAT.has(tok.name)) return this.repeat(tok);
53	      if (LET.has(tok.name)) return this.assign(tok);
54	      if (IF.has(tok.name)) return this.conditional(tok, false);
55	      if (IFELSE.has(tok.name)) return this.conditional(tok, true);
56	      const cmd = COMMANDS.get(tok.name);
57	      if (cmd) return this.command(tok, cmd);
58	    }
59	    if (tok.kind === "rbr") this.fault("Nadmiarowy nawias „]” bez pasującego „[”.", tok);
60	    return this.fault(`Nieznane polecenie „${tok.text}”.`, tok);
61	  }
62	
63	  private command(tok: Token, name: CmdName): Stmt {
64	    if (this.mode === "2d" && SPATIAL.has(name)) {
65	      this.fault(`Polecenie „${tok.text}” działa tylko w trybie 3D. Przełącz się na 3D lub użyj poleceń płaskich.`, tok);
66	    }
67	    if (NO_ARG.has(name)) return { t: "cmd", tok, name };
68	    if (name === "color") return this.colour(tok);
69	    const arg = this.arg(tok);
70	    if (name === "width") {
71	      const literal = constantValue(arg.e);
72	      const problem = literal === null ? null : widthProblem(literal);
73	      if (problem) this.fault(problem, arg.tok);
74	    }
75	    return { t: "cmd", tok, name, arg };
76	  }
77	
78	  private colour(tok: Token): Stmt {
79	    const lit = this.toks[this.pos++];
80	    if (!lit) this.fault("Polecenie „kolor” wymaga koloru w cudzysłowie, np. \"#16866a\".", tok);
81	    if (lit.kind === "bad") this.fault(lit.problem, lit);
82	    if (lit.kind !== "str" || !COLOUR.test(lit.name)) {
83	      this.fault("Kolor to napis z sześciu cyfr szesnastkowych w cudzysłowie, np. \"#16866a\".", lit);
84	    }
85	    return { t: "cmd", tok, name: "color", color: lit.name.toLowerCase() };
86	  }
87	
88	  private arg(cmd: Token): Arg {
89	    const tok = this.peek();
90	    if (!tok) this.fault(`Polecenie „${cmd.text}” wymaga argumentu.`, cmd);
91	    return { e: this.expression(), tok };
92	  }
93	
94	  private repDepth = 0;
95	
96	  private assign(tok: Token): Stmt {
97	    const name = this.toks[this.pos++];
98	    if (!name) this.fault("Polecenie „niech” wymaga nazwy zmiennej i wartości.", tok);
99	    if (name.kind === "bad") this.fault(name.problem, name);
100	    if (name.kind !== "word" && name.kind !== "cname") {
101	      this.fault(`Oczekiwano nazwy zmiennej, a jest „${name.text}”.`, name);
