import { LangFault } from "./fault";
import { LIMITS } from "./limits";
import { COLOUR, constantValue, repeatCountProblem, widthProblem } from "./validate";
import { lex, type Token } from "./lexer";
import type { Arg, CmdName, Cond, Expr, Program, Stmt } from "./ast";
import { COMMANDS, IF, IFELSE, LET, REPCOUNT, REPEAT, RESERVED } from "./keywords";
import type { Mode } from "./types";

const SPATIAL: ReadonlySet<CmdName> = new Set(["pitchup", "pitchdown", "rr", "rl"]);
const NO_ARG: ReadonlySet<CmdName> = new Set(["pu", "pd", "home", "cs", "stop"]);

class Parser {
  private pos = 0;
  private readonly globals = new Set<string>();

  constructor(
    private readonly toks: Token[],
    private readonly mode: Mode,
  ) {
    this.scan();
  }

  /** First pass: names assigned by `niech`, so uses may come before the assignment. */
  private scan(): void {
    for (let i = 0; i + 1 < this.toks.length; i++) {
      const t = this.toks[i];
      const next = this.toks[i + 1];
      if (t.kind === "word" && LET.has(t.name) && (next.kind === "word" || next.kind === "cname")) {
        this.globals.add(next.name);
      }
    }
  }

  program(): Program {
    const body: Stmt[] = [];
    while (this.pos < this.toks.length) body.push(this.statement());
    return { procs: new Map(), body };
  }

  private peek(): Token | undefined {
    return this.toks[this.pos];
  }

  private fault(msg: string, tok: Token): never {
    throw new LangFault(msg, tok.line, tok.col);
  }

  private statement(): Stmt {
    const tok = this.toks[this.pos++];
    if (tok.kind === "bad") this.fault(tok.problem, tok);
    if (tok.kind === "word") {
      if (REPEAT.has(tok.name)) return this.repeat(tok);
      if (LET.has(tok.name)) return this.assign(tok);
      if (IF.has(tok.name)) return this.conditional(tok, false);
      if (IFELSE.has(tok.name)) return this.conditional(tok, true);
      const cmd = COMMANDS.get(tok.name);
      if (cmd) return this.command(tok, cmd);
    }
    if (tok.kind === "rbr") this.fault("Nadmiarowy nawias „]” bez pasującego „[”.", tok);
    return this.fault(`Nieznane polecenie „${tok.text}”.`, tok);
  }

  private command(tok: Token, name: CmdName): Stmt {
    if (this.mode === "2d" && SPATIAL.has(name)) {
      this.fault(`Polecenie „${tok.text}” działa tylko w trybie 3D. Przełącz się na 3D lub użyj poleceń płaskich.`, tok);
    }
    if (NO_ARG.has(name)) return { t: "cmd", tok, name };
    if (name === "color") return this.colour(tok);
    const arg = this.arg(tok);
    if (name === "width") {
      const literal = constantValue(arg.e);
      const problem = literal === null ? null : widthProblem(literal);
      if (problem) this.fault(problem, arg.tok);
    }
    return { t: "cmd", tok, name, arg };
  }

  private colour(tok: Token): Stmt {
    const lit = this.toks[this.pos++];
    if (!lit) this.fault("Polecenie „kolor” wymaga koloru w cudzysłowie, np. \"#16866a\".", tok);
    if (lit.kind === "bad") this.fault(lit.problem, lit);
    if (lit.kind !== "str" || !COLOUR.test(lit.name)) {
      this.fault("Kolor to napis z sześciu cyfr szesnastkowych w cudzysłowie, np. \"#16866a\".", lit);
    }
    return { t: "cmd", tok, name: "color", color: lit.name.toLowerCase() };
  }

  private arg(cmd: Token): Arg {
    const tok = this.peek();
    if (!tok) this.fault(`Polecenie „${cmd.text}” wymaga argumentu.`, cmd);
    return { e: this.expression(), tok };
  }

  private repDepth = 0;

  private assign(tok: Token): Stmt {
    const name = this.toks[this.pos++];
    if (!name) this.fault("Polecenie „niech” wymaga nazwy zmiennej i wartości.", tok);
    if (name.kind === "bad") this.fault(name.problem, name);
    if (name.kind !== "word" && name.kind !== "cname") {
      this.fault(`Oczekiwano nazwy zmiennej, a jest „${name.text}”.`, name);
    }
    if (RESERVED.has(name.name)) {
      this.fault(`„${name.text}” jest słowem zarezerwowanym i nie może być nazwą zmiennej.`, name);
    }
    return { t: "let", tok, name: name.name, value: this.arg(tok) };
  }

  private conditional(tok: Token, withElse: boolean): Stmt {
    const l = this.arg(tok);
    const op = this.toks[this.pos++];
    if (!op) this.fault("Warunek wymaga operatora porównania: < > = <= >= <>.", tok);
    if (op.kind === "bad") this.fault(op.problem, op);
    if (op.kind !== "cmp") this.fault(`Oczekiwano operatora porównania (< > = <= >= <>), a jest „${op.text}”.`, op);
    const r = this.arg(tok);
    const cond: Cond = { l, op: op.name as Cond["op"], r };
    const then = this.block(tok);
    const otherwise = withElse ? this.block(tok) : null;
    return { t: "if", tok, cond, then, otherwise };
  }

  private repeat(tok: Token): Stmt {
    const count = this.arg(tok);
    const literal = constantValue(count.e);
    if (literal !== null) {
      const problem = repeatCountProblem(literal);
      if (problem) this.fault(problem, count.tok);
    }
    this.repDepth++;
    const body = this.block(tok);
    this.repDepth--;
    return { t: "repeat", tok, count, body };
  }

  /** Parses `[ statements ]`; `owner` is the command that needed the body. */
  private block(owner: Token): Stmt[] {
    const open = this.toks[this.pos];
    if (!open) this.fault(`Polecenie „${owner.text}” wymaga ciała w nawiasach [ ].`, owner);
    if (open.kind === "bad") this.fault(open.problem, open);
    if (open.kind !== "lbr") this.fault(`Oczekiwano „[”, a jest „${open.text}”.`, open);
    this.pos++;
    this.enter(open);
    const body: Stmt[] = [];
    for (;;) {
      const t = this.toks[this.pos];
      if (!t) this.fault("Brakuje zamykającego nawiasu „]”.", open);
      if (t.kind === "rbr") {
        this.pos++;
        break;
      }
      body.push(this.statement());
    }
    this.depth--;
    return body;
  }

  private depth = 0;

  private enter(open: Token): void {
    if (++this.depth > LIMITS.nesting) {
      this.fault(`Za głębokie zagnieżdżenie: limit to ${LIMITS.nesting} poziomów nawiasów.`, open);
    }
  }

  private expression(): Expr {
    let left = this.multiplicative();
    for (;;) {
      const op = this.binaryOp("+", "-");
      if (!op) return left;
      left = { k: "bin", op: op.name as "+" | "-", l: left, r: this.multiplicative() };
    }
  }

  private multiplicative(): Expr {
    let left = this.unary();
    for (;;) {
      const op = this.binaryOp("*", "/");
      if (!op) return left;
      left = { k: "bin", op: op.name as "*" | "/", l: left, r: this.unary() };
    }
  }

  /** A binary operator needs whitespace on both sides or on neither side. */
  private binaryOp(...ops: string[]): Token | null {
    const t = this.peek();
    if (t && t.kind === "op" && ops.includes(t.name) && t.spaceBefore === t.spaceAfter) {
      this.pos++;
      return t;
    }
    return null;
  }

  private unary(): Expr {
    const t = this.peek();
    if (t && t.kind === "op" && (t.name === "-" || t.name === "+")) {
      this.pos++;
      const e = this.unary();
      return t.name === "-" ? { k: "neg", e } : e;
    }
    return this.primary();
  }

  private primary(): Expr {
    const tok = this.toks[this.pos++];
    if (!tok) return this.fault("Wyrażenie jest niedokończone.", this.toks[this.toks.length - 1]);
    if (tok.kind === "bad") this.fault(tok.problem, tok);
    if (tok.kind === "num") return { k: "num", v: tok.value };
    if (tok.kind === "word" && REPCOUNT.has(tok.name)) {
      if (this.repDepth === 0) {
        this.fault("„nrpowt” można używać tylko wewnątrz ciała polecenia powtórz.", tok);
      }
      return { k: "rep" };
    }
    if (tok.kind === "word" || tok.kind === "cname") {
      if (tok.kind === "word" && RESERVED.has(tok.name)) {
        this.fault(`Oczekiwano wyrażenia, a jest polecenie „${tok.text}”.`, tok);
      }
      if (!this.globals.has(tok.name)) {
        this.fault(`Nazwa „${tok.text}” nie jest parametrem ani zmienną. Nadaj jej wartość poleceniem niech.`, tok);
      }
      return { k: "var", name: tok.name };
    }
    if (tok.kind === "lpar") {
      this.enter(tok);
      const e = this.expression();
      const close = this.toks[this.pos];
      if (!close) this.fault("Brakuje nawiasu zamykającego „)”.", tok);
      if (close.kind !== "rpar") this.fault(`Oczekiwano „)”, a jest „${close.text}”.`, close);
      this.pos++;
      this.depth--;
      return e;
    }
    return this.fault(`Oczekiwano wyrażenia, a jest „${tok.text}”.`, tok);
  }
}

export function parse(source: string, mode: Mode): Program {
  return new Parser(lex(source), mode).program();
}

