  name: string;
  params: string[];
}

interface Header {
  sig: Signature | null;
  error: LangFault | null;
  /** index of the first token after the header line */
  next: number;
}

interface Scope {
  params: Set<string>;
  locals: Set<string>;
}

class Parser {
  private pos = 0;
  private readonly globals = new Set<string>();
  private readonly signatures = new Map<string, Signature>();
  private readonly headers = new Map<number, Header>();
  private readonly scopes = new Map<number, Scope>();
  private scope: Scope | null = null;
  private readonly procs = new Map<string, Proc>();

  constructor(
    private readonly toks: Token[],
    private readonly mode: Mode,
  ) {
    this.scan();
  }

  /**
   * First pass: procedure headers (so calls may precede definitions) and the names
   * assigned by `niech` in each scope (so uses may precede assignments).
   */
  private scan(): void {
    const toks = this.toks;
    let current: Scope | null = null;
    for (let i = 0; i < toks.length; i++) {
      const t = toks[i];
      if (t.kind !== "word") continue;
      if (TO.has(t.name) && t.firstOnLine && !current) {
        const header = this.readHeader(i);
        this.headers.set(i, header);
        current = { params: new Set(header.sig?.params ?? []), locals: new Set() };
        this.scopes.set(i, current);
        i = header.next - 1;
      } else if (END.has(t.name) && t.firstOnLine && t.lastOnLine && current) {
        current = null;
      } else if (LET.has(t.name) && i + 1 < toks.length) {
        const next = toks[i + 1];
        if (next.kind === "word" || next.kind === "cname") (current ? current.locals : this.globals).add(next.name);
      }
    }
  }

  private readHeader(at: number): Header {
    const toks = this.toks;
    const oto = toks[at];
    let end = at + 1;
    while (end < toks.length && toks[end].line === oto.line) end++;
    const err = (msg: string, tok: Token): Header => ({ sig: null, error: new LangFault(msg, tok.line, tok.col), next: end });
    if (end === at + 1) return err("Po „oto” brakuje nazwy procedury.", oto);
    const nameTok = toks[at + 1];
    if (nameTok.kind === "bad") return err(nameTok.problem, nameTok);
    if (nameTok.kind !== "word") return err(`Oczekiwano nazwy procedury, a jest „${nameTok.text}”.`, nameTok);
    if (RESERVED.has(nameTok.name)) {
      return err(`„${nameTok.text}” jest słowem zarezerwowanym i nie może być nazwą procedury.`, nameTok);
    }
    if (this.signatures.has(nameTok.name)) {
      return err(`Procedura „${nameTok.text}” jest już zdefiniowana. Nazwę można zdefiniować tylko raz.`, nameTok);
    }
    const params: string[] = [];
    let i = at + 2;
    const addParam = (t: Token): string | null => {
      if (t.kind === "bad") return t.problem;
      if (t.kind !== "word" && t.kind !== "cname") return `Oczekiwano nazwy parametru, a jest „${t.text}”.`;
      if (RESERVED.has(t.name)) return `„${t.text}” jest słowem zarezerwowanym i nie może być nazwą parametru.`;
      if (params.includes(t.name)) return `Parametr „${t.text}” występuje w nagłówku więcej niż raz.`;
      params.push(t.name);
      return null;
    };
    if (i < end) {
      const first = toks[i];
      const isMa = first.kind === "ma" || (first.kind === "word" && first.name === "ma" && toks[i + 1]?.kind === "colon" && i + 1 < end);
      if (isMa) {
        i += first.kind === "ma" ? 1 : 2;
        if (i >= end) return err("Po „ma:” brakuje listy parametrów.", first);
        for (let expectParam = true; i < end; i++) {
          const t = toks[i];
          if (expectParam) {
            const problem = addParam(t);
            if (problem) return err(problem, t);
          } else if (t.kind !== "comma") {
            return err(`Parametry oddzielaj przecinkami; znaleziono „${t.text}”.`, t);
          }
          expectParam = !expectParam;
          if (!expectParam && i + 1 >= end) break;
          if (expectParam && i + 1 >= end) return err("Po przecinku brakuje nazwy parametru.", t);
        }
      } else {
        for (; i < end; i++) {
          const t = toks[i];
          if (t.kind !== "cname") return err(`Oczekiwano „ma:” albo parametrów w formie :nazwa, a jest „${t.text}”.`, t);
          const problem = addParam(t);
          if (problem) return err(problem, t);
        }
      }
    }
    const sig = { name: nameTok.name, params };
    this.signatures.set(sig.name, sig);
    return { sig, error: null, next: end };
  }

  program(): Program {
    const body: Stmt[] = [];
    while (this.pos < this.toks.length) body.push(this.statement());
    return { procs: this.procs, body };
  }

