import { LangFault } from "./fault";
import { repeatCountProblem, widthProblem } from "./validate";
import { initialTurtle, rotatePair, samePoint, type TurtleState } from "./machine";
import type { Arg, Cond, Expr, Program, Stmt } from "./ast";
import type { Segment, Vec3 } from "./types";

export interface StepInfo {
  line: number;
  column: number;
}

class EvalFailure extends Error {}

function finite(v: number): number {
  if (!Number.isFinite(v)) throw new EvalFailure("Wynik nie jest liczbą skończoną.");
  return v;
}

export class Execution {
  readonly turtle: TurtleState = initialTurtle();
  segments: Segment[] = [];
  private readonly gen: Generator<StepInfo, boolean, void>;
  finished = false;
  error: ReturnType<LangFault["toError"]> | null = null;

  constructor(private readonly program: Program) {
    this.gen = this.runBlock(program.body);
  }

  /** Execute up to the next operation. Returns the step, or null when the program is over. */
  step(): StepInfo | null {
    if (this.finished) return null;
    try {
      const r = this.gen.next();
      if (r.done) {
        this.finished = true;
        return null;
      }
      return r.value;
    } catch (e) {
      this.finished = true;
      if (e instanceof LangFault) {
        this.error = e.toError();
        return null;
      }
      throw e;
    }
  }

  private readonly counters: number[] = [];
  private readonly globals = new Map<string, number>();

  private compare(c: Cond): boolean {
    const l = this.evalArg(c.l);
    const r = this.evalArg(c.r);
    switch (c.op) {
      case "<": return l < r;
      case ">": return l > r;
      case "=": return l === r;
      case "<=": return l <= r;
      case ">=": return l >= r;
      default: return l !== r;
    }
  }

  /** Runs statements; returns true when a `stop` ended the enclosing call. */
  private *runBlock(stmts: Stmt[]): Generator<StepInfo, boolean, void> {
    for (const s of stmts) if (yield* this.exec(s)) return true;
    return false;
  }

  private *exec(s: Stmt): Generator<StepInfo, boolean, void> {
    if (s.t === "let") {
      this.globals.set(s.name, this.evalArg(s.value));
      yield { line: s.tok.line, column: s.tok.col };
      return false;
    }
    if (s.t === "if") {
      const taken = this.compare(s.cond);
      yield { line: s.tok.line, column: s.tok.col };

