import { LangFault } from "./fault";
import { repeatCountProblem, widthProblem } from "./validate";
import { initialTurtle, rotatePair, samePoint, type TurtleState } from "./machine";
import type { Arg, Cond, Expr, Program, Stmt } from "./ast";
import type { LangError, Segment, Vec3 } from "./types";

export interface StepInfo {
  line: number;
  column: number;
}

class EvalFailure extends Error {}

function finite(v: number): number {
  if (!Number.isFinite(v)) throw new EvalFailure("Wynik nie jest liczbą skończoną.");
  return v;
}

/** Variables and repeat counters of one procedure call (or of the top level). */
interface Frame {
  vars: Map<string, number>;
  counters: number[];
}

type Steps = Generator<StepInfo, boolean, void>;

export class Execution {
  readonly turtle: TurtleState = initialTurtle();
  segments: Segment[] = [];
  finished = false;
  error: LangError | null = null;

  private readonly globals = new Map<string, number>();
  private readonly top: Frame = { vars: this.globals, counters: [] };
  private readonly gen: Steps;

  constructor(private readonly program: Program) {
    this.gen = this.runBlock(program.body, this.top);
  }

  /** Execute up to the next operation. Returns where it happened, or null when the program is over. */
  step(): StepInfo | null {
    if (this.finished) return null;
    try {
      const r = this.gen.next();
      if (r.done) {
        this.finished = true;
        return null;
      }
      return r.value;
    } catch (e) {
      this.finished = true;
      if (e instanceof LangFault) {
        this.error = e.toError();
        return null;
      }
      throw e;
    }
  }

  /** Runs statements; returns true when a `stop` ended the enclosing call. */
  private *runBlock(stmts: Stmt[], f: Frame): Steps {
    for (const s of stmts) if (yield* this.exec(s, f)) return true;
    return false;
  }

  private *exec(s: Stmt, f: Frame): Steps {
    const at: StepInfo = { line: s.tok.line, column: s.tok.col };
    switch (s.t) {
      case "let":
        f.vars.set(s.name, this.evalArg(s.value, f));
        yield at;
        return false;
      case "if": {
        const taken = this.compare(s.cond, f);
        yield at;
        const body = taken ? s.then : s.otherwise;
        return body ? yield* this.runBlock(body, f) : false;
      }
      case "repeat": {
        const n = this.evalArg(s.count, f);
        const problem = repeatCountProblem(n);
        if (problem) throw new LangFault(problem, s.count.tok.line, s.count.tok.col);
        yield at;
        f.counters.push(0);
        for (let i = 1; i <= n; i++) {
          f.counters[f.counters.length - 1] = i;
          if (yield* this.runBlock(s.body, f)) return true;
        }
        f.counters.pop();
        return false;
      }
      case "call": {
        const proc = this.program.procs.get(s.proc)!;
        const vars = new Map<string, number>();
        proc.params.forEach((p, i) => vars.set(p, this.evalArg(s.args[i], f)));
        yield at;
        yield* this.runBlock(proc.body, { vars, counters: [] });
        return false;
      }
      case "cmd":
        return yield* this.command(s, f, at);
    }
  }

  private *command(s: Extract<Stmt, { t: "cmd" }>, f: Frame, at: StepInfo): Steps {
    const t = this.turtle;
    const d = s.arg ? this.evalArg(s.arg, f) : 0;
    switch (s.name) {
      case "fd":
        this.move(d);
        break;
      case "bk":
        this.move(-d);
        break;
      case "rt":
        [t.h, t.r] = rotatePair(t.h, t.r, d);
        break;
      case "lt":
        [t.h, t.r] = rotatePair(t.h, t.r, -d);
        break;
      case "pitchup":
        [t.h, t.u] = rotatePair(t.h, t.u, d);
        break;
      case "pitchdown":
        [t.h, t.u] = rotatePair(t.h, t.u, -d);
        break;
      case "rr":
        [t.u, t.r] = rotatePair(t.u, t.r, d);
        break;
      case "rl":
        [t.u, t.r] = rotatePair(t.u, t.r, -d);
        break;
      case "pu":
        t.pen = false;
        break;
      case "pd":
