describe("limity", () => {
  test("10 000 operacji: powtórz n [np 1] kosztuje 1 + 2n, więc 4999 mieści się, a 5000 nie", () => {
    const ok = run("powtorz 4999 [np 1]", "2d");
    expect(ok.error).toBeNull();
    expect(ok.segments).toHaveLength(4999);
    const over = run("powtorz 5000 [np 1]", "2d");
    expect(over.error?.message).toContain("10000");
    expect(over.error).toMatchObject({ line: 1, column: 1 });
    expect(over.segments).toHaveLength(5000);
  });
  test("pusty program o 10 000 poleceniach nie przekracza limitu, 10 001 tak (koniec programu nie jest liczony)", () => {
    const ten = run("niech x 0\npowtorz 3333 [niech x x + 1]", "2d");
    expect(ten.error).toBeNull(); // 1 + 1 + 3333*2 = 6667
    const over = run("niech x 0\npowtorz 5000 [niech x x + 1]", "2d");
    expect(over.error).not.toBeNull(); // 1 + 1 + 10000
  });
  test("nieskończona rekurencja zatrzymuje się na limicie ramek (32), rysunek zostaje", () => {
    const r = run("oto f\n np 1\n f\njuż\nf", "2d");
    expect(r.segments).toHaveLength(32);
    expect(r.error).toMatchObject({ line: 3, column: 2 });
    expect(r.error?.message).toContain("32");
  });
  test("32 aktywne ramki są dozwolone, 33 nie; ciała warunków nie są ramkami", () => {
    const src = (n: number) => `oto f ma: n\n jeśli n > 0 [f n - 1]\njuż\nf ${n}`;
    expect(run(src(31), "2d").error).toBeNull();
    expect(run(src(32), "2d").error).not.toBeNull();
    const deepRepeat = "powtorz 1 [".repeat(32) + "np 1" + "]".repeat(32);
    expect(run(deepRepeat, "2d").error).toBeNull();
    const cond = "jeśli 1 = 1 [".repeat(32) + "np 1" + "]".repeat(32);
    expect(run(cond, "2d").error).toBeNull();
  });
  test("ramki liczą razem wywołania i powtórzenia", () => {
    const src = "oto f ma: n\n powtorz 1 [jeśli n > 0 [f n - 1]]\njuż\nf 15";
    expect(run(src, "2d").error).toBeNull(); // 16 calls + 16 repeats = 32
    expect(run("oto f ma: n\n powtorz 1 [jeśli n > 0 [f n - 1]]\njuż\nf 16", "2d").error).not.toBeNull();
  });
  test("współrzędne w granicach ±100 000, także przy podniesionym piórze; przekroczenie nic nie rysuje", () => {
    expect(run("np 100000", "2d").error).toBeNull();
    const r = run("np 100001", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 1, column: 1 });
    expect(run("pod ws 100001", "2d").error).not.toBeNull();
    expect(run("np 100000 pw 90 np 100000 pw 90 np 200000", "2d").error).not.toBeNull();
  });
  test("program do 50 000 znaków przechodzi, 50 001 to błąd na pierwszym nadmiarowym znaku", () => {
    const pad = (n: number) => ";" + "x".repeat(n - 1);
    expect(run(pad(50000), "2d").error).toBeNull();
    const r = run(pad(50001), "2d");
    expect(r.error).toMatchObject({ line: 1, column: 50001 });
  });
  test("10 000 tokenów przechodzi, 10 001. jest błędem na tym tokenie", () => {
    const lines = (n: number) => Array.from({ length: n }, () => "np 1").join("\n");
    expect(run(lines(5000), "2d").error).toBeNull();
    const r = run(lines(5001), "2d");
    expect(r.error).toMatchObject({ line: 5001, column: 1 });
    expect(r.segments).toEqual([]);
  });
  test("błąd wykonania po czyść zachowuje tylko to, co narysowano później", () => {
    const r = run("np 5 czysc np 7 np 1 / 0", "2d");
    expect(r.segments.map((s) => s.to[1])).toEqual([7]);
    expect(r.error).not.toBeNull();
  });
});
EOF
