import { describe, expect, test } from "bun:test";
import { run } from "../src/lang";
import { EXAMPLES, exampleById } from "../src/core/examples";

const ex = (id: string) => {
  const e = exampleById(id)!;
  const r = run(e.source, e.mode);
  expect(r.error).toBeNull();
  return r.segments;
};
const len = (s: { from: number[]; to: number[] }) => Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);
const bbox = (segs: { from: number[]; to: number[] }[]) => {
  const pts = segs.flatMap((s) => [s.from, s.to]);
  return [0, 1, 2].map((k) => [Math.min(...pts.map((p) => p[k])), Math.max(...pts.map((p) => p[k]))]);
};

describe("standardowe programy", () => {
  test("jest trzynaście, w poprawnych trybach, pod właściwymi nazwami", () => {
    expect(EXAMPLES.map((e) => [e.id, e.mode])).toEqual([
      ["kwadrat", "2d"], ["gwiazda", "2d"], ["rozeta", "2d"], ["spirala", "2d"], ["wielokaty", "2d"],
      ["drzewo", "2d"], ["sniezynka", "2d"], ["schody", "3d"], ["szescian", "3d"], ["pierscien", "3d"],
      ["kula", "3d"], ["helisa", "3d"], ["drzewo3d", "3d"],
    ]);
  });
  test("każdy zaczyna się komentarzem z opisu zadania (źródła nie zostały przepisane)", () => {
    const first: Record<string, string> = {
      kwadrat: "; Cztery boki, cztery skręty.",
      gwiazda: "; Sekret gwiazdy? Kąt 144 stopni.",
      rozeta: "; Obróć kwadrat i zobacz, co powstanie.",
      spirala: "; Każdy bok jest dłuższy od poprzedniego, kolory na zmianę.",
      wielokaty: "; Jedna procedura, wiele figur: kąt liczy się sam.",
      drzewo: "; Rekurencja: gałąź rysuje dwie mniejsze gałęzie.",
      sniezynka: "; Krzywa Kocha: każdy odcinek dzieli się na cztery.",
      schody: "; Żółw wspina się w przestrzeni.",
      szescian: "; Dwa kwadraty połączone krawędziami.",
      pierscien: "; Okrąg przechylony o 30 stopni.",
      kula: "; Dwanaście okręgów, każdy przechylony o 15 stopni.",
      helisa: "; Spirala wznosi się ku górze.",
      drzewo3d: "; Drzewo w przestrzeni: gałęzie obracają się wokół pnia.",
    };
    for (const e of EXAMPLES) expect(e.source.split("\n")[0]).toBe(first[e.id]);
  });
  test("kwadrat: cztery boki po 120, zamknięty", () => {
    const s = ex("kwadrat");
    expect(s.map(len)).toEqual([120, 120, 120, 120]);
    expect(s[3].to).toEqual([0, 0, 0]);
  });
  test("gwiazda: pięć ramion po 180 wraca do początku", () => {
    const s = ex("gwiazda");
    expect(s).toHaveLength(5);
    expect(Math.hypot(...s[4].to)).toBeLessThan(1e-9);
    expect(s[0].color).toBe("#c1763d");
  });
  test("rozeta: dwanaście kwadratów po 4 odcinki", () => {
    expect(ex("rozeta")).toHaveLength(48);
  });
  test("spirala: 90 boków rosnących o 2,5, kolory na przemian zaczynając od zielonego", () => {
    const s = ex("spirala");
    expect(s).toHaveLength(90);
    expect(len(s[0])).toBeCloseTo(2.5, 9);
    expect(len(s[89])).toBeCloseTo(225, 9);
    expect(s.slice(0, 4).map((x) => x.color)).toEqual(["#16866a", "#c1763d", "#16866a", "#c1763d"]);
  });
  test("wielokąty: figury od trójkąta do dziewięciokąta, razem 42 boki po 60", () => {
    const s = ex("wielokaty");
    expect(s).toHaveLength(3 + 4 + 5 + 6 + 7 + 8 + 9);
    for (const seg of s) expect(len(seg)).toBeCloseTo(60, 9);
  });
  test("drzewo: pień brązowy i grubszy, gałązki zielone i cienkie", () => {
    const s = ex("drzewo");
    expect(s[0]).toMatchObject({ color: "#6b4f2a", width: 3 });
    expect(s.some((x) => x.color === "#2f8f4e" && x.width === 1)).toBe(true);
    expect(s.length).toBeGreaterThan(50);
  });
  test("śnieżynka: trzy boki po 4^4 = 256 odcinków długości 270/81", () => {
    const s = ex("sniezynka");
    expect(s).toHaveLength(768);
    expect(len(s[0])).toBeCloseTo(270 / 81, 9);
    expect(new Set(s.map((x) => x.color + x.width))).toEqual(new Set(["#2b6fb31"]));
  });
  test("schody: sześć stopni, każdy 35 do przodu i 20 w górę", () => {
    const s = ex("schody");
    expect(s).toHaveLength(12);
    expect(s[11].to.map((v) => Math.round(v))).toEqual([0, 210, 120]);
    expect(s[0].width).toBe(4);
  });
  test("sześcian: bryła o krawędzi 100 we wszystkich trzech wymiarach", () => {
    const s = ex("szescian");
    expect(s).toHaveLength(17);
    for (const [lo, hi] of bbox(s)) {
      expect(Math.round(hi - lo)).toBe(100);
    }
  });
  test("pierścień: 36 odcinków po 12, zamknięty, wychodzi nad płaszczyznę", () => {
    const s = ex("pierscien");
    expect(s).toHaveLength(36);
    expect(Math.hypot(...s[35].to)).toBeLessThan(1e-9);
    expect(bbox(s)[2][1]).toBeGreaterThan(10);
  });
  test("kula: 12 okręgów po 36 odcinków w dwóch kolorach", () => {
    const s = ex("kula");
    expect(s).toHaveLength(432);
    expect(new Set(s.map((x) => x.color))).toEqual(new Set(["#16866a", "#2b6fb3"]));
  });
  test("helisa: 120 zwojów, każdy 10 do przodu i 1,5 w górę; kończy na wysokości 180", () => {
    const s = ex("helisa");
    expect(s).toHaveLength(240);
    expect(s[239].to[2]).toBeCloseTo(180, 9);
  });
  test("drzewo 3D: rośnie w górę z pnia i mieści się w limitach", () => {
    const s = ex("drzewo3d");
    expect(s[0]).toMatchObject({ color: "#6b4f2a", width: 3 });
    expect(s[0].to[2]).toBeCloseTo(70, 9);
    expect(s.length).toBeGreaterThan(100);
  });
});
EOF
