/** A scheduler we drive by hand: the one external boundary (time) of the controller. */
function fakeScheduler() {
  let pending: (() => void) | null = null;
  return {
    schedule(cb: () => void, _ms: number) {
      pending = cb;
      return 1;
    },
    cancel() {
      pending = null;
    },
    get waiting() {
      return pending !== null;
    },
    fire() {
      const cb = pending;
      pending = null;
