import { initialTurtle, start, type Execution, type LangError, type Mode, type Segment, type TurtleState } from "../lang";

export type Status = "idle" | "running" | "paused" | "finished" | "error";

export interface ControllerState {
  mode: Mode;
  source: string;
  status: Status;
  segments: readonly Segment[];
  turtle: TurtleState;
  currentLine: number | null;
  currentColumn: number | null;
  error: LangError | null;
  steps: number;
}

export interface Scheduler {
  schedule(cb: () => void, ms: number): unknown;
  cancel(handle: unknown): void;
}

export interface ControllerOptions {
  scheduler: Scheduler;
}

export function createController(opts: ControllerOptions) {
  let mode: Mode = "2d";
  let source = "";
  let exec: Execution | null = null;
  let status: Status = "idle";
  let line: number | null = null;
  let column: number | null = null;
  let error: LangError | null = null;
  let steps = 0;

  const begin = (): boolean => {
    const s = start(source, mode);
    exec = s.execution;
    error = s.error;
    line = column = null;
    steps = 0;
    if (!exec) {
      status = "error";
      return false;
    }
    return true;
  };

  const advance = () => {
    if (!exec) return;
    const at = exec.step();
    if (at) {
      line = at.line;
      column = at.column;
      steps++;
      return;
    }
    line = column = null;
    error = exec.error;
    status = exec.error ? "error" : "finished";
  };

  return {
    setMode(m: Mode) {
      mode = m;
    },
    setSource(text: string) {
      source = text;
    },
    step() {
      if (!exec || status === "idle" || status === "finished" || status === "error") {
        if (!begin()) return;
      }
      status = "paused";
      advance();
    },
    getState(): ControllerState {
      return {
        mode,
        source,
        status,
        segments: exec ? exec.segments : [],
        turtle: exec ? exec.turtle : initialTurtle(),
        currentLine: line,
        currentColumn: column,
        error,
        steps,
      };
    },
  };
}
