describe("uruchamianie z animacją", () => {
  const SRC = "powtorz 4 [np 10 pw 90]";

  test("run niczego nie rysuje, dopóki zegar nie zadziała; po zakończeniu rysunek jest taki sam jak z run()", () => {
    const sched = fakeScheduler();
    const c = createController({ scheduler: sched });
    c.setMode("2d");
    c.setSource(SRC);
    c.setSpeed(2);
    c.run();
    expect(c.getState().status).toBe("running");
    expect(c.getState().segments).toHaveLength(0);
    expect(sched.waiting).toBe(true);

    let guard = 0;
    while (sched.waiting && guard++ < 1000) sched.fire();
    const s = c.getState();
    expect(s.status).toBe("finished");
    expect(s.segments).toEqual(run(SRC, "2d").segments);
    expect(sched.waiting).toBe(false);
  });

  test("pause zatrzymuje rysowanie, resume wznawia bez pomijania i powtarzania poleceń", () => {
    const sched = fakeScheduler();
    const c = createController({ scheduler: sched });
    c.setSource(SRC);
    c.setSpeed(1);
    c.run();
    sched.fire(); // powtórz
    sched.fire(); // np 10
    expect(c.getState().segments).toHaveLength(1);

    c.pause();
    expect(c.getState().status).toBe("paused");
    expect(sched.waiting).toBe(false);
    sched.fire();
    expect(c.getState().segments).toHaveLength(1);

    c.resume();
    expect(c.getState().status).toBe("running");
    while (sched.waiting) sched.fire();
    expect(c.getState().segments).toEqual(run(SRC, "2d").segments);
  });

  test("step w trakcie pauzy kontynuuje ten sam przebieg", () => {
    const sched = fakeScheduler();
    const c = createController({ scheduler: sched });
    c.setSource(SRC);
    c.setSpeed(1);
    c.run();
    sched.fire();
    sched.fire();
    c.pause();
