    expect(c.getState().stale).toBe(false);
    c.setSource("np 11");
    expect(c.getState().stale).toBe(true);
    expect(c.getState().segments).toHaveLength(1);
    c.setSource("np 10");
    expect(c.getState().stale).toBe(false);
  });

  test("zmiana trybu resetuje przebieg", () => {
    const c = createController({ scheduler: fakeScheduler() });
    c.setSource("np 10");
    c.runInstant();
    c.setMode("3d");
    const s = c.getState();
    expect(s.mode).toBe("3d");
    expect(s.status).toBe("idle");
    expect(s.segments).toHaveLength(0);
  });

  test("polecenia 3D w trybie 2D dają błąd, a w 3D działają", () => {
    const c = createController({ scheduler: fakeScheduler() });
    c.setSource("gora 90 np 10");
    c.setMode("2d");
    c.runInstant();
    expect(c.getState().error?.message).toContain("3D");
    c.setMode("3d");
    c.runInstant();
    expect(c.getState().segments[0].to).toEqual([0, 0, 10]);
  });

  test("subskrybenci są powiadamiani o zmianach; po wypisaniu cichną", () => {
    const sched = fakeScheduler();
    const c = createController({ scheduler: sched });
    let calls = 0;
    const off = c.subscribe(() => calls++);
    c.setSource("np 1");
    c.step();
    expect(calls).toBeGreaterThanOrEqual(2);
    off();
    const before = calls;
    c.reset();
    expect(calls).toBe(before);
  });
});
