import type { Mode } from "../lang";
import { exampleById } from "./examples";

export type StorageLike = Pick<Storage, "getItem" | "setItem" | "removeItem">;

interface Persisted {
  mode: Mode;
  drafts: Record<Mode, string>;
  /** example a draft was loaded from (null: written or imported by the user) */
  origins: Record<Mode, string | null>;
}

export interface WorkspaceState {
  mode: Mode;
  /** the draft of the current mode */
  draft: string;
  drafts: Record<Mode, string>;
}

const KEY = "logomocja.workspace.v1";

const defaults = (): Persisted => ({
  mode: "2d",
  drafts: { "2d": exampleById("kwadrat")!.source, "3d": exampleById("schody")!.source },
  origins: { "2d": "kwadrat", "3d": "schody" },
});

export function createWorkspace(deps: { storage: StorageLike }) {
  let data = defaults();

  const load = () => {
    try {
      const raw = deps.storage.getItem(KEY);
      if (!raw) return;
      const p = JSON.parse(raw) as Partial<Persisted>;
      const d = defaults();
      data = {
        mode: p.mode === "3d" ? "3d" : "2d",
        drafts: {
          "2d": typeof p.drafts?.["2d"] === "string" ? p.drafts["2d"] : d.drafts["2d"],
          "3d": typeof p.drafts?.["3d"] === "string" ? p.drafts["3d"] : d.drafts["3d"],
        },
        origins: { "2d": p.origins?.["2d"] ?? null, "3d": p.origins?.["3d"] ?? null },
      };
    } catch {
      data = defaults();
    }
  };

  const save = () => {
    try {
      deps.storage.setItem(KEY, JSON.stringify(data));
    } catch {
      /* storage full or unavailable: the session still works */
    }
  };

  load();

  return {
    getState(): WorkspaceState {
      return { mode: data.mode, draft: data.drafts[data.mode], drafts: { ...data.drafts } };
    },
    setMode(mode: Mode) {
      data.mode = mode;
      save();
    },
    setDraft(source: string) {
      data.drafts[data.mode] = source;
      save();
    },
  };
}

export type Workspace = ReturnType<typeof createWorkspace>;
EOF
