    const ws = createWorkspace({ storage: new MemoryStorage() });
    ws.setDraft("np 5 ; moja praca");
    const r = ws.loadExample("gwiazda");
    expect(r.status).toBe("needs-confirmation");
    expect(ws.getState().draft).toBe("np 5 ; moja praca");
  });

  test("po potwierdzeniu przykład wchodzi, a poprzedni szkic trafia do kopii i można go przywrócić", () => {
    const ws = createWorkspace({ storage: new MemoryStorage() });
    ws.setDraft("np 5 ; moja praca");
    ws.loadExample("gwiazda", { replace: true });
    expect(ws.getState().draft).toBe(exampleById("gwiazda")!.source);
    expect(ws.getState().backups.map((b) => b.source)).toEqual(["np 5 ; moja praca"]);

    ws.restoreBackup(0);
    expect(ws.getState().draft).toBe("np 5 ; moja praca");
  });

  test("kopie przeżywają przeładowanie strony", () => {
    const storage = new MemoryStorage();
    const a = createWorkspace({ storage });
    a.setDraft("np 7");
    a.loadExample("gwiazda", { replace: true });
    expect(createWorkspace({ storage }).getState().backups).toHaveLength(1);
  });

  test("przykład 3D otwarty w trybie 2D przełącza tryb i chroni szkic 3D, a nie 2D", () => {
    const ws = createWorkspace({ storage: new MemoryStorage() });
    ws.setDraft("np 5 ; praca 2D");
    ws.setMode("3d");
    ws.setDraft("gora 90 np 1 ; praca 3D");
    ws.setMode("2d");
    const r = ws.loadExample("helisa");
    expect(r.status).toBe("needs-confirmation");
    expect(ws.getState().mode).toBe("2d");
    ws.loadExample("helisa", { replace: true });
    expect(ws.getState().mode).toBe("3d");
    expect(ws.getState().draft).toBe(exampleById("helisa")!.source);
    ws.setMode("2d");
    expect(ws.getState().draft).toBe("np 5 ; praca 2D");
  });

  test("ten sam, niezmieniony przykład lub pusty szkic nie jest „brudny”", () => {
    const ws = createWorkspace({ storage: new MemoryStorage() });
    ws.loadExample("gwiazda");
    expect(ws.loadExample("rozeta").status).toBe("loaded");
    ws.setDraft("   \n");
    expect(ws.loadExample("kwadrat").status).toBe("loaded");
  });

  test("edycja przykładu czyni szkic brudnym, a cofnięcie edycji znów czystym", () => {
    const ws = createWorkspace({ storage: new MemoryStorage() });
    ws.loadExample("gwiazda");
    const original = ws.getState().draft;
    ws.setDraft(original + "\nnp 1");
    expect(ws.isDirty()).toBe(true);
    ws.setDraft(original);
    expect(ws.isDirty()).toBe(false);
  });

  test("wczytanie z zewnątrz (link, plik) zawsze odkłada brudny szkic do kopii", () => {
    const ws = createWorkspace({ storage: new MemoryStorage() });
    ws.setDraft("np 5 ; moje");
    ws.loadExternal("np 99", "2d", "plik.logo");
    expect(ws.getState().draft).toBe("np 99");
    expect(ws.getState().backups[0]).toMatchObject({ source: "np 5 ; moje", mode: "2d" });
    expect(ws.getState().backups[0].label).toContain("przed");
  });

  test("kopii jest co najwyżej 10, najnowsze pierwsze, identyczne nie dublują się", () => {
    const ws = createWorkspace({ storage: new MemoryStorage() });
    for (let i = 0; i < 14; i++) {
      ws.setDraft(`np ${i + 1}`);
      ws.loadExternal("np 999", "2d", "x");
    }
    const b = ws.getState().backups;
    expect(b).toHaveLength(10);
    expect(b[0].source).toBe("np 14");
    ws.setDraft("np 14");
    ws.loadExternal("np 999", "2d", "x");
    expect(ws.getState().backups.filter((x) => x.source === "np 14")).toHaveLength(1);
  });
});
