      const hash = url.slice(url.indexOf("#"));
      expect(parsePermalink(hash)).toEqual({ source: SRC, mode });
    }
  });

  test("adres nie zawiera znaków wymagających zakodowania", () => {
    const url = buildPermalink("http://x/", { source: "np 1 ??? >>> ~~~" + "ÿ".repeat(40), mode: "2d" });
    expect(url.slice(url.indexOf("#"))).toMatch(/^#\/p\/(2d|3d)\/[A-Za-z0-9_-]*$/);
  });

