    const url = buildPermalink("http://x/app/?a=1#/stare", { source: "np 1", mode: "2d" });
    expect(url.match(/#/g)).toHaveLength(1);
    expect(url.startsWith("http://x/app/?a=1#/p/2d/")).toBe(true);
  });

  test("nieprawidłowe lub obce hashe dają null", () => {
    for (const h of ["", "#", "#/", "#/przyklady", "#/p/4d/abc", "#/p/2d/", "#/p/2d/***", "#/p/2d/%%%"]) {
      expect(parsePermalink(h), h).toBeNull();
    }
  });

  test("pusty program też można udostępnić", () => {
    const url = buildPermalink("http://x/", { source: "", mode: "3d" });
    expect(parsePermalink(url.slice(url.indexOf("#")))).toEqual({ source: "", mode: "3d" });
  });
});

describe("pliki .logo", () => {
  test("plik to czysty tekst programu zakończony nową linią, z sensowną nazwą", () => {
    expect(logoFileText("np 1")).toBe("np 1\n");
    expect(logoFileText("np 1\n")).toBe("np 1\n");
    expect(suggestedFileName("2d")).toMatch(/^logomocja-2d-\d{8}\.logo$|^program-2d\.logo$/);
  });

  test("wczytanie usuwa BOM i ujednolica końce linii", () => {
    expect(readLogoText("﻿np 1\r\npw 90\rnp 2\r\n")).toBe("np 1\npw 90\nnp 2\n");
  });

  test("rozpoznaje programy używające poleceń przestrzennych (aby otworzyć je w 3D)", () => {
    expect(usesSpatialCommands("np 1 gora 90")).toBe(true);
    expect(usesSpatialCommands("; gora w komentarzu\nnp 1")).toBe(false);
    expect(usesSpatialCommands("RollLeft 5")).toBe(true);
    expect(usesSpatialCommands("niech dol 1")).toBe(true); // wystarczy słowo; błąd i tak zgłosi parser
    expect(usesSpatialCommands("np 1 pw 2")).toBe(false);
  });
});
EOF
