import { COMMAND_ALIASES } from "../lang/keywords";
import { lex } from "../lang/lexer";
import type { Mode } from "../lang";

export interface SharedProgram {
  source: string;
  mode: Mode;
}

const toBase64Url = (text: string): string => {
  const bytes = new TextEncoder().encode(text);
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
};

const fromBase64Url = (code: string): string | null => {
  if (!/^[A-Za-z0-9_-]*$/.test(code) || code.length % 4 === 1) return null;
  try {
    const bin = atob(code.replace(/-/g, "+").replace(/_/g, "/"));
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    return null;
  }
};

/** `base` may already carry a query or an old hash; the permalink replaces the hash. */
export function buildPermalink(base: string, program: SharedProgram): string {
  const clean = base.split("#")[0];
  return `${clean}#/p/${program.mode}/${toBase64Url(program.source)}`;
}

export function parsePermalink(hash: string): SharedProgram | null {
  const m = /^#\/p\/(2d|3d)\/([^/]*)$/.exec(hash);
  if (!m) return null;
  const source = fromBase64Url(m[2]);
  return source === null ? null : { source, mode: m[1] as Mode };
}

export function logoFileText(source: string): string {
  return source.endsWith("\n") ? source : source + "\n";
}

export function suggestedFileName(mode: Mode): string {
  return `program-${mode}.logo`;
}

export function readLogoText(raw: string): string {
  return raw.replace(/^﻿/, "").replace(/\r\n?/g, "\n");
}

const SPATIAL = new Set(
  [...COMMAND_ALIASES.pitchup, ...COMMAND_ALIASES.pitchdown, ...COMMAND_ALIASES.rr, ...COMMAND_ALIASES.rl].map((a) =>
    a.normalize("NFC"),
  ),
);

/** True when the program mentions a pitch or roll command (so it only makes sense in 3D). */
export function usesSpatialCommands(source: string): boolean {
  try {
    return lex(source).some((t) => t.kind === "word" && SPATIAL.has(t.name));
  } catch {
    return false;
  }
}
