const check = (id: string, source: string) => checkChallenge(challengeById(id)!, source);

describe("wyzwania: sprawdzanie rysunku", () => {
  test("jest co najmniej pięć wyzwań, każde z tytułem, opisem zadania i trybem", () => {
    expect(CHALLENGES.length).toBeGreaterThanOrEqual(5);
