      expect(c.title.length).toBeGreaterThan(2);
      expect(c.brief.length).toBeGreaterThan(20);
      expect(["2d", "3d"]).toContain(c.mode);
    }
    expect(new Set(CHALLENGES.map((c) => c.id)).size).toBe(CHALLENGES.length);
  });

  test("kwadrat 100: poprawne rozwiązania przechodzą, niezależnie od sposobu zapisu", () => {
    expect(check("kwadrat-100", "powtorz 4 [np 100 pw 90]").passed).toBe(true);
    expect(check("kwadrat-100", "np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100").passed).toBe(true);
    expect(check("kwadrat-100", "powtorz 4 [np 50 np 50 pw 90]").passed).toBe(true);
    expect(check("kwadrat-100", 'kolor "#2b6fb3" grubosc 9 powtorz 4 [np 100 pw 90]').passed).toBe(true);
  });

  test("zły rozmiar, kierunek lub nadmiar kończą się porażką z powodem po polsku", () => {
    const small = check("kwadrat-100", "powtorz 4 [np 90 pw 90]");
    expect(small.passed).toBe(false);
    expect(small.reason).toMatch(/Brakuje|nadmiar/i);

    const mirrored = check("kwadrat-100", "powtorz 4 [np 100 lw 90]");
    expect(mirrored.passed).toBe(false);

    const extra = check("kwadrat-100", "powtorz 4 [np 100 pw 90] np 50");
    expect(extra.passed).toBe(false);
    expect(extra.reason).toMatch(/nadmiar/i);

    const half = check("kwadrat-100", "np 100 pw 90 np 100");
    expect(half.passed).toBe(false);
    expect(half.reason).toMatch(/Brakuje/);
  });

  test("pusty rysunek i błąd w programie mają własne, zrozumiałe powody", () => {
    expect(check("kwadrat-100", "").reason).toMatch(/niczego nie narysował/i);
    const broken = check("kwadrat-100", "np 100\nnp iks");
    expect(broken.passed).toBe(false);
    expect(broken.reason).toContain("linia 2");
  });

  test("trójkąt, sześciokąt, gwiazda i krzyż mają poprawne rozwiązania", () => {
    expect(check("trojkat", "powtorz 3 [np 120 pw 120]").passed).toBe(true);
    expect(check("szesciokat", "powtorz 6 [np 60 pw 60]").passed).toBe(true);
    expect(check("gwiazda-5", "powtorz 5 [np 150 pw 144]").passed).toBe(true);
    expect(check("krzyz", "powtorz 4 [np 60 ws 60 pw 90]").passed).toBe(true);
    expect(check("krzyz", "powtorz 3 [np 60 ws 60 pw 90]").passed).toBe(false);
    expect(check("trojkat", "powtorz 3 [np 120 pw 90]").passed).toBe(false);
  });

  test("schodki wymagają użycia powtórz", () => {
    const loop = "powtorz 5 [np 30 pw 90 np 30 lw 90]";
    expect(check("schodki", loop).passed).toBe(true);
    const flat = check("schodki", "np 30 pw 90 np 30 lw 90 ".repeat(5));
    expect(flat.passed).toBe(false);
    expect(flat.reason).toMatch(/powtórz/);
