import type { Segment, Vec3 } from "../lang";

type Seg = Pick<Segment, "from" | "to">;

export function distanceToSegment(p: Vec3, a: Vec3, b: Vec3): number {
  const abx = b[0] - a[0];
  const aby = b[1] - a[1];
  const abz = b[2] - a[2];
  const len2 = abx * abx + aby * aby + abz * abz;
  let t = len2 === 0 ? 0 : ((p[0] - a[0]) * abx + (p[1] - a[1]) * aby + (p[2] - a[2]) * abz) / len2;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(p[0] - (a[0] + abx * t), p[1] - (a[1] + aby * t), p[2] - (a[2] + abz * t));
}

/** Points spaced at most `step` apart along every segment (endpoints included). */
export function samplePoints(segs: readonly Seg[], step: number, cap = 6000): Vec3[] {
  const total = segs.reduce((n, s) => n + Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]), 0);
  const eff = Math.max(step, total / cap);
  const pts: Vec3[] = [];
  for (const s of segs) {
    const len = Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);
    const n = Math.max(1, Math.ceil(len / eff));
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      pts.push([
        s.from[0] + (s.to[0] - s.from[0]) * t,
        s.from[1] + (s.to[1] - s.from[1]) * t,
        s.from[2] + (s.to[2] - s.from[2]) * t,
      ]);
    }
  }
  return pts;
}

/** First point of `from` that lies farther than `tol` from every segment of `onto`, or null. */
export function firstUncovered(from: readonly Seg[], onto: readonly Seg[], tol: number): Vec3 | null {
  const pts = samplePoints(from, tol);
  for (const p of pts) {
    let near = false;
    for (const s of onto) {
      if (distanceToSegment(p, s.from, s.to) <= tol) {
        near = true;
        break;
      }
    }
    if (!near) return p;
  }
  return null;
}
