export const challengeById = (id: string): Challenge | undefined => CHALLENGES.find((c) => c.id === id);

const targets = new Map<string, Segment[]>();
const targetOf = (c: Challenge): Segment[] => {
  let t = targets.get(c.id);
  if (!t) {
    t = run(c.solution, c.mode).segments;
    targets.set(c.id, t);
  }
  return t;
};

const fmt = (p: readonly number[]) => `(${p.map((v) => Math.round(v)).join(", ")})`;

export function checkChallenge(c: Challenge, source: string): CheckResult {
  const result = run(source, c.mode);
  if (result.error) {
    const { line, column, message } = result.error;
    return { passed: false, reason: `Program zawiera błąd (linia ${line}, kolumna ${column}): ${message}` };
  }
  if (c.requireWord && !c.requireWord.pattern.test(source.replace(/;[^\n]*/g, ""))) {
    return { passed: false, reason: c.requireWord.message };
  }
  const drawn = result.segments;
  if (drawn.length === 0) return { passed: false, reason: "Program niczego nie narysował." };

  const target = targetOf(c);
  const missing = firstUncovered(target, drawn, c.tolerance);
  if (missing) {
    return { passed: false, reason: `Brakuje części rysunku, np. w okolicy punktu ${fmt(missing)}.` };
  }
  const extra = firstUncovered(drawn, target, c.tolerance);
  if (extra) {
    return { passed: false, reason: `Na rysunku jest coś nadmiarowego, np. w okolicy punktu ${fmt(extra)}.` };
  }
  if (c.requireColor && drawn.some((s) => s.color !== c.requireColor)) {
    return { passed: false, reason: `Rysunek jest dobry, ale kolor linii powinien być ${c.requireColor}.` };
  }
  if (c.requireWidth && drawn.some((s) => s.width !== c.requireWidth)) {
    return { passed: false, reason: `Rysunek jest dobry, ale grubość linii powinna wynosić ${c.requireWidth}.` };
  }
  return { passed: true, reason: "Rysunek zgadza się ze wzorem." };
}
