import { describe, expect, test } from "bun:test";
import { defaultCamera, fitCamera, makeProjector, boundsOf } from "../src/ui/camera";
import { run } from "../src/lang";
import { exampleById } from "../src/core/examples";

const W = 800;
const H = 500;

describe("kamera 2D", () => {
  test("domyślny widok pokazuje początek układu pośrodku", () => {
    const p = makeProjector(defaultCamera("2d"), W, H);
    const o = p.project([0, 0, 0])!;
    expect(o.x).toBeCloseTo(W / 2, 6);
    expect(o.y).toBeCloseTo(H / 2, 6);
  });

  test("oś Y rośnie w górę ekranu, a X w prawo", () => {
    const p = makeProjector(defaultCamera("2d"), W, H);
    const o = p.project([0, 0, 0])!;
    expect(p.project([0, 10, 0])!.y).toBeLessThan(o.y);
    expect(p.project([10, 0, 0])!.x).toBeGreaterThan(o.x);
  });

  test("dopasowanie mieści cały rysunek z marginesem, także gdy leży daleko od początku", () => {
    const segs = run("pod np 900 pw 90 np 400 opu pw 90 np 300", "2d").segments;
    const cam = fitCamera("2d", segs, W, H);
    const p = makeProjector(cam, W, H);
    for (const s of segs) {
      for (const pt of [s.from, s.to]) {
        const q = p.project(pt)!;
        expect(q.x).toBeGreaterThanOrEqual(0);
        expect(q.x).toBeLessThanOrEqual(W);
        expect(q.y).toBeGreaterThanOrEqual(0);
        expect(q.y).toBeLessThanOrEqual(H);
      }
    }
  });

  test("dopasowanie pustego rysunku wraca do widoku domyślnego", () => {
    expect(fitCamera("2d", [], W, H)).toEqual(defaultCamera("2d"));
  });

  test("dopasowanie pojedynczego punktu lub odcinka o zerowej szerokości nie daje nieskończonego powiększenia", () => {
    const cam = fitCamera("2d", run("np 100", "2d").segments, W, H);
    expect(Number.isFinite(cam.kind === "2d" ? cam.scale : NaN)).toBe(true);
    expect((cam as { scale: number }).scale).toBeLessThan(20);
  });
});

describe("kamera 3D", () => {
  test("punkty przed kamerą są rzutowane, a za nią — nie", () => {
    const cam = defaultCamera("3d");
    if (cam.kind !== "3d") throw new Error();
    const p = makeProjector(cam, W, H);
    expect(p.project(cam.target)).not.toBeNull();
    const behind = makeProjector({ ...cam, dist: 10 }, W, H);
    // punkt daleko za kamerą
    const eyeDir = [
      Math.cos(cam.pitch) * Math.sin(cam.yaw),
      -Math.cos(cam.pitch) * Math.cos(cam.yaw),
      Math.sin(cam.pitch),
    ];
    const farBehind: [number, number, number] = [eyeDir[0] * 500, eyeDir[1] * 500, eyeDir[2] * 500];
    expect(behind.project(farBehind)).toBeNull();
  });

  test("z góry (+Z) widać „górę” ekranu: wyższy punkt leży wyżej na ekranie", () => {
    const p = makeProjector(defaultCamera("3d"), W, H);
    expect(p.project([0, 0, 50])!.y).toBeLessThan(p.project([0, 0, 0])!.y);
  });

  test("bliższe punkty rysowane są większe i mają mniejszą głębię", () => {
    const cam = defaultCamera("3d");
    const p = makeProjector(cam, W, H);
    const near = p.project([0, -100, 0])!;
    const far = p.project([0, 100, 0])!;
    expect(near.depth).toBeLessThan(far.depth);
    expect(near.scale).toBeGreaterThan(far.scale);
  });

  test("dopasowanie mieści każdy z trzynastu standardowych rysunków 3D w kadrze", () => {
    for (const id of ["schody", "szescian", "pierscien", "kula", "helisa", "drzewo3d"]) {
      const ex = exampleById(id)!;
      const segs = run(ex.source, "3d").segments;
      const cam = fitCamera("3d", segs, W, H);
      const p = makeProjector(cam, W, H);
      for (const s of segs) {
        for (const pt of [s.from, s.to]) {
          const q = p.project(pt);
          expect(q, id).not.toBeNull();
          expect(q!.x, id).toBeGreaterThan(-1);
          expect(q!.x, id).toBeLessThan(W + 1);
          expect(q!.y, id).toBeGreaterThan(-1);
          expect(q!.y, id).toBeLessThan(H + 1);
        }
      }
    }
  });

  test("granice rysunku obejmują oba końce każdego odcinka", () => {
    const b = boundsOf(run("np 10 pw 90 np 20", "2d").segments)!;
    expect(b.min).toEqual([0, 0, 0]);
    expect(b.max).toEqual([20, 10, 0]);
    expect(boundsOf([])).toBeNull();
  });
});
