import type { Mode, Segment, Vec3 } from "../lang";

export interface Camera2D {
  kind: "2d";
  /** world point shown at the centre of the view */
  cx: number;
  cy: number;
  /** pixels per world unit */
  scale: number;
}

export interface Camera3D {
  kind: "3d";
  target: Vec3;
  /** radians; 0 looks from −Y towards +Y */
  yaw: number;
  /** radians above the ground plane */
  pitch: number;
  dist: number;
}

export type Camera = Camera2D | Camera3D;

export interface Projected {
  x: number;
  y: number;
  /** distance along the view direction (2D: 0) */
  depth: number;
  /** pixels per world unit at this point */
  scale: number;
}

export interface Projector {
  project(p: Vec3): Projected | null;
}

export const FOV = (40 * Math.PI) / 180;
const MIN_SPAN = 40;
const PAD = 36;

export const MIN_SCALE = 0.02;
export const MAX_SCALE = 400;
export const MIN_DIST = 20;
export const MAX_DIST = 2_000_000;
export const MAX_PITCH = (89 * Math.PI) / 180;

export function defaultCamera(mode: Mode): Camera {
  return mode === "2d"
    ? { kind: "2d", cx: 0, cy: 0, scale: 1.6 }
    : { kind: "3d", target: [0, 0, 0], yaw: (-32 * Math.PI) / 180, pitch: (24 * Math.PI) / 180, dist: 520 };
}

export function boundsOf(segs: readonly Pick<Segment, "from" | "to">[]): { min: Vec3; max: Vec3 } | null {
  if (segs.length === 0) return null;
  const min: Vec3 = [Infinity, Infinity, Infinity];
  const max: Vec3 = [-Infinity, -Infinity, -Infinity];
  for (const s of segs) {
    for (const p of [s.from, s.to]) {
      for (let k = 0; k < 3; k++) {
        if (p[k] < min[k]) min[k] = p[k];
        if (p[k] > max[k]) max[k] = p[k];
      }
    }
  }
  return { min, max };
}

const sub = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec3, b: Vec3): Vec3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
const norm = (a: Vec3): Vec3 => {
  const l = Math.hypot(a[0], a[1], a[2]) || 1;
  return [a[0] / l, a[1] / l, a[2] / l];
};

export function eyeOf(cam: Camera3D): Vec3 {
  const cp = Math.cos(cam.pitch);
  return [
    cam.target[0] + cam.dist * Math.sin(cam.yaw) * cp,
    cam.target[1] - cam.dist * Math.cos(cam.yaw) * cp,
    cam.target[2] + cam.dist * Math.sin(cam.pitch),
  ];
}

export function basisOf(cam: Camera3D): { eye: Vec3; right: Vec3; up: Vec3; forward: Vec3 } {
  const eye = eyeOf(cam);
  const forward = norm(sub(cam.target, eye));
  const right = norm(cross(forward, [0, 0, 1]));
  const up = cross(right, forward);
  return { eye, right, up, forward };
}

export function makeProjector(cam: Camera, w: number, h: number): Projector {
  if (cam.kind === "2d") {
    return {
      project: (p) => ({
        x: w / 2 + (p[0] - cam.cx) * cam.scale,
        y: h / 2 - (p[1] - cam.cy) * cam.scale,
        depth: 0,
        scale: cam.scale,
      }),
    };
  }
  const { eye, right, up, forward } = basisOf(cam);
  const focal = h / 2 / Math.tan(FOV / 2);
  const near = cam.dist * 0.02;
  return {
    project: (p) => {
      const d = sub(p, eye);
      const z = dot(d, forward);
      if (z <= near) return null;
      return {
        x: w / 2 + (dot(d, right) / z) * focal,
        y: h / 2 - (dot(d, up) / z) * focal,
        depth: z,
        scale: focal / z,
      };
    },
  };
}

export function fitCamera(mode: Mode, segs: readonly Segment[], w: number, h: number): Camera {
  const b = boundsOf(segs);
  if (!b) return defaultCamera(mode);
  const centre: Vec3 = [
    (b.min[0] + b.max[0]) / 2,
    (b.min[1] + b.max[1]) / 2,
    (b.min[2] + b.max[2]) / 2,
  ];
  if (mode === "2d") {
    const spanX = Math.max(b.max[0] - b.min[0], MIN_SPAN);
    const spanY = Math.max(b.max[1] - b.min[1], MIN_SPAN);
    const scale = Math.min((w - 2 * PAD) / spanX, (h - 2 * PAD) / spanY);
    return { kind: "2d", cx: centre[0], cy: centre[1], scale: clamp(scale, MIN_SCALE, MAX_SCALE) };
  }
  let radius = MIN_SPAN / 2;
  for (const s of segs) {
    for (const p of [s.from, s.to]) radius = Math.max(radius, Math.hypot(...sub(p, centre)));
  }
  const def = defaultCamera("3d") as Camera3D;
  const half = Math.atan(Math.tan(FOV / 2) * Math.min(1, w / h));
  const usable = 1 - (2 * PAD) / Math.min(w, h);
  const dist = radius / Math.sin(half) / Math.max(usable, 0.5);
  return { ...def, target: centre, dist: clamp(dist, MIN_DIST, MAX_DIST) };
}

export const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));
