/** Projects the segment a–b, clipping it against the near plane. */
export function projectLine(cam: Camera, w: number, h: number, a: Vec3, b: Vec3): [Projected, Projected] | null {
  if (cam.kind === "2d") {
    const p = makeProjector(cam, w, h);
    return [p.project(a)!, p.project(b)!];
  }
  const { eye, forward } = basisOf(cam);
  const near = cam.dist * 0.02;
  const za = dot(sub(a, eye), forward);
  const zb = dot(sub(b, eye), forward);
  if (za <= near && zb <= near) return null;
  let A = a;
  let B = b;
  if (za <= near || zb <= near) {
    const t = (near + 1e-6 - za) / (zb - za);
    const m: Vec3 = [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
    if (za <= near) A = m;
    else B = m;
  }
  const p = makeProjector(cam, w, h);
  const pa = p.project(A);
  const pb = p.project(B);
  return pa && pb ? [pa, pb] : null;
}
