import type { Mode, Segment, TurtleState, Vec3 } from "../lang";
import { basisOf, clamp, makeProjector, projectLine, type Camera, type Camera2D, type Camera3D, type Projected } from "./camera";
import { TURTLE_PIECES } from "./turtle-shape";

/** The slice of CanvasRenderingContext2D the renderer uses (so tests can supply a software one). */
export interface Ctx2D {
  canvas?: unknown;
  fillStyle: string | CanvasGradient | CanvasPattern;
  strokeStyle: string | CanvasGradient | CanvasPattern;
  lineWidth: number;
  lineCap: CanvasLineCap;
  lineJoin: CanvasLineJoin;
  globalAlpha: number;
  font: string;
  textAlign: CanvasTextAlign;
  textBaseline: CanvasTextBaseline;
  save(): void;
  restore(): void;
  setTransform(a: number, b: number, c: number, d: number, e: number, f: number): void;
  clearRect(x: number, y: number, w: number, h: number): void;
  fillRect(x: number, y: number, w: number, h: number): void;
  beginPath(): void;
  moveTo(x: number, y: number): void;
  lineTo(x: number, y: number): void;
  closePath(): void;
  arc(x: number, y: number, r: number, a0: number, a1: number): void;
  stroke(): void;
  fill(): void;
  setLineDash(d: number[]): void;
  fillText(t: string, x: number, y: number): void;
}

export interface Palette {
  paper: string;
  grid: string;
  gridMajor: string;
  axis: string;
  axisX: string;
  axisY: string;
  axisZ: string;
  label: string;
  turtle: string;
  turtleEdge: string;
  accent: string;
}

/** The sheet stays light in both themes so stroke colours read the same as in the exported PNG. */
export const SHEET: Palette = {
  paper: "#fbf8ef",
  grid: "rgba(43, 70, 84, 0.10)",
  gridMajor: "rgba(43, 70, 84, 0.22)",
  axis: "#2a3b45",
  axisX: "#a45f26",
  axisY: "#0f7a60",
  axisZ: "#2a64a3",
  label: "#4a5b66",
  turtle: "#0d6a54",
  turtleEdge: "#fbf8ef",
  accent: "#c1763d",
};

export interface Scene {
  mode: Mode;
  camera: Camera;
  segments: readonly Segment[];
  turtle: TurtleState | null;
  width: number;
  height: number;
  /** device pixel ratio; 1 for exports at their own size */
  dpr?: number;
  palette?: Palette;
  showTurtle?: boolean;
  showGuides?: boolean;
}

/** Grid step (world units) so that neighbouring lines are at least `minPx` apart. */
export function niceStep(scale: number, minPx = 22): number {
  const raw = minPx / scale;
  const pow = Math.pow(10, Math.floor(Math.log10(raw)));
  for (const m of [1, 2, 5, 10]) if (m * pow >= raw) return m * pow;
  return 10 * pow;
}

export function gridStepFor(cam: Camera, h: number): number {
  if (cam.kind === "2d") return niceStep(cam.scale);
  const focal = h / 2 / Math.tan((40 * Math.PI) / 360);
  return niceStep(focal / cam.dist, 26);
}

const fmt = (n: number): string => (Math.abs(n) >= 1000 ? String(n / 1000) + "k" : String(+n.toFixed(6)));

export function drawScene(ctx: Ctx2D, scene: Scene): void {
  const pal = scene.palette ?? SHEET;
  const dpr = scene.dpr ?? 1;
  const { width: w, height: h } = scene;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.globalAlpha = 1;
  ctx.setLineDash([]);
  ctx.fillStyle = pal.paper;
  ctx.fillRect(0, 0, w, h);

  if (scene.camera.kind === "2d") draw2D(ctx, scene, scene.camera, pal);
  else draw3D(ctx, scene, scene.camera, pal);
  ctx.globalAlpha = 1;
}

function draw2D(ctx: Ctx2D, scene: Scene, cam: Camera2D, pal: Palette): void {
  const { width: w, height: h } = scene;
  const proj = makeProjector(cam, w, h);
  const step = niceStep(cam.scale);
  const x0 = cam.cx - w / 2 / cam.scale;
  const x1 = cam.cx + w / 2 / cam.scale;
  const y0 = cam.cy - h / 2 / cam.scale;
  const y1 = cam.cy + h / 2 / cam.scale;
  const origin = proj.project([0, 0, 0])!;

  if (scene.showGuides !== false) {
    ctx.lineWidth = 1;
    const line = (major: boolean, ax: number, ay: number, bx: number, by: number) => {
      ctx.strokeStyle = major ? pal.gridMajor : pal.grid;
      ctx.beginPath();
      ctx.moveTo(ax, ay);
      ctx.lineTo(bx, by);
      ctx.stroke();
    };
    for (let i = Math.ceil(x0 / step); i <= Math.floor(x1 / step); i++) {
      const px = Math.round(proj.project([i * step, 0, 0])!.x) + 0.5;
      line(i % 5 === 0, px, 0, px, h);
    }
    for (let j = Math.ceil(y0 / step); j <= Math.floor(y1 / step); j++) {
      const py = Math.round(proj.project([0, j * step, 0])!.y) + 0.5;
      line(j % 5 === 0, 0, py, w, py);
    }

    // axes through the origin
    ctx.lineWidth = 1.5;
    ctx.strokeStyle = pal.axis;
    ctx.beginPath();
    ctx.moveTo(0, origin.y);
    ctx.lineTo(w, origin.y);
    ctx.moveTo(origin.x, 0);
    ctx.lineTo(origin.x, h);
    ctx.stroke();

    ctx.font = "11px system-ui, sans-serif";
    ctx.fillStyle = pal.label;
    ctx.textBaseline = "top";
    ctx.textAlign = "center";
    const ly = clamp(origin.y + 4, 2, h - 14);
    for (let i = Math.ceil(x0 / step); i <= Math.floor(x1 / step); i++) {
      if (i % 5 !== 0 || i === 0) continue;
      ctx.fillText(fmt(i * step), proj.project([i * step, 0, 0])!.x, ly);
    }
    ctx.textAlign = origin.x > w - 40 ? "right" : "left";
    const lx = clamp(origin.x + 5, 2, w - 4);
    ctx.textBaseline = "middle";
    for (let j = Math.ceil(y0 / step); j <= Math.floor(y1 / step); j++) {
      if (j % 5 !== 0 || j === 0) continue;
      ctx.fillText(fmt(j * step), lx, proj.project([0, j * step, 0])!.y - 8);
    }
    axisLabel(ctx, "X", clamp(w - 14, 8, w), clamp(origin.y - 12, 10, h - 8), pal.axisX);
    axisLabel(ctx, "Y", clamp(origin.x + 12, 8, w - 8), 12, pal.axisY);

    // the origin: ring and cross
    ctx.strokeStyle = pal.axis;
    ctx.fillStyle = pal.paper;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(origin.x, origin.y, 4.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }

  strokeSegments(ctx, scene.segments, (p) => proj.project(p), 1);
  if (scene.turtle && scene.showTurtle !== false) drawTurtle(ctx, scene, cam, pal);
}

function axisLabel(ctx: Ctx2D, text: string, x: number, y: number, colour: string): void {
  ctx.font = "bold 12px system-ui, sans-serif";
  ctx.fillStyle = colour;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(text, x, y);
}

function draw3D(ctx: Ctx2D, scene: Scene, cam: Camera3D, pal: Palette): void {
  const { width: w, height: h } = scene;
  const proj = makeProjector(cam, w, h);
  const step = gridStepFor(cam, h);
  const extentWanted = Math.max(cam.dist * 0.7, 100);
  const extent = Math.min(Math.ceil(extentWanted / step) * step, step * 40);

