/**
 * The turtle marker: a bilaterally symmetric paper-cut figure ("wycinanka").
 * Local coordinates: a = towards the turtle's right, b = towards its heading; the figure spans b ∈ [-1.15, 1.1].
 */
export type Pt = [number, number];

export interface Piece {
  /** shell, flippers, tail: filled with the turtle colour; cut: paper showing through; head: pen colour */
  kind: "body" | "cut" | "head";
  pts: Pt[];
}

const ellipse = (cx: number, cy: number, rx: number, ry: number, rot = 0, n = 28): Pt[] => {
  const out: Pt[] = [];
  const c = Math.cos(rot);
  const s = Math.sin(rot);
  for (let i = 0; i < n; i++) {
    const t = (i / n) * Math.PI * 2;
    const x = Math.cos(t) * rx;
    const y = Math.sin(t) * ry;
    out.push([cx + x * c - y * s, cy + x * s + y * c]);
  }
  return out;
};

const mirror = (pts: Pt[]): Pt[] => pts.map(([a, b]) => [-a, b] as Pt).reverse();

const half = {
  frontFlipper: ellipse(0.66, 0.5, 0.2, 0.46, -0.9),
  rearFlipper: ellipse(0.52, -0.62, 0.16, 0.3, 0.7),
  sideCut: [[0.36, 0.3], [0.5, 0.05], [0.36, -0.2], [0.22, 0.05]] as Pt[],
};

export const TURTLE_PIECES: readonly Piece[] = [
  { kind: "body", pts: half.frontFlipper },
  { kind: "body", pts: mirror(half.frontFlipper) },
  { kind: "body", pts: half.rearFlipper },
  { kind: "body", pts: mirror(half.rearFlipper) },
  { kind: "body", pts: [[-0.13, -0.8], [0.13, -0.8], [0, -1.15]] },
  { kind: "body", pts: ellipse(0, -0.02, 0.56, 0.78) },
  { kind: "cut", pts: [[0, 0.5], [0.17, 0.26], [0, 0.02], [-0.17, 0.26]] },
  { kind: "cut", pts: [[0, -0.1], [0.17, -0.34], [0, -0.58], [-0.17, -0.34]] },
  { kind: "cut", pts: half.sideCut },
  { kind: "cut", pts: mirror(half.sideCut) },
  { kind: "head", pts: ellipse(0, 0.93, 0.2, 0.2, 0, 18) },
];
