// Renders every standard program through the real renderer into PNGs (dev aid, not shipped).
import { mkdirSync, writeFileSync } from "node:fs";
import { EXAMPLES } from "../src/core/examples";
import { initialTurtle, start } from "../src/lang";
import { fitCamera, defaultCamera } from "../src/ui/camera";
import { drawScene } from "../src/ui/render";
import { SoftCanvas } from "./softcanvas";

const out = process.argv[2] ?? "/tmp/preview";
mkdirSync(out, { recursive: true });
const W = Number(process.argv[3] ?? 640);
const H = Number(process.argv[4] ?? 440);
const only = process.argv[5];
for (const ex of EXAMPLES) {
  if (only && ex.id !== only) continue;
  const s = start(ex.source, ex.mode);
  if (!s.execution) throw new Error(ex.id);
  while (s.execution.step());
  const cv = new SoftCanvas(W, H);
  drawScene(cv, {
    mode: ex.mode,
    camera: fitCamera(ex.mode, s.execution.segments, W, H),
    segments: s.execution.segments,
    turtle: s.execution.turtle,
    width: W,
    height: H,
  });
  writeFileSync(`${out}/${ex.id}.png`, cv.toPNG());
}
if (!only) {
  const cv = new SoftCanvas(W, H);
  drawScene(cv, { mode: "2d", camera: defaultCamera("2d"), segments: [], turtle: initialTurtle(), width: W, height: H });
  writeFileSync(`${out}/_empty2d.png`, cv.toPNG());
  const c3 = new SoftCanvas(W, H);
  drawScene(c3, { mode: "3d", camera: defaultCamera("3d"), segments: [], turtle: initialTurtle(), width: W, height: H });
  writeFileSync(`${out}/_empty3d.png`, c3.toPNG());
}
