import { beforeEach, describe, expect, test } from "bun:test";
import { Window } from "happy-dom";
import { mountApp } from "../src/ui/app";
import { run } from "../src/lang";
import { SoftCanvas } from "../tools/softcanvas";

class MemoryStorage {
  data = new Map<string, string>();
  getItem(k: string) {
    return this.data.get(k) ?? null;
  }
  setItem(k: string, v: string) {
    this.data.set(k, v);
  }
  removeItem(k: string) {
    this.data.delete(k);
  }
}

interface Harness {
  win: Window;
  doc: Document;
  api: ReturnType<typeof mountApp>["api"];
  canvases: SoftCanvas[];
  storage: MemoryStorage;
}

function boot(storage = new MemoryStorage()): Harness {
  const win = new Window({ url: "https://example.org/Logomocja/builds/x/", width: 1200, height: 800 });
  const doc = win.document as unknown as Document;
  const root = doc.createElement("div");
  doc.body.appendChild(root);
  const canvases: SoftCanvas[] = [];
  const app = mountApp(root, {
    storage,
    getContext: () => {
      const c = new SoftCanvas(800, 500);
      canvases.push(c);
      return c;
    },
  });
  return { win, doc, api: app.api, canvases, storage };
}

const text = (el: Element | null) => (el?.textContent ?? "").replace(/\s+/g, " ").trim();
const q = (h: Harness, sel: string) => h.doc.querySelector(sel) as HTMLElement | null;
const button = (h: Harness, label: string) =>
  [...h.doc.querySelectorAll("button")].find((b) => text(b).startsWith(label) || b.getAttribute("aria-label")?.startsWith(label)) as
    | HTMLButtonElement
    | undefined;
const editor = (h: Harness) => q(h, "textarea[aria-label='Kod programu']") as unknown as HTMLTextAreaElement;

describe("punkt zaczepienia window.logomocja", () => {
  let h: Harness;
  beforeEach(() => {
    h = boot();
  });

  test("udostępnia version, run i open", () => {
    expect(typeof h.api.version).toBe("string");
    expect(typeof h.api.run).toBe("function");
    expect(typeof h.api.open).toBe("function");
  });

  test("run interpretuje bez ruszania interfejsu", async () => {
    const before = editor(h).value;
    const r = await h.api.run("powtorz 4 [np 50 pw 90]", "2d");
    expect(r).toEqual(run("powtorz 4 [np 50 pw 90]", "2d"));
    expect(editor(h).value).toBe(before);
  });
});

describe("open: edytor zgodny z kontraktem języka", () => {
  test("wczytuje kod do edytora, ustawia tryb, uruchamia do końca i zwraca wynik run", async () => {
    const h = boot();
    const src = "kolor \"#c1763d\"\npowtorz 3 [np 60 pw 120]";
    const r = await h.api.open(src, "2d");
    expect(r).toEqual(run(src, "2d"));
    expect(r.segments).toHaveLength(3);
    expect(editor(h).value).toBe(src);
    expect(q(h, "[role=radio][aria-checked=true]")?.textContent).toContain("2D");
    expect(text(q(h, "[data-role=status]"))).toContain("Zakończono");
  });

  test("po open rysunek jest na płótnie: w miejscu odcinka są piksele w kolorze pisaka", async () => {
    const h = boot();
    await h.api.open("kolor \"#c1763d\" grubosc 6 np 100", "2d");
    const cv = h.canvases[h.canvases.length - 1];
    let found = 0;
    for (let y = 0; y < cv.height; y += 2) {
      for (let x = 0; x < cv.width; x += 2) {
        const [r, g, b, a] = cv.pixel(x, y);
        if (a === 255 && Math.abs(r - 0xc1) < 8 && Math.abs(g - 0x76) < 8 && Math.abs(b - 0x3d) < 8) found++;
      }
    }
    expect(found).toBeGreaterThan(40);
  });

  test("przełącza tryb przy kolejnych wywołaniach i zwraca wyniki 3D", async () => {
    const h = boot();
    const r3 = await h.api.open("gora 90 np 50", "3d");
    expect(r3.segments[0].to).toEqual([0, 0, 50]);
    expect(q(h, "[role=radio][aria-checked=true]")?.textContent).toContain("3D");
    const r2 = await h.api.open("np 10", "2d");
    expect(r2.segments).toHaveLength(1);
    expect(q(h, "[role=radio][aria-checked=true]")?.textContent).toContain("2D");
  });

  test("błąd parsowania: nic nie jest rysowane, jest znacznik w linii i kolumnie oraz komunikat po polsku", async () => {
    const h = boot();
    const r = await h.api.open("np 10\n  np iks", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 2, column: 6 });
    const marker = q(h, "[data-role=error-marker]")!;
    expect(marker).not.toBeNull();
    expect(marker.getAttribute("data-line")).toBe("2");
    expect(marker.getAttribute("data-column")).toBe("6");
    expect(text(q(h, "[data-role=error-message]"))).toContain("linia 2");
    expect(text(q(h, "[data-role=error-message]"))).toContain("iks");
  });

  test("błąd wykonania zachowuje rysunek i też jest oznaczony", async () => {
    const h = boot();
    const r = await h.api.open("np 10\nnp 1 / 0", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
    expect(q(h, "[data-role=error-marker]")?.getAttribute("data-line")).toBe("2");
  });

  test("powtórne open nie kumuluje rysunku, a poprawny program usuwa stary znacznik błędu", async () => {
    const h = boot();
    await h.api.open("np 10 np iks", "2d");
    const ok = await h.api.open("np 10", "2d");
    expect(ok.error).toBeNull();
    expect(q(h, "[data-role=error-marker]")).toBeNull();
    const again = await h.api.open("np 10", "2d");
    expect(again.segments).toHaveLength(1);
    expect(text(q(h, "[data-role=segment-count]"))).toContain("1");
  });

  test("edycja w polu tekstowym unieważnia wynik: błąd jest odświeżany po uruchomieniu przyciskiem", async () => {
    const h = boot();
    await h.api.open("np 10", "2d");
    const ta = editor(h);
    ta.value = "np 10\nnp 5 / 0";
    ta.dispatchEvent(new h.win.Event("input", { bubbles: true }) as unknown as Event);
    button(h, "Uruchom")!.click();
    // animacja jest na zegarze; „Reset” kasuje rysunek i błąd, zostawiając kod
    button(h, "Reset")!.click();
    expect(editor(h).value).toBe("np 10\nnp 5 / 0");
    expect(q(h, "[data-role=error-marker]")).toBeNull();
    expect(text(q(h, "[data-role=segment-count]"))).toContain("0");
  });

  test("open nie niszczy niezapisanego szkicu: poprzedni kod trafia do kopii roboczych", async () => {
    const h = boot();
    const ta = editor(h);
    ta.value = "np 77 ; moje";
    ta.dispatchEvent(new h.win.Event("input", { bubbles: true }) as unknown as Event);
    await h.api.open("np 1", "2d");
    const saved = JSON.parse(h.storage.getItem("logomocja.workspace.v1")!);
    expect(saved.backups.map((b: { source: string }) => b.source)).toContain("np 77 ; moje");
  });

  test("szkic przetrwa przeładowanie: nowa instancja aplikacji na tym samym storage ma ten sam kod", async () => {
    const storage = new MemoryStorage();
    const a = boot(storage);
    const ta = editor(a);
    ta.value = "np 123";
    ta.dispatchEvent(new a.win.Event("input", { bubbles: true }) as unknown as Event);
    const b = boot(storage);
    expect(editor(b).value).toBe("np 123");
  });
});
EOF
