type Child = Node | string | null | undefined | false;
type Attrs = Record<string, string | number | boolean | null | undefined | ((e: Event) => void)>;

/** Tiny hyperscript helper bound to one document (the app never touches globals). */
export function create(doc: Document) {
  function el<K extends keyof HTMLElementTagNameMap>(tag: K, attrs?: Attrs | null, ...children: Child[]): HTMLElementTagNameMap[K];
  function el(tag: string, attrs?: Attrs | null, ...children: Child[]): HTMLElement;
  function el(tag: string, attrs?: Attrs | null, ...children: Child[]): HTMLElement {
    const node = doc.createElement(tag);
    if (attrs) {
      for (const [k, v] of Object.entries(attrs)) {
        if (v === null || v === undefined || v === false) continue;
        if (typeof v === "function") node.addEventListener(k.replace(/^on/, "").toLowerCase(), v);
        else if (k === "class") node.className = String(v);
        else node.setAttribute(k, v === true ? "" : String(v));
      }
    }
    for (const c of children) {
      if (c === null || c === undefined || c === false) continue;
      node.appendChild(typeof c === "string" ? doc.createTextNode(c) : c);
    }
    return node;
  }
  return el;
}

export type El = ReturnType<typeof create>;

export function clear(node: Node): void {
  while (node.firstChild) node.removeChild(node.firstChild);
}

export const escapeHtml = (s: string): string =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
