import { create } from "./dom";
import { highlight } from "./highlight";

export interface EditorError {
  line: number;
  column: number;
  message: string;
}

export interface Editor {
  el: HTMLElement;
  textarea: HTMLTextAreaElement;
  getValue(): string;
  /** Replaces the text without firing onInput. */
  setValue(text: string): void;
  setError(error: EditorError | null): void;
  setExecLine(line: number | null): void;
  /** Moves the caret to a 1-based position and brings it into view. */
  goTo(line: number, column: number): void;
  focus(): void;
}

const TAB = 2;

/** Visual column (tab stops of 2) of the 1-based character column on a line. */
export function visualColumn(lineText: string, column: number): number {
  let v = 0;
  for (let k = 0; k < column - 1 && k < lineText.length; k++) {
    v += lineText[k] === "\t" ? TAB - (v % TAB) : 1;
  }
  return v + Math.max(0, column - 1 - lineText.length);
}

const TOKEN_AT = /^(?:[\p{L}\p{N}_:.]+|"[^"\n]*"?|.)/u;

export function createEditor(doc: Document, onInput: (value: string) => void): Editor {
  const el = create(doc);
  const gutter = el("div", { class: "gutter", "aria-hidden": "true" });
  const pre = el("pre", { class: "hl", "aria-hidden": "true" });
  const layer = el("div", { class: "marks", "aria-hidden": "true" });
  const textarea = el("textarea", {
    class: "code-input",
    "aria-label": "Kod programu",
    "aria-describedby": "editor-help",
    spellcheck: "false",
    autocapitalize: "off",
    autocomplete: "off",
    autocorrect: "off",
    wrap: "off",
    rows: 1,
  });
  const code = el("div", { class: "code" }, pre, layer, textarea);
  const scroll = el("div", { class: "editor-scroll" }, el("div", { class: "editor-body" }, gutter, code));
  const root = el(
    "div",
    { class: "editor", "data-role": "editor" },
    scroll,
    el("p", { id: "editor-help", class: "sr-only" }, "Edytor programu Logo. Numery linii są po lewej. Skróty klawiszowe znajdziesz w oknie Skróty."),
  );

  let execLine: number | null = null;
  let error: EditorError | null = null;
  let lineCount = 0;

  const execBar = el("div", { class: "line-mark exec", "data-role": "exec-line" });
  const errBar = el("div", { class: "line-mark err" });
  const squiggle = el("div", { class: "squiggle", "data-role": "error-marker", role: "img" });

  const lines = () => textarea.value.split(/\r\n|\r|\n/);

  const renderGutter = (count: number) => {
    if (count === lineCount) return;
    lineCount = count;
    gutter.style.setProperty("--digits", String(String(count).length));
    gutter.textContent = "";
    for (let n = 1; n <= count; n++) {
      gutter.appendChild(el("div", { class: "ln", "data-line": n }, String(n)));
    }
    markGutter();
  };

  const markGutter = () => {
    for (const child of Array.from(gutter.children)) {
      const n = Number((child as HTMLElement).getAttribute("data-line"));
      child.classList.toggle("is-exec", n === execLine);
      child.classList.toggle("is-err", error !== null && n === error.line);
    }
  };

  const renderMarks = () => {
    layer.textContent = "";
    markGutter();
    if (execLine !== null) {
      execBar.style.setProperty("--line", String(execLine - 1));
      layer.appendChild(execBar);
    }
    if (error) {
      errBar.style.setProperty("--line", String(error.line - 1));
      layer.appendChild(errBar);
      const text = lines()[error.line - 1] ?? "";
      const tok = TOKEN_AT.exec(text.slice(error.column - 1))?.[0] ?? " ";
      const start = visualColumn(text, error.column);
      const end = visualColumn(text, error.column + Math.max(1, tok.length));
      squiggle.style.setProperty("--line", String(error.line - 1));
      squiggle.style.setProperty("--col", String(start));
      squiggle.style.setProperty("--len", String(Math.max(1, end - start)));
      squiggle.setAttribute("data-line", String(error.line));
      squiggle.setAttribute("data-column", String(error.column));
      squiggle.setAttribute("aria-label", `Błąd: ${error.message}`);
      squiggle.setAttribute("title", error.message);
      layer.appendChild(squiggle);
    }
  };

  const sync = () => {
    const text = textarea.value;
    pre.innerHTML = highlight(text) + "\n ";
    const ls = lines();
    renderGutter(ls.length);
    let widest = 0;
    for (const l of ls) widest = Math.max(widest, visualColumn(l, l.length + 1));
    code.style.setProperty("--cols", String(widest + 2));
    code.style.setProperty("--rows", String(ls.length + 1));
    renderMarks();
  };

  const reveal = (line: number, column = 1) => {
    const lh = parseFloat(getComputedStyleSafe(root, "--lh")) || 22;
    const top = (line - 1) * lh;
    const h = scroll.clientHeight;
    if (h > 0) {
      if (top < scroll.scrollTop) scroll.scrollTop = Math.max(0, top - lh);
      else if (top + lh * 2 > scroll.scrollTop + h) scroll.scrollTop = top + lh * 2 - h;
    }
    void column;
  };

  const insert = (text: string) => {
    const exec = (doc as Document & { execCommand?: (c: string, u: boolean, v: string) => boolean }).execCommand;
    if (typeof exec === "function" && exec.call(doc, "insertText", false, text)) return;
    const { selectionStart: s, selectionEnd: e } = textarea;
    textarea.setRangeText(text, s, e, "end");
    textarea.dispatchEvent(new (doc.defaultView as Window & typeof globalThis).Event("input", { bubbles: true }));
  };

  textarea.addEventListener("input", () => {
    sync();
    onInput(textarea.value);
  });

  textarea.addEventListener("keydown", (e) => {
    if (e.key !== "Enter" || e.ctrlKey || e.metaKey || e.altKey || e.shiftKey || e.isComposing) return;
    const { selectionStart: s, selectionEnd: end, value } = textarea;
    if (s !== end) return;
    const lineStart = value.lastIndexOf("\n", s - 1) + 1;
    const before = value.slice(lineStart, s);
    const indent = /^[ \t]*/.exec(before)![0];
    const code = before.replace(/;.*$/, "").trimEnd();
    const deeper = /\[$/.test(code) || (/^\s*(oto|to)\b/i.test(code) && !/\b(już|juz|end)\s*$/i.test(code));
    e.preventDefault();
    insert("\n" + indent + (deeper ? "  " : ""));
  });

  textarea.addEventListener("keyup", (e) => {
    // dedent a lone closing bracket or "już" typed on an indented line
    void e;
  });

  sync();

  return {
    el: root,
    textarea,
    getValue: () => textarea.value,
    setValue(text) {
      textarea.value = text;
      sync();
    },
    setError(next) {
      error = next;
      renderMarks();
    },
    setExecLine(line) {
      if (line === execLine) return;
      execLine = line;
      renderMarks();
      if (line !== null) reveal(line);
    },
    goTo(line, column) {
      const ls = lines();
      let pos = 0;
      for (let k = 0; k < line - 1 && k < ls.length; k++) pos += ls[k].length + 1;
      pos += Math.min(Math.max(0, column - 1), (ls[line - 1] ?? "").length);
      textarea.focus();
      textarea.setSelectionRange(pos, pos);
      reveal(line, column);
    },
    focus: () => textarea.focus(),
  };
}

function getComputedStyleSafe(node: HTMLElement, prop: string): string {
  const view = node.ownerDocument.defaultView;
  try {
    return view?.getComputedStyle(node).getPropertyValue(prop) ?? "";
  } catch {
    return "";
  }
}
