cat > src/ui/viewport.ts <<'EOF'
import type { Mode, Segment, TurtleState } from "../lang";
import {
  MAX_DIST, MAX_PITCH, MAX_SCALE, MIN_DIST, MIN_SCALE, FOV,
  basisOf, boundsOf, clamp, defaultCamera, fitCamera, makeProjector, type Camera, type Camera3D,
} from "./camera";
import { create } from "./dom";
import { drawScene, gridStepFor, niceStep, type Ctx2D, type Scene } from "./render";

export interface ViewportDeps {
  getContext?: (canvas: HTMLCanvasElement) => Ctx2D | null;
  /** schedules a paint; defaults to requestAnimationFrame */
  raf?: (cb: () => void) => unknown;
}

export interface Viewport {
  el: HTMLElement;
  canvas: HTMLCanvasElement;
  /** false when the browser gave no 2D canvas; `unavailableReason` then says why */
  available: boolean;
  unavailableReason: string;
  setMode(mode: Mode): void;
  setScene(s: { segments: readonly Segment[]; turtle: TurtleState | null; ghost?: readonly Segment[] | null }): void;
  fit(): void;
  resetView(): void;
  zoomBy(factor: number): void;
  /** Re-fits only if something drawn or the turtle is outside the frame and the user has not moved the view. */
  keepInView(): void;
  /** Call when a new run begins: the view follows the drawing again. */
  followAgain(): void;
  renderNow(): void;
  toPNG(): Promise<Blob | null>;
  describe(): string;
  size(): { w: number; h: number };
}

export function createViewport(doc: Document, deps: ViewportDeps = {}): Viewport {
  const el = create(doc);
  const win = doc.defaultView!;
  const canvas = el("canvas", {
    class: "stage-canvas",
    tabindex: 0,
    role: "img",
    "aria-label": "Rysunek",
    "aria-describedby": "view-help",
  });
  const hint = el("div", { class: "empty-hint", "data-role": "empty-hint" },
    el("strong", null, "Tu pojawi się rysunek."),
    el("span", null, "Napisz program i naciśnij Uruchom (Ctrl+Enter) albo wczytaj przykład."),
  );
  const note = el("div", { class: "scale-note", "data-role": "scale-note" });
  const unavailable = el("div", { class: "unavailable", role: "status", hidden: true });
  const help = el("p", { id: "view-help", class: "sr-only" },
    "Rysunek. Strzałki przesuwają lub obracają widok, plus i minus przybliżają, 0 dopasowuje widok do rysunku.");
  const stage = el("div", { class: "stage", "data-role": "stage" }, canvas, hint, note, unavailable, help);

  const ctx = (deps.getContext ?? ((c: HTMLCanvasElement) => c.getContext("2d") as unknown as Ctx2D | null))(canvas);
  const available = ctx !== null;
  const reason = "Przeglądarka nie udostępniła płótna 2D (canvas), więc podgląd rysunku jest wyłączony. Edytor i interpreter nadal działają. Widok 3D też jest wyłączony, bo korzysta z tego samego płótna.";
  if (!available) {
    unavailable.hidden = false;
    unavailable.textContent = reason;
  }

  let mode: Mode = "2d";
  const cameras: Record<Mode, Camera> = { "2d": defaultCamera("2d"), "3d": defaultCamera("3d") };
  let segments: readonly Segment[] = [];
  let turtle: TurtleState | null = null;
  let ghost: readonly Segment[] | null = null;
  let userMoved = false;
  let cssW = 0;
  let cssH = 0;
  let dpr = 1;
  let queued = false;

  const measure = () => {
    const w = canvas.clientWidth || stage.clientWidth || 800;
    const h = canvas.clientHeight || stage.clientHeight || 500;
    dpr = Math.max(1, Math.min(3, win.devicePixelRatio || 1));
    if (w !== cssW || h !== cssH) {
      cssW = w;
      cssH = h;
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
    }
  };

  const scene = (over: Partial<Scene> = {}): Scene => ({
    mode,
    camera: cameras[mode],
    segments,
    turtle,
    ghost: ghost ?? undefined,
    width: cssW,
    height: cssH,
    dpr,
    ...over,
  });

  const updateNote = () => {
    const cam = cameras[mode];
    const step = cam.kind === "2d" ? niceStep(cam.scale) : gridStepFor(cam, cssH);
    note.textContent = `Kratka: ${step} jedn.`;
    hint.hidden = segments.length > 0;
  };

  const describe = () => {
    const t = turtle;
    const where = t ? ` Żółw: x ${r1(t.pos[0])}, y ${r1(t.pos[1])}${mode === "3d" ? `, z ${r1(t.pos[2])}` : ""}.` : "";
    return `Rysunek ${mode === "2d" ? "płaski" : "przestrzenny"}: ${segments.length} odcinków.${where}`;
  };

  const render = () => {
    queued = false;
    measure();
    updateNote();
    canvas.setAttribute("aria-label", describe());
    if (ctx) drawScene(ctx, scene());
  };

  const invalidate = () => {
    if (queued) return;
    queued = true;
    const raf = deps.raf ?? ((cb: () => void) => (win.requestAnimationFrame ? win.requestAnimationFrame(cb) : win.setTimeout(cb, 16)));
    raf(render);
  };

  const moved = () => {
    userMoved = true;
    invalidate();
  };

  const fit = () => {
    measure();
    cameras[mode] = fitCamera(mode, segments, cssW, cssH, cameras[mode]);
    invalidate();
  };

  // --- interaction ---------------------------------------------------------------------------
  const pan3D = (cam: Camera3D, dx: number, dy: number): Camera3D => {
    const { right, up } = basisOf(cam);
    const perPx = (2 * cam.dist * Math.tan(FOV / 2)) / Math.max(cssH, 1);
    return {
      ...cam,
      target: [
        cam.target[0] - right[0] * dx * perPx + up[0] * dy * perPx,
        cam.target[1] - right[1] * dx * perPx + up[1] * dy * perPx,
        cam.target[2] - right[2] * dx * perPx + up[2] * dy * perPx,
      ],
    };
  };

  const pan = (dx: number, dy: number) => {
    const cam = cameras[mode];
    if (cam.kind === "2d") cameras["2d"] = { ...cam, cx: cam.cx - dx / cam.scale, cy: cam.cy + dy / cam.scale };
    else cameras["3d"] = pan3D(cam, dx, dy);
  };

  const orbit = (dx: number, dy: number) => {
