import { create } from "./dom";
import { icon } from "./icons";

export interface DialogAction {
  label: string;
  value: string;
  primary?: boolean;
}

export interface Overlays {
  /** Opens a modal dialog and resolves with the chosen action's value (or "cancel" on Esc/close). */
  dialog(opts: { title: string; body: Node; actions?: DialogAction[]; wide?: boolean; id?: string }): Promise<string>;
  toast(message: string, action?: { label: string; run: () => void }): void;
  toastRegion: HTMLElement;
}

export function createOverlays(doc: Document): Overlays {
  const el = create(doc);
  const win = doc.defaultView!;
  const toastRegion = el("div", { class: "toasts", role: "status", "aria-live": "polite", "data-role": "toast" });
  let toastTimer: number | undefined;

  const toast: Overlays["toast"] = (message, action) => {
    toastRegion.textContent = "";
    const item = el("div", { class: "toast" }, el("span", null, message));
    if (action) {
      const b = el("button", { type: "button", class: "btn btn-quiet" }, action.label);
      b.addEventListener("click", () => {
        action.run();
        toastRegion.textContent = "";
      });
      item.appendChild(b);
    }
    const close = el("button", { type: "button", class: "icon-btn", "aria-label": "Zamknij komunikat" }, icon(doc, "close", 16));
    close.addEventListener("click", () => (toastRegion.textContent = ""));
    item.appendChild(close);
    toastRegion.appendChild(item);
    win.clearTimeout(toastTimer);
    toastTimer = win.setTimeout(() => (toastRegion.textContent = ""), action ? 14000 : 7000);
  };

  const dialog: Overlays["dialog"] = ({ title, body, actions = [], wide, id }) =>
    new Promise((resolve) => {
      const dlg = el("dialog", { class: wide ? "dialog wide" : "dialog", "aria-labelledby": "dlg-title-" + (id ?? "x") }) as HTMLDialogElement;
      const head = el("div", { class: "dialog-head" },
        el("h2", { id: "dlg-title-" + (id ?? "x") }, title),
      );
      const closeBtn = el("button", { type: "button", class: "icon-btn", "aria-label": "Zamknij okno" }, icon(doc, "close", 18));
      head.appendChild(closeBtn);
      const foot = el("div", { class: "dialog-foot" });
      let result = "cancel";
      const finish = (v: string) => {
        result = v;
        if (typeof dlg.close === "function") dlg.close();
        else dlg.removeAttribute("open");
        done();
      };
      let finished = false;
      const done = () => {
        if (finished) return;
        finished = true;
        dlg.remove();
        resolve(result);
      };
      for (const a of actions) {
        const b = el("button", { type: "button", class: a.primary ? "btn btn-primary" : "btn" }, a.label);
        b.addEventListener("click", () => finish(a.value));
        foot.appendChild(b);
      }
      closeBtn.addEventListener("click", () => finish("cancel"));
      dlg.addEventListener("close", done);
      dlg.addEventListener("cancel", () => {
        result = "cancel";
      });
      dlg.append(head, el("div", { class: "dialog-body" }, body));
      if (actions.length) dlg.appendChild(foot);
      doc.body.appendChild(dlg);
      if (typeof dlg.showModal === "function") dlg.showModal();
      else dlg.setAttribute("open", "");
      const first = (dlg.querySelector("[data-autofocus]") ?? dlg.querySelector(".btn-primary") ?? closeBtn) as HTMLElement;
      first.focus();
    });

  return { dialog, toast, toastRegion };
}
EOF
