import { challengeById, checkChallenge, type Challenge } from "../core/challenges";
import type { Controller, ControllerState } from "../core/controller";
import { exampleById } from "../core/examples";
import { buildPermalink, logoFileText, readLogoText, suggestedFileName, usesSpatialCommands } from "../core/share";
import type { Workspace } from "../core/workspace";
import { run, type Mode, type RunResult, type Segment } from "../lang";
import { create } from "./dom";
import { createEditor } from "./editor";
import { icon } from "./icons";
import type { Overlays } from "./overlays";
import type { Viewport } from "./viewport";

export const SPEEDS = [1, 2, 5, 10, 20, 50, 100, 300, 1000, 5000, 20000];
const SPEED_LABELS = SPEEDS.map((s, i) => (i === SPEEDS.length - 1 ? "maks." : `${s} kr./s`));
const STATUS_TEXT: Record<ControllerState["status"], string> = {
  idle: "Gotowy",
  running: "Działa",
  paused: "Wstrzymano",
  finished: "Zakończono",
  error: "Błąd",
};

export interface StudioDeps {
  doc: Document;
  workspace: Workspace;
  controller: Controller;
  viewport: Viewport;
  overlays: Overlays;
  navigate(hash: string): void;
}

export interface Studio {
  el: HTMLElement;
  modeSwitch: HTMLElement;
  /** Puts a program in the editor as if pasted (unsaved work goes to the backups), then runs it to the end. */
  open(source: string, mode: Mode, label: string): Promise<RunResult>;
  openExample(id: string): Promise<boolean>;
  bindChallenge(id: string | null): void;
  /** Call when the studio becomes visible again. */
  show(): void;
  showShortcuts(): void;
  isChallenge(): boolean;
  exportPng(): Promise<void>;
}

export function createStudio(d: StudioDeps): Studio {
  const { doc, workspace, controller, viewport, overlays } = d;
  const el = create(doc);
  const win = doc.defaultView!;

  let challenge: Challenge | null = null;
  let ghostOn = false;

  const currentMode = (): Mode => (challenge ? challenge.mode : workspace.getState().mode);
  const currentText = (): string => (challenge ? workspace.getChallengeDraft(challenge.id) : workspace.getState().draft);
  const storeText = (text: string) => (challenge ? workspace.setChallengeDraft(challenge.id, text) : workspace.setDraft(text));

  // --- editor ---------------------------------------------------------------------------------
  const editor = createEditor(doc, (text) => {
    storeText(text);
    controller.setSource(text);
    editor.setError(null);
    errorRegion.hidden = true;
    resultRegion.hidden = true;
    refresh();
  });

  // --- mode switch (placed in the top bar by the app) -----------------------------------------
  const modeButtons = (["2d", "3d"] as const).map((m) => {
    const b = el("button", { type: "button", role: "radio", class: "seg-btn", "data-mode": m, "aria-checked": "false", tabindex: -1 }, m === "2d" ? "2D" : "3D");
    b.addEventListener("click", () => setMode(m));
    b.addEventListener("keydown", (e) => {
      const keys = ["ArrowRight", "ArrowDown", "ArrowLeft", "ArrowUp"];
      if (!keys.includes(e.key)) return;
      e.preventDefault();
      const next = m === "2d" ? "3d" : "2d";
      setMode(next);
      modeButtons.find((x) => x.getAttribute("data-mode") === next)?.focus();
    });
    return b;
  });
  const modeSwitch = el("div", { class: "seg", role: "radiogroup", "aria-label": "Tryb rysowania" }, ...modeButtons);

  const renderModeSwitch = () => {
    const mode = currentMode();
    for (const b of modeButtons) {
      const on = b.getAttribute("data-mode") === mode;
      b.setAttribute("aria-checked", String(on));
      b.tabIndex = on ? 0 : -1;
      const off3d = b.getAttribute("data-mode") === "3d" && !viewport.available;
      b.disabled = off3d || challenge !== null;
      b.title = off3d
        ? viewport.unavailableReason
        : challenge
          ? "Tryb wyzwania jest ustalony przez zadanie."
          : b.getAttribute("data-mode") === "2d"
            ? "Rysowanie na płaszczyźnie"
            : "Rysowanie w przestrzeni";
    }
  };

  // --- controls ---------------------------------------------------------------------------------
  const btn = (label: string, iconName: string, cls = "btn", keys = "", title = "") => {
    const b = el("button", { type: "button", class: cls, "aria-keyshortcuts": keys || null, title: title || (keys ? `${label} (${keys.replace("Control", "Ctrl")})` : label) },
      icon(doc, iconName, 18), el("span", { class: "btn-label" }, label));
    return b;
  };
  const runBtn = btn("Uruchom", "play", "btn btn-primary", "Control+Enter");
  const stepBtn = btn("Krok", "step", "btn", "Alt+Enter");
  const pauseBtn = btn("Pauza", "pause", "btn", "Alt+P");
  const resetBtn = btn("Reset", "reset", "btn", "Alt+R");

  const speedInput = el("input", { type: "range", min: 0, max: SPEEDS.length - 1, step: 1, id: "speed", "aria-describedby": "speed-out" }) as HTMLInputElement;
  const speedOut = el("output", { id: "speed-out", for: "speed", class: "speed-out" });
  const savedSpeed = Number(workspace.getPref("speed"));
  speedInput.value = String(Number.isInteger(savedSpeed) && savedSpeed >= 0 && savedSpeed < SPEEDS.length ? savedSpeed : 4);
  const applySpeed = () => {
    const i = Number(speedInput.value);
    controller.setSpeed(SPEEDS[i]);
    speedOut.textContent = SPEED_LABELS[i];
    speedInput.setAttribute("aria-valuetext", SPEED_LABELS[i]);
    workspace.setPref("speed", String(i));
  };
  speedInput.addEventListener("input", applySpeed);
  const controls = el("div", { class: "controls", role: "group", "aria-label": "Sterowanie wykonaniem" },
    runBtn, stepBtn, pauseBtn, resetBtn,
    el("div", { class: "speed" }, el("label", { for: "speed" }, "Prędkość"), speedInput, speedOut),
  );

  const startRun = () => {
    resultRegion.hidden = true;
    viewport.followAgain();
    controller.run();
  };
  const startStep = () => {
    if (controller.getState().status !== "paused" || controller.getState().stale) viewport.followAgain();
    controller.step();
  };
  const togglePause = () => {
    const s = controller.getState();
    if (s.status === "running") controller.pause();
    else if (s.status === "paused") controller.resume();
  };
  runBtn.addEventListener("click", startRun);
  stepBtn.addEventListener("click", startStep);
  pauseBtn.addEventListener("click", togglePause);
  resetBtn.addEventListener("click", () => {
    controller.reset();
    editor.setError(null);
    errorRegion.hidden = true;
    resultRegion.hidden = true;
  });

  // --- file actions ----------------------------------------------------------------------------
  const fileInput = el("input", { type: "file", accept: ".logo,.txt,text/plain", class: "sr-only", tabindex: -1, "aria-hidden": "true" }) as HTMLInputElement;
  const openBtn = btn("Otwórz", "upload", "btn btn-quiet", "", "Otwórz plik .logo");
  const saveBtn = btn("Pobierz", "download", "btn btn-quiet", "", "Pobierz program jako plik .logo");
  const shareBtn = btn("Link", "link", "btn btn-quiet", "", "Skopiuj link do programu");
  const backupBtn = btn("Kopie", "history", "btn btn-quiet", "", "Kopie robocze: poprzednie wersje programu");
  const backupCount = el("span", { class: "count", "data-role": "backup-count" });
  backupBtn.appendChild(backupCount);
  openBtn.addEventListener("click", () => fileInput.click());
  fileInput.addEventListener("change", async () => {
    const file = fileInput.files?.[0];
    fileInput.value = "";
    if (!file) return;
    if (file.size > 200_000) return overlays.toast("Plik jest za duży: program może mieć najwyżej 50 000 znaków.");
    const text = readLogoText(await file.text());
    const mode: Mode = usesSpatialCommands(text) ? "3d" : currentMode();
    await loadIntoEditor(text, mode, file.name, true);
  });
  saveBtn.addEventListener("click", () => {
    const blob = new win.Blob([logoFileText(editor.getValue())], { type: "text/plain;charset=utf-8" });
    download(blob, challenge ? `${challenge.id}.logo` : suggestedFileName(currentMode()));
  });
  shareBtn.addEventListener("click", async () => {
    const url = buildPermalink(win.location.href, { source: editor.getValue(), mode: currentMode() });
    const input = el("input", { type: "text", readonly: true, class: "share-url", "aria-label": "Link do programu", "data-autofocus": "" }) as HTMLInputElement;
    input.value = url;
    const note = el("p", { class: "muted" }, url.length > 8000
      ? "Ten link jest bardzo długi; niektóre komunikatory mogą go uciąć. Rozważ pobranie pliku .logo."
      : "Link zawiera cały program i tryb. Kto go otworzy, zobaczy uruchomiony rysunek.");
    let copied = false;
    try {
      await win.navigator.clipboard.writeText(url);
      copied = true;
    } catch {
      /* clipboard unavailable: the dialog shows the link to copy by hand */
    }
    if (copied) overlays.toast("Skopiowano link do programu.");
    await overlays.dialog({
      title: copied ? "Link skopiowany" : "Link do programu",
      body: el("div", null, input, note),
      actions: [{ label: "Gotowe", value: "ok", primary: true }],
      id: "share",
    });
  });
  backupBtn.addEventListener("click", showBackups);

  const download = (blob: Blob, name: string) => {
    const url = win.URL.createObjectURL(blob);
    const a = el("a", { href: url, download: name, class: "sr-only" });
    doc.body.appendChild(a);
    a.click();
    a.remove();
    win.setTimeout(() => win.URL.revokeObjectURL(url), 2000);
  };

  async function showBackups() {
    const list = workspace.getState().backups;
    const body = el("div", null);
    if (list.length === 0) {
      body.appendChild(el("p", { class: "muted" }, "Brak kopii. Gdy wczytasz przykład, plik lub link, a w edytorze są niezapisane zmiany, poprzednia wersja trafi tutaj."));
    } else {
      const ul = el("ul", { class: "backup-list" });
      list.forEach((b, i) => {
        const first = b.source.split("\n").find((l) => l.trim()) ?? "(pusty program)";
        const btnR = el("button", { type: "button", class: "btn", "data-index": i }, "Przywróć");
        btnR.addEventListener("click", () => {
          workspace.restoreBackup(i);
          overlays.toast("Przywrócono kopię.");
          syncFromWorkspace();
          (btnR.closest("dialog") as HTMLDialogElement | null)?.close();
        });
        ul.appendChild(el("li", null,
          el("div", { class: "backup-meta" },
            el("strong", null, `${b.mode.toUpperCase()} · ${b.label}`),
            el("span", { class: "muted" }, new Date(b.at).toLocaleString("pl-PL")),
            el("code", null, first.length > 60 ? first.slice(0, 60) + "…" : first)),
          btnR));
      });
      body.appendChild(ul);
    }
    await overlays.dialog({ title: "Kopie robocze", body, actions: [{ label: "Zamknij", value: "ok", primary: true }], id: "backups", wide: true });
  }

  const fileTools = el("div", { class: "tools", role: "toolbar", "aria-label": "Plik i udostępnianie" }, openBtn, saveBtn, shareBtn, backupBtn, fileInput);

  // --- view tools -------------------------------------------------------------------------------
  const tool = (label: string, iconName: string, run: () => void, keys = "") => {
    const b = el("button", { type: "button", class: "icon-btn", "aria-label": label, title: keys ? `${label} (${keys})` : label }, icon(doc, iconName, 18));
    b.addEventListener("click", run);
    return b;
  };
  const ghostBtn = el("button", { type: "button", class: "btn btn-quiet", "aria-pressed": "false", hidden: true, title: "Pokaż lub ukryj wzór" }, icon(doc, "eye", 18), el("span", { class: "btn-label" }, "Wzór"));
  ghostBtn.addEventListener("click", () => {
    ghostOn = !ghostOn;
    refresh();
  });
  const viewTools = el("div", { class: "tools", role: "toolbar", "aria-label": "Narzędzia widoku" },
    ghostBtn,
    tool("Dopasuj widok do rysunku", "fit", () => viewport.fit(), "0"),
    tool("Widok początkowy", "home", () => viewport.resetView(), "Home"),
    tool("Przybliż", "plus", () => viewport.zoomBy(1.25), "+"),
    tool("Oddal", "minus", () => viewport.zoomBy(0.8), "−"),
    tool("Pobierz rysunek jako PNG", "image", () => void exportPng()),
  );

  async function exportPng() {
    const blob = await viewport.toPNG();
    if (!blob) return overlays.toast("Nie udało się utworzyć obrazu PNG w tej przeglądarce.");
    download(blob, `logomocja-${currentMode()}.png`);
  }

  // --- regions ---------------------------------------------------------------------------------
  const errorMsg = el("span", { "data-role": "error-message" });
  const gotoBtn = el("button", { type: "button", class: "btn btn-quiet" }, "Pokaż w kodzie");
  const errorRegion = el("div", { class: "error-region", role: "alert", hidden: true }, icon(doc, "alert", 18), errorMsg, gotoBtn);
  gotoBtn.addEventListener("click", () => {
    const e = controller.getState().error;
    if (e) editor.goTo(e.line, e.column);
  });

  const resultRegion = el("div", { class: "result-region", role: "status", hidden: true, "data-role": "challenge-result" });
  const challengeTitle = el("h2", { class: "challenge-title" });
  const challengeBrief = el("p", { class: "challenge-brief" });
  const checkBtn = el("button", { type: "button", class: "btn btn-primary" }, icon(doc, "check", 18), el("span", { class: "btn-label" }, "Sprawdź rozwiązanie"));
  const hintBtn = el("button", { type: "button", class: "btn", "aria-expanded": "false" }, icon(doc, "lightbulb", 18), el("span", { class: "btn-label" }, "Podpowiedź"));
  const solutionBtn = el("button", { type: "button", class: "btn btn-quiet" }, "Pokaż rozwiązanie wzorcowe");
  const hintText = el("p", { class: "hint", hidden: true });
  const backLink = el("a", { href: "#/wyzwania", class: "btn btn-quiet" }, "Wszystkie wyzwania");
  const challengeBar = el("section", { class: "challenge-bar", "aria-label": "Wyzwanie", hidden: true, "data-role": "challenge-bar" },
    challengeTitle, challengeBrief,
    el("div", { class: "challenge-actions" }, checkBtn, hintBtn, solutionBtn, backLink),
    hintText);

  checkBtn.addEventListener("click", () => {
    if (!challenge) return;
    const source = editor.getValue();
    const r = checkChallenge(challenge, source);
    workspace.recordChallenge(challenge.id, r.passed, source);
    controller.setSource(source);
    controller.runInstant();
    viewport.fit();
    resultRegion.hidden = false;
    resultRegion.className = "result-region " + (r.passed ? "pass" : "fail");
    resultRegion.textContent = "";
    resultRegion.append(icon(doc, r.passed ? "check" : "alert", 18), el("span", null, (r.passed ? "Zaliczone! " : "Jeszcze nie. ") + r.reason));
    renderChallengeBar();
  });
  hintBtn.addEventListener("click", () => {
    const open = hintText.hidden;
    hintText.hidden = !open;
    hintBtn.setAttribute("aria-expanded", String(open));
  });
  solutionBtn.addEventListener("click", async () => {
    if (!challenge) return;
    const body = el("div", null, el("p", null, "Rozwiązanie wzorcowe pokazuje gotową odpowiedź. Twój program zostanie zachowany w kopiach roboczych."),
      el("pre", { class: "solution" }, challenge.solution));
    const choice = await overlays.dialog({ title: "Rozwiązanie wzorcowe", body, actions: [{ label: "Anuluj", value: "cancel" }, { label: "Wstaw do edytora", value: "insert", primary: true }], id: "solution" });
    if (choice === "insert" && challenge) {
      const mine = editor.getValue();
      if (mine.trim() && mine !== challenge.starter) workspace.loadExternal(mine, challenge.mode, "wyzwanie: poprzednia wersja"); // keeps the old text in backups
      workspace.setChallengeDraft(challenge.id, challenge.solution);
      applyDoc(false);
    }
  });

  const renderChallengeBar = () => {
    challengeBar.hidden = challenge === null;
    ghostBtn.hidden = challenge === null;
    if (!challenge) return;
    const p = workspace.getState().progress[challenge.id];
    challengeTitle.textContent = challenge.title + (p?.solved ? " · zaliczone" : "");
    challengeBrief.textContent = challenge.brief;
    hintText.textContent = challenge.hint;
  };

  // --- layout -----------------------------------------------------------------------------------
  const tabLabel = (text: string) => el("span", { class: "panel-tab" }, text);
  const editorPanel = el("section", { class: "panel editor-panel", id: "panel-code", "aria-label": "Program" },
    el("header", { class: "panel-head" }, tabLabel("Program"), fileTools),
    challengeBar,
    editor.el,
    errorRegion,
    resultRegion,
    controls,
  );
  const viewPanel = el("section", { class: "panel view-panel", id: "panel-view", "aria-label": "Rysunek" },
    el("header", { class: "panel-head" }, tabLabel("Rysunek"), viewTools),
    viewport.el,
  );

  const statusLabel = el("span", { class: "status-main", "data-role": "status" });
  const statusStale = el("span", { class: "status-stale", hidden: true }, "kod zmieniony: rysunek jest nieaktualny");
  const posOut = el("span", { class: "num", "data-role": "turtle-pos" });
  const stepsOut = el("span", { class: "num", "data-role": "step-count" });
  const segOut = el("span", { class: "num", "data-role": "segment-count" });
  const lineOut = el("span", { class: "num", "data-role": "line-col" });
  const statusBar = el("footer", { class: "statusbar" },
    el("div", { class: "status-left", "aria-live": "off" }, statusLabel, statusStale),
    el("div", { class: "status-right" }, lineOut, stepsOut, segOut, posOut));

  const tabs = (["code", "view"] as const).map((k) => {
    const b = el("button", { type: "button", role: "tab", class: "tab", id: `tab-${k}`, "aria-controls": k === "code" ? "panel-code" : "panel-view", "aria-selected": "false", tabindex: -1 }, k === "code" ? "Kod" : "Rysunek");
    b.addEventListener("click", () => setPane(k));
    b.addEventListener("keydown", (e) => {
      if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
        e.preventDefault();
        const next = k === "code" ? "view" : "code";
        setPane(next);
        tabs.find((t) => t.id === `tab-${next}`)?.focus();
      }
    });
    return b;
  });
  const tabBar = el("div", { class: "pane-tabs", role: "tablist", "aria-label": "Widok pracowni" }, ...tabs);
  let pane: "code" | "view" = "code";
  const setPane = (p: "code" | "view") => {
    pane = p;
    root.setAttribute("data-pane", p);
    for (const t of tabs) {
      const on = t.id === `tab-${p}`;
      t.setAttribute("aria-selected", String(on));
      t.tabIndex = on ? 0 : -1;
    }
    if (p === "view") viewport.renderNow();
  };

  const root = el("div", { class: "studio", "data-pane": "code" }, tabBar, el("div", { class: "studio-panels" }, editorPanel, viewPanel), statusBar);

  // --- state to DOM -----------------------------------------------------------------------------
  function refresh() {
    const s = controller.getState();
    statusLabel.textContent = STATUS_TEXT[s.status];
    statusLabel.setAttribute("data-state", s.status);
    statusStale.hidden = !(s.stale && s.status !== "idle");
    stepsOut.textContent = `Kroki: ${s.steps}`;
    segOut.textContent = `Odcinki: ${s.segments.length}`;
    posOut.textContent = formatTurtle(s);
    lineOut.textContent = s.currentLine !== null ? `Linia ${s.currentLine}:${s.currentColumn}` : "";
    backupCount.textContent = String(workspace.getState().backups.length || "");
    backupBtn.setAttribute("aria-label", `Kopie robocze (${workspace.getState().backups.length})`);

    const live = s.status === "running" || s.status === "paused";
    editor.setExecLine(live ? s.currentLine : null);
    if (s.status === "error" && s.error && !s.stale) {
      editor.setError(s.error);
      errorMsg.textContent = `Błąd (linia ${s.error.line}, kolumna ${s.error.column}): ${s.error.message}`;
      errorRegion.hidden = false;
    }

    const paused = s.status === "paused" && !s.stale;
    const label = pauseBtn.querySelector(".btn-label")!;
    label.textContent = paused ? "Wznów" : "Pauza";
    const ic = pauseBtn.querySelector("svg");
    if (ic) ic.replaceWith(icon(doc, paused ? "play" : "pause", 18));
    pauseBtn.setAttribute("aria-label", paused ? "Wznów" : "Pauza");
    pauseBtn.disabled = !(s.status === "running" || paused);
    resetBtn.disabled = s.status === "idle";
    runBtn.setAttribute("aria-busy", String(s.status === "running"));

    ghostBtn.setAttribute("aria-pressed", String(ghostOn));
    const ghost = challenge && ghostOn ? run(challenge.solution, challenge.mode).segments : null;
    viewport.setScene({ segments: s.segments, turtle: s.status === "idle" && s.segments.length === 0 ? s.turtle : s.turtle, ghost });
    if (s.status === "running" || s.status === "paused") viewport.keepInView();
    if (s.status === "finished" || s.status === "error") viewport.keepInView();
    viewport.renderNow();
  }

  const formatTurtle = (s: ControllerState) => {
    const [x, y, z] = s.turtle.pos.map((v) => Math.round(v * 10) / 10);
    const angle = Math.round(((Math.atan2(s.turtle.h[0], s.turtle.h[1]) * 180) / Math.PI + 360) % 360);
    return s.mode === "3d" ? `x ${x} y ${y} z ${z}` : `x ${x} y ${y} · kierunek ${angle}°`;
  };

  controller.subscribe(refresh);

  /** Loads the current document (workshop draft or challenge draft) into editor, controller and viewport. */
  function applyDoc(resetRun = true) {
    const mode = currentMode();
    editor.setValue(currentText());
    editor.setError(null);
    errorRegion.hidden = true;
    controller.setMode(mode);
    controller.setSource(currentText());
    if (resetRun) controller.reset();
    viewport.setMode(mode);
    renderModeSwitch();
    renderChallengeBar();
    refresh();
  }

  function setMode(mode: Mode) {
    if (challenge || mode === workspace.getState().mode) return;
    workspace.setMode(mode);
    applyDoc();
    viewport.fit();
  }

  /** Re-reads everything after the workspace changed behind the editor's back (examples, backups). */
  function syncFromWorkspace() {
    applyDoc();
  }

  async function loadIntoEditor(source: string, mode: Mode, label: string, announce: boolean): Promise<RunResult> {
    if (challenge) {
      // leaving challenge context: the program opens in the workshop
      challenge = null;
      d.navigate("#/pracownia");
    }
    const before = workspace.getState().backups.length;
    workspace.loadExternal(source, mode, label);
    applyDoc();
    controller.runInstant();
    viewport.followAgain();
    viewport.fit();
    refresh();
    if (announce && workspace.getState().backups.length > before) {
      overlays.toast("Poprzednia wersja programu została zachowana w kopiach roboczych.", {
        label: "Cofnij",
        run: () => {
          workspace.restoreBackup(0);
          syncFromWorkspace();
        },
      });
    }
    const s = controller.getState();
    return { segments: s.segments.map(copySegment), error: s.error };
  }

  async function openExample(id: string): Promise<boolean> {
    const ex = exampleById(id);
    if (!ex) return false;
    let res = workspace.loadExample(id);
    if (res.status === "needs-confirmation") {
      const choice = await overlays.dialog({
        title: "Zastąpić niezapisany program?",
        body: el("div", null,
          el("p", null, `W trybie ${ex.mode.toUpperCase()} masz zmiany, których nie ma w żadnym przykładzie. Wczytanie przykładu „${ex.title}” zastąpi je.`),
          el("p", { class: "muted" }, "Poprzednia wersja zostanie zachowana w kopiach roboczych i możesz ją przywrócić.")),
        actions: [
          { label: "Anuluj", value: "cancel" },
          { label: "Zastąp i zachowaj kopię", value: "replace", primary: true },
        ],
        id: "replace",
      });
      if (choice !== "replace") return false;
      res = workspace.loadExample(id, { replace: true });
    }
    if (res.status !== "loaded") return false;
    challenge = null;
    d.navigate("#/pracownia");
    applyDoc();
    controller.runInstant();
    viewport.followAgain();
    viewport.fit();
    refresh();
    overlays.toast(`Wczytano przykład „${ex.title}”.`);
    return true;
  }

  function bindChallenge(id: string | null) {
    const c = id ? (challengeById(id) ?? null) : null;
    if (c === challenge) return;
    challenge = c;
    ghostOn = false;
    resultRegion.hidden = true;
    hintText.hidden = true;
    hintBtn.setAttribute("aria-expanded", "false");
    applyDoc();
    viewport.fit();
  }

  // --- shortcuts ---------------------------------------------------------------------------------
  const SHORTCUTS: [string, string][] = [
    ["Ctrl + Enter", "Uruchom program od początku"],
    ["Alt + Enter", "Wykonaj jeden krok (podświetla bieżącą linię)"],
    ["Alt + P", "Wstrzymaj lub wznów"],
    ["Alt + R", "Reset: wyczyść rysunek, zachowaj kod"],
    ["?", "Pokaż ten spis (poza edytorem)"],
    ["Strzałki", "Przesuń widok (2D) lub obracaj kamerę (3D); z Shift przesuwaj"],
    ["+  /  −", "Przybliż / oddal rysunek"],
    ["0", "Dopasuj widok do rysunku"],
    ["Home", "Widok początkowy"],
    ["Mysz", "Przeciągnij: przesuwanie (2D) lub obrót (3D); Shift lub prawy przycisk: przesuwanie; kółko: zoom"],
    ["Dotyk", "Jeden palec: przesuwanie lub obrót; dwa palce: zoom i przesuwanie"],
  ];
  function showShortcuts() {
    const dl = el("dl", { class: "shortcuts" });
    for (const [k, v] of SHORTCUTS) dl.append(el("dt", null, el("kbd", null, k)), el("dd", null, v));
    return void overlays.dialog({
      title: "Skróty klawiszowe",
      body: dl,
      actions: [{ label: "Zamknij", value: "ok", primary: true }],
      id: "keys",
      wide: true,
    });
  }

  const onKey = (e: KeyboardEvent) => {
    if (root.hidden || e.defaultPrevented) return;
    if (doc.querySelector("dialog[open]")) return;
    const target = e.target as HTMLElement | null;
    const typing = !!target && (target.tagName === "TEXTAREA" || target.tagName === "INPUT" || target.isContentEditable);
    if (e.key === "Enter" && (e.ctrlKey || e.metaKey) && !e.altKey) {
      e.preventDefault();
      startRun();
    } else if (e.altKey && !e.ctrlKey && !e.metaKey) {
      const k = e.key.toLowerCase();
      if (e.key === "Enter") {
        e.preventDefault();
        startStep();
      } else if (k === "p") {
        e.preventDefault();
        togglePause();
      } else if (k === "r") {
        e.preventDefault();
        resetBtn.click();
      }
    } else if (e.key === "?" && !typing) {
      e.preventDefault();
      showShortcuts();
    }
  };
  win.addEventListener("keydown", onKey);

  applySpeed();
  setPane("code");
  applyDoc();

  return {
    el: root,
    modeSwitch,
    open: (source, mode, label) => loadIntoEditor(source, mode, label, true),
    openExample,
    bindChallenge,
    show() {
      renderModeSwitch();
      viewport.renderNow();
    },
    showShortcuts,
    isChallenge: () => challenge !== null,
    exportPng,
  };
}

const copySegment = (s: Segment): Segment => ({ from: [...s.from], to: [...s.to], color: s.color, width: s.width });

