import type { Mode } from "../lang";

/** Text with `code` spans written in backticks. */
export type Text = string;

export interface DocExample {
  code: string;
  mode: Mode;
  /** what to expect */
  note?: Text;
}

export interface CommandDoc {
  id: string;
  names: string[];
  english: string[];
  arg: string;
  summary: Text;
  mode: "2D i 3D" | "tylko 3D";
  example: DocExample;
}

export type Block =
  | { t: "p"; text: Text }
  | { t: "ul"; items: Text[] }
  | { t: "example"; ex: DocExample }
  | { t: "table"; head: string[]; rows: Text[][] }
  | { t: "commands"; ids: string[] };

export interface DocSection {
  id: string;
  title: string;
  blocks: Block[];
}

export const COMMAND_DOCS: CommandDoc[] = [
  {
    id: "np", names: ["np", "naprzod", "naprzód"], english: ["fd", "forward"], arg: "wyrażenie (odległość)", mode: "2D i 3D",
    summary: "Przesuwa żółwia do przodu o podaną odległość. Przy opuszczonym piórze rysuje odcinek w bieżącym kolorze i grubości. Ruch o zero niczego nie rysuje.",
    example: { code: "np 100", mode: "2d", note: "Pionowa kreska długości 100: żółw zaczyna w punkcie (0, 0) i patrzy w górę ekranu." },
  },
  {
    id: "ws", names: ["ws", "wstecz"], english: ["bk", "back"], arg: "wyrażenie (odległość)", mode: "2D i 3D",
    summary: "Cofa żółwia: to samo co `np` z odległością ze zmienionym znakiem. Kierunek żółwia się nie zmienia.",
    example: { code: "np 100\nws 40", mode: "2d", note: "Druga komenda cofa się po tej samej linii." },
  },
  {
    id: "pw", names: ["pw", "prawo"], english: ["rt", "right"], arg: "wyrażenie (stopnie)", mode: "2D i 3D",
    summary: "Obraca żółwia w prawo o podaną liczbę stopni (zgodnie z ruchem wskazówek zegara, gdy patrzysz z góry). Kąt może być ułamkiem; ujemny kąt obraca w lewo.",
    example: { code: "powtorz 4 [np 80 pw 90]", mode: "2d", note: "Kwadrat o boku 80." },
  },
  {
    id: "lw", names: ["lw", "lewo"], english: ["lt", "left"], arg: "wyrażenie (stopnie)", mode: "2D i 3D",
    summary: "Obraca żółwia w lewo o podaną liczbę stopni.",
    example: { code: "powtorz 3 [np 90 lw 120]", mode: "2d", note: "Trójkąt równoboczny skręcany w lewo." },
  },
  {
    id: "pod", names: ["pod", "podnies", "podnieś"], english: ["pu", "penup"], arg: "brak", mode: "2D i 3D",
    summary: "Podnosi pióro: żółw się porusza, ale nie zostawia śladu. Pióro zostaje podniesione, dopóki go nie opuścisz.",
    example: { code: "np 40\npod\nnp 40\nopu\nnp 40", mode: "2d", note: "Dwie kreski przedzielone przerwą." },
  },
  {
    id: "opu", names: ["opu", "opusc", "opuść"], english: ["pd", "pendown"], arg: "brak", mode: "2D i 3D",
    summary: "Opuszcza pióro: kolejne ruchy znowu rysują. Na początku programu pióro jest opuszczone.",
    example: { code: "pod np 30 opu np 30", mode: "2d" },
  },
  {
    id: "kolor", names: ["kolor"], english: ["color"], arg: "kolor w cudzysłowie: \"#rrggbb\"", mode: "2D i 3D",
    summary: "Ustawia kolor pióra. Kolor to napis z sześciu cyfr szesnastkowych (wielkość liter nie ma znaczenia). Domyślny kolor to `\"#16866a\"`.",
    example: { code: "kolor \"#c1763d\"\nnp 60\nkolor \"#2b6fb3\"\nnp 60", mode: "2d" },
  },
  {
    id: "grubosc", names: ["grubosc", "grubość"], english: ["width"], arg: "wyrażenie: liczba całkowita 1–12", mode: "2D i 3D",
    summary: "Ustawia grubość linii. Wartość spoza zakresu 1–12 albo niecałkowita jest błędem. Domyślna grubość to 3.",
    example: { code: "grubosc 1\nnp 40\ngrubosc 6\nnp 40", mode: "2d" },
  },
  {
    id: "powtorz", names: ["powtorz", "powtórz"], english: ["repeat"], arg: "wyrażenie: liczba całkowita 0–10000, potem [ ciało ]", mode: "2D i 3D",
    summary: "Wykonuje ciało w nawiasach kwadratowych podaną liczbę razy. Zero oznacza, że ciało nie wykona się wcale. Pętle można zagnieżdżać.",
    example: { code: "powtorz 5 [np 120 pw 144]", mode: "2d", note: "Pięcioramienna gwiazda." },
  },
  {
    id: "niech", names: ["niech"], english: ["let"], arg: "nazwa, potem wyrażenie", mode: "2D i 3D",
    summary: "Nadaje zmiennej wartość wyrażenia; kolejne `niech` z tą samą nazwą zmienia wartość. Nazwa nie może być słowem-poleceniem ani nazwą procedury.",
    example: { code: "niech bok 50\npowtorz 4 [np bok pw 90]\nniech bok bok * 2\npowtorz 4 [np bok pw 90]", mode: "2d", note: "Dwa kwadraty: drugi dwa razy większy." },
  },
  {
    id: "jesli", names: ["jeśli", "jesli"], english: ["if"], arg: "warunek, potem [ ciało ]", mode: "2D i 3D",
    summary: "Wykonuje ciało tylko wtedy, gdy warunek jest prawdziwy. Warunek to dwa wyrażenia i znak porównania: `<` `>` `=` `<=` `>=` `<>`.",
    example: { code: "powtorz 8 [\n  np 20\n  jeśli nrpowt > 4 [pw 45]\n]", mode: "2d" },
  },
  {
    id: "jezeli", names: ["jeżeli", "jezeli"], english: ["ifelse"], arg: "warunek, potem [ ciało ] [ ciało inaczej ]", mode: "2D i 3D",
    summary: "Wykonuje pierwsze ciało, gdy warunek zachodzi, a w przeciwnym razie drugie. Oba ciała są obowiązkowe.",
    example: { code: "powtorz 6 [\n  jeżeli nrpowt < 4 [kolor \"#16866a\"] [kolor \"#c1763d\"]\n  np 40\n  pw 60\n]", mode: "2d" },
  },
  {
    id: "stop", names: ["stop"], english: ["stop"], arg: "brak", mode: "2D i 3D",
    summary: "Kończy bieżące wywołanie procedury. Na najwyższym poziomie kończy cały program. `stop` wewnątrz `powtorz` lub `jeśli` kończy całą procedurę, a nie tylko ciało.",
    example: { code: "np 50\nstop\nnp 50", mode: "2d", note: "Rysuje tylko pierwszą kreskę." },
  },
  {
    id: "dom", names: ["dom"], english: ["home"], arg: "brak", mode: "2D i 3D",
    summary: "Odsyła żółwia do punktu (0, 0, 0) i przywraca początkowy kierunek. Gdy pióro jest opuszczone, a żółw nie był na miejscu, rysuje odcinek powrotu. Kolor, grubość i stan pióra się nie zmieniają.",
    example: { code: "np 80\npw 90\nnp 50\ndom", mode: "2d", note: "Ostatnia linia ciągnie przekątną z powrotem do początku." },
  },
  {
    id: "czysc", names: ["czyść", "czysc"], english: ["cs", "clearscreen"], arg: "brak", mode: "2D i 3D",
    summary: "Usuwa z ekranu wszystkie narysowane dotąd odcinki. Pozycja, kierunek i ustawienia żółwia zostają.",
    example: { code: "np 100\nczyść\npw 90\nnp 50", mode: "2d", note: "Zostaje tylko druga kreska." },
  },
  {
    id: "gora", names: ["gora", "góra"], english: ["pitchup"], arg: "wyrażenie (stopnie)", mode: "tylko 3D",
    summary: "Unosi nos żółwia o podaną liczbę stopni w stronę jego „góry”. Po `gora 90` żółw patrzy tam, gdzie wcześniej była jego góra. W trybie 2D to błąd.",
    example: { code: "np 50\ngora 90\nnp 50", mode: "3d", note: "Najpierw kreska do przodu, potem pionowo w górę." },
  },
  {
    id: "dol", names: ["dol", "dół"], english: ["pitchdown"], arg: "wyrażenie (stopnie)", mode: "tylko 3D",
    summary: "Opuszcza nos żółwia (przeciwnie do `gora`).",
    example: { code: "np 50\ndol 90\nnp 50", mode: "3d" },
  },
  {
    id: "pp", names: ["pp", "przechylprawo"], english: ["rr", "rollright"], arg: "wyrażenie (stopnie)", mode: "tylko 3D",
    summary: "Przechyla żółwia w prawo wokół jego kierunku: „góra” żółwia obraca się ku jego prawej stronie. Kierunek ruchu się nie zmienia, ale zmieniają się późniejsze `pw`, `gora` i `dol`.",
    example: { code: "pp 90\ngora 90\nnp 60", mode: "3d", note: "Po przechyleniu o 90° „góra” żółwia to dawna prawa strona, więc `gora 90` prowadzi w bok." },
  },
  {
    id: "pl", names: ["pl", "przechyllewo"], english: ["rl", "rollleft"], arg: "wyrażenie (stopnie)", mode: "tylko 3D",
    summary: "Przechyla żółwia w lewo wokół jego kierunku (przeciwnie do `pp`).",
    example: { code: "pl 90\ngora 90\nnp 60", mode: "3d" },
  },
];

export const DOC_SECTIONS: DocSection[] = [
  {
    id: "start",
    title: "Zaczynamy",
    blocks: [
      { t: "p", text: "Logomocja to pracownia grafiki żółwia. Piszesz program z poleceń dla żółwia: idź naprzód, skręć, podnieś pióro. Żółw rysuje to, co mu każesz." },
      { t: "p", text: "Żółw startuje w punkcie (0, 0, 0), patrzy w górę ekranu (kierunek +Y), ma opuszczone pióro, kolor `#16866a` i grubość 3." },
      { t: "ul", items: [
        "Układ jest prawoskrętny: +X w prawo, +Y do przodu (w górę ekranu), +Z w górę, ponad kartkę.",
        "Tryb 2D rysuje na płaszczyźnie XY (z = 0). Tryb 3D rysuje w przestrzeni i dodaje polecenia `gora`, `dol`, `pp`, `pl`.",
