import type { Mode } from "../lang";

/** Text with `code` spans written in backticks. */
export type Text = string;

export interface DocExample {
  code: string;
  mode: Mode;
  /** what to expect */
  note?: Text;
}

export interface CommandDoc {
  id: string;
  names: string[];
  english: string[];
  arg: string;
  summary: Text;
  mode: "2D i 3D" | "tylko 3D";
  example: DocExample;
}

export type Block =
  | { t: "p"; text: Text }
  | { t: "ul"; items: Text[] }
  | { t: "example"; ex: DocExample }
  | { t: "table"; head: string[]; rows: Text[][] }
  | { t: "commands"; ids: string[] };

export interface DocSection {
  id: string;
  title: string;
  blocks: Block[];
}

export const COMMAND_DOCS: CommandDoc[] = [
