import { ALL_DOC_EXAMPLES, COMMAND_DOCS, DOC_SECTIONS, type Block, type DocExample, type Text } from "./docs-data";
import { create, escapeHtml } from "./dom";
import { highlight } from "./highlight";
import { icon } from "./icons";
import { drawScene, type Ctx2D } from "./render";
import type { Studio } from "./studio";

export interface PageDeps {
  doc: Document;
  workspace: Workspace;
  studio: Studio;
  getContext?: (canvas: HTMLCanvasElement) => Ctx2D | null;
  navigate(hash: string): void;
}

const THUMB_W = 280;
const THUMB_H = 190;

function thumbnail(d: PageDeps, source: string, mode: Mode): HTMLElement {
  const el = create(d.doc);
  const canvas = el("canvas", { class: "thumb", width: THUMB_W * 2, height: THUMB_H * 2, "aria-hidden": "true" });
  const ctx = (d.getContext ?? ((c: HTMLCanvasElement) => c.getContext("2d") as unknown as Ctx2D | null))(canvas);
  if (ctx) {
    const segs = run(source, mode).segments;
    drawScene(ctx, {
      mode,
      camera: fitCamera(mode, segs, THUMB_W, THUMB_H),
      segments: segs,
      turtle: initialTurtle(),
      width: THUMB_W,
      height: THUMB_H,
      dpr: 2,
      showTurtle: false,
      showGuides: false,
    });
  }
  return canvas;
}

const badge = (el: ReturnType<typeof create>, mode: Mode) =>
  el("span", { class: `badge badge-${mode}`, title: mode === "2d" ? "Rysunek płaski" : "Rysunek przestrzenny" }, mode === "2d" ? "2D" : "3D");

/** Examples gallery. */
export function renderExamples(d: PageDeps): HTMLElement {
  const el = create(d.doc);
  let filter: "all" | Mode = "all";
  const grid = el("ul", { class: "example-grid" });
  const filters = el("div", { class: "seg", role: "group", "aria-label": "Filtr trybu" });

  const draw = () => {
    grid.textContent = "";
    for (const ex of EXAMPLES.filter((e) => filter === "all" || e.mode === filter)) {
      const load = el("button", { type: "button", class: "btn btn-primary", "data-example": ex.id }, icon(d.doc, "play", 18), el("span", { class: "btn-label" }, `Wczytaj „${ex.title}”`));
      load.addEventListener("click", () => void d.studio.openExample(ex.id));
      grid.appendChild(el("li", { class: "example-card" },
        thumbnail(d, ex.source, ex.mode),
        el("div", { class: "example-body" },
          el("div", { class: "example-head" }, el("h3", null, ex.title), badge(el, ex.mode)),
          el("p", null, ex.blurb),
          load)));
    }
  };

  for (const [value, label] of [["all", "Wszystkie"], ["2d", "2D"], ["3d", "3D"]] as const) {
    const b = el("button", { type: "button", class: "seg-btn", "aria-pressed": String(filter === value) }, label);
    b.addEventListener("click", () => {
      filter = value;
      for (const x of Array.from(filters.children)) x.setAttribute("aria-pressed", String(x === b));
      draw();
    });
    filters.appendChild(b);
  }
  draw();

  return el("div", { class: "page" },
    el("header", { class: "page-head" },
      el("h1", null, "Przykłady"),
      el("p", { class: "lede" }, "Trzynaście gotowych programów. Wczytaj dowolny, uruchom go i zmieniaj liczby, żeby zobaczyć, co się stanie. Jeśli masz w edytorze niezapisane zmiany, zapytamy o zgodę i zachowamy kopię."),
      filters),
    grid);
}

/** Challenge list. */
export function renderChallenges(d: PageDeps): HTMLElement {
  const el = create(d.doc);
  const progress = d.workspace.getState().progress;
  const solved = CHALLENGES.filter((c) => progress[c.id]?.solved).length;
  const list = el("ol", { class: "challenge-list" });
  for (const c of CHALLENGES) {
    const p = progress[c.id];
    const status = p?.solved
      ? el("span", { class: "status-chip done" }, icon(d.doc, "check", 16), "Zaliczone")
      : p?.attempts
        ? el("span", { class: "status-chip tried" }, icon(d.doc, "pencil", 16), `Próby: ${p.attempts}`)
        : el("span", { class: "status-chip todo" }, "Do zrobienia");
    const go = el("a", { href: `#/wyzwania/${c.id}`, class: p?.solved ? "btn" : "btn btn-primary", "data-challenge": c.id }, p?.attempts ? "Wróć do zadania" : "Zacznij");
    list.appendChild(el("li", { class: "challenge-row" },
      thumbnail(d, c.solution, c.mode),
      el("div", { class: "challenge-info" },
        el("div", { class: "example-head" }, el("h3", null, c.title), badge(el, c.mode), status),
        el("p", null, c.brief),
        go)));
  }
  const meter = el("meter", { min: 0, max: CHALLENGES.length, value: solved, "aria-label": "Postęp wyzwań" });
  return el("div", { class: "page" },
    el("header", { class: "page-head" },
      el("h1", null, "Wyzwania"),
      el("p", { class: "lede" }, "Każde zadanie pokazuje, co narysować. Piszesz program, a Logomocja porównuje twój rysunek ze wzorem. Liczy się kształt i położenie, nie sposób zapisu. Postęp zapamiętujemy w tej przeglądarce."),
      el("p", { class: "progress-line", "data-role": "challenge-progress" }, meter, el("span", null, `Zaliczone: ${solved} z ${CHALLENGES.length}`))),
    list);
}

/** Renders `text` with `code` spans. */
function rich(el: ReturnType<typeof create>, text: Text): Node[] {
  return text.split(/(`[^`]+`)/).filter(Boolean).map((part) =>
    part.startsWith("`") ? el("code", null, part.slice(1, -1)) : (el("span", null, part) as Node),
  );
}

function codeBlock(d: PageDeps, ex: DocExample, label = "Wypróbuj w pracowni"): HTMLElement {
  const el = create(d.doc);
  const pre = el("pre", { class: "code-sample" });
  const code = el("code");
  code.innerHTML = highlight(ex.code);
  pre.appendChild(code);
  const tryIt = el("button", { type: "button", class: "btn btn-quiet", "data-try": "" }, icon(d.doc, "play", 16), el("span", { class: "btn-label" }, label));
  tryIt.addEventListener("click", () => void d.studio.open(ex.code, ex.mode, "przykład z dokumentacji"));
  return el("div", { class: "sample" },
    pre,
    el("div", { class: "sample-foot" }, el("span", { class: "badge badge-" + ex.mode }, ex.mode.toUpperCase()), ex.note ? el("span", { class: "muted" }, ...rich(el, ex.note)) : null, tryIt));
}

/** Command reference (Polish documentation of the whole dialect). */
export function renderReference(d: PageDeps, anchor?: string): HTMLElement {
  const el = create(d.doc);
  const content = el("div", { class: "doc" });

  const renderBlock = (b: Block): Node => {
    switch (b.t) {
      case "p":
        return el("p", null, ...rich(el, b.text));
      case "ul":
        return el("ul", null, ...b.items.map((i) => el("li", null, ...rich(el, i))));
      case "example":
        return codeBlock(d, b.ex);
      case "table":
        return el("div", { class: "table-wrap" }, el("table", null,
          el("thead", null, el("tr", null, ...b.head.map((h) => el("th", { scope: "col" }, h)))),
          el("tbody", null, ...b.rows.map((r) => el("tr", null, ...r.map((c) => el("td", null, ...rich(el, c))))))));
      case "commands":
        return el("div", { class: "commands" }, ...b.ids.map((id) => {
          const c = COMMAND_DOCS.find((x) => x.id === id)!;
          return el("article", { class: "command", id: `cmd-${c.id}` },
            el("h3", null,
              el("span", { class: "cmd-names" }, ...c.names.map((n, i) => el("code", { class: i === 0 ? "primary" : "" }, n))),
              el("span", { class: "cmd-en" }, c.english.join(", ")),
              el("span", { class: "badge " + (c.mode === "tylko 3D" ? "badge-3d" : "badge-both") }, c.mode)),
            el("p", { class: "cmd-arg" }, el("strong", null, "Argument: "), c.arg),
            el("p", null, ...rich(el, c.summary)),
            codeBlock(d, c.example));
        }));
    }
  };

  const toc = el("nav", { class: "toc", "aria-label": "Spis treści dokumentacji" }, el("h2", null, "Spis treści"));
  const tocList = el("ul");
  for (const s of DOC_SECTIONS) {
    tocList.appendChild(el("li", null, el("a", { href: `#/polecenia/${s.id}` }, s.title)));
    content.appendChild(el("section", { class: "doc-section", id: `sec-${s.id}`, "aria-labelledby": `h-${s.id}` },
      el("h2", { id: `h-${s.id}` }, s.title),
      ...s.blocks.map(renderBlock)));
  }
  toc.appendChild(tocList);
  const page = el("div", { class: "page page-doc" },
    el("header", { class: "page-head" },
      el("h1", null, "Polecenia i język"),
      el("p", { class: "lede" }, `Pełny opis języka Logomocji: ${COMMAND_DOCS.length} poleceń, wyrażenia, zmienne, warunki, procedury i limity. Przykłady (${ALL_DOC_EXAMPLES.length}) można uruchomić jednym kliknięciem.`)),
    el("div", { class: "doc-layout" }, toc, content));
  if (anchor) {
    queueMicrotask(() => d.doc.getElementById(`sec-${anchor}`)?.scrollIntoView?.());
  }
  void escapeHtml;
  return page;
}

