  const themeBtn = el("button", { type: "button", class: "icon-btn", "data-role": "theme-toggle" });
  const applyTheme = () => {
    if (theme === "auto") doc.documentElement.removeAttribute("data-theme");
    else doc.documentElement.setAttribute("data-theme", theme);
    themeBtn.textContent = "";
    themeBtn.appendChild(icon(doc, theme === "auto" ? "auto" : theme === "light" ? "sun" : "moon", 20));
    themeBtn.setAttribute("aria-label", `Motyw: ${THEME_LABEL[theme]}. Naciśnij, aby zmienić.`);
    themeBtn.title = `Motyw: ${THEME_LABEL[theme]}`;
  };
  themeBtn.addEventListener("click", () => {
    theme = THEMES[(THEMES.indexOf(theme) + 1) % THEMES.length];
    workspace.setPref("theme", theme);
    applyTheme();
  });
  applyTheme();

  // --- shell ------------------------------------------------------------------------------------
  const navItems: [string, string, string][] = [
    ["studio", "#/pracownia", "Pracownia"],
    ["examples", "#/przyklady", "Przykłady"],
    ["challenges", "#/wyzwania", "Wyzwania"],
    ["reference", "#/polecenia", "Polecenia"],
  ];
  const navLinks = navItems.map(([key, href, label]) => el("a", { href, class: "nav-link", "data-nav": key }, label));
  const shortcutsBtn = el("button", { type: "button", class: "icon-btn", "aria-label": "Skróty klawiszowe", title: "Skróty klawiszowe (?)" }, icon(doc, "keyboard", 20));
  shortcutsBtn.addEventListener("click", () => studio.showShortcuts());
  const modeWrap = el("div", { class: "mode-wrap" }, studio.modeSwitch);

  const header = el("header", { class: "topbar" },
    el("a", { href: "#/pracownia", class: "brand", "aria-label": "Logomocja: pracownia" }, icon(doc, "turtle", 26), el("span", null, "Logomocja")),
    modeWrap,
    el("nav", { class: "nav", "aria-label": "Sekcje" }, ...navLinks),
    el("div", { class: "topbar-tools" }, shortcutsBtn, themeBtn));

  const pageHost = el("div", { class: "page-host", hidden: true });
  const main = el("main", { id: "main", class: "main", tabindex: -1 }, studio.el, pageHost);
  const skip = el("a", { href: "#main", class: "skip-link" }, "Przejdź do treści");
  skip.addEventListener("click", (e) => {
    e.preventDefault();
    main.focus();
  });
  const shell = el("div", { class: "app-shell" }, skip, header, main, overlays.toastRegion);
  root.appendChild(shell);

  // --- routing ----------------------------------------------------------------------------------
  const TITLES: Record<string, string> = { studio: "Pracownia", examples: "Przykłady", challenges: "Wyzwania", challenge: "Wyzwanie", reference: "Polecenia", permalink: "Pracownia", example: "Pracownia" };
  const pageDeps = { doc, workspace, studio, getContext: deps.getContext, navigate };

  const showStudio = () => {
    studio.el.hidden = false;
    pageHost.hidden = true;
    pageHost.textContent = "";
    modeWrap.hidden = false;
    studio.show();
  };
  const showPage = (node: HTMLElement) => {
    studio.el.hidden = true;
    modeWrap.hidden = true;
    pageHost.hidden = false;
    pageHost.textContent = "";
    pageHost.appendChild(node);
  };

  let routing = false;
  const applyRoute = async () => {
    if (routing) return;
    routing = true;
    try {
      const route = parseRoute(win.location.hash);
      const key = route.name === "challenge" ? "challenges" : route.name === "permalink" || route.name === "example" ? "studio" : route.name;
      for (const a of navLinks) {
        if (a.getAttribute("data-nav") === key) a.setAttribute("aria-current", "page");
        else a.removeAttribute("aria-current");
      }
      doc.title = `${TITLES[route.name] ?? "Logomocja"} · Logomocja`;
      switch (route.name) {
        case "studio":
          studio.bindChallenge(null);
          showStudio();
          break;
        case "examples":
          showPage(renderExamples(pageDeps));
          break;
        case "challenges":
          showPage(renderChallenges(pageDeps));
          break;
        case "challenge":
          studio.bindChallenge(route.id);
          showStudio();
          break;
        case "reference":
          showPage(renderReference(pageDeps, route.anchor));
          break;
        case "example":
          studio.bindChallenge(null);
          showStudio();
          await studio.openExample(route.id);
          replaceHash("#/pracownia");
          break;
        case "permalink": {
          const shared = parsePermalink(route.hash);
          studio.bindChallenge(null);
          showStudio();
          if (!shared) {
            overlays.toast("Ten link do programu jest uszkodzony, więc nic nie wczytano.");
          } else {
            await studio.open(shared.source, shared.mode, "link");
          }
          replaceHash("#/pracownia");
          break;
        }
      }
      if (route.name !== "studio" && route.name !== "challenge" && route.name !== "permalink" && route.name !== "example") {
        main.scrollTop = 0;
        main.focus({ preventScroll: true });
      }
    } finally {
      routing = false;
    }
  };

  const replaceHash = (hash: string) => {
    try {
      win.history.replaceState(null, "", win.location.href.split("#")[0] + hash);
    } catch {
      /* history unavailable */
    }
    for (const a of navLinks) a.removeAttribute("aria-current");
    navLinks[0].setAttribute("aria-current", "page");
  };

  win.addEventListener("hashchange", applyRoute);

  // --- public hook -------------------------------------------------------------------------------
  const settle = () =>
    new Promise<void>((resolve) => {
      let done = false;
      const fin = () => {
        if (!done) {
          done = true;
          resolve();
        }
      };
      win.setTimeout(fin, 60);
      if (win.requestAnimationFrame) win.requestAnimationFrame(() => win.requestAnimationFrame(fin));
    });

  const api: LogomocjaApi = {
    version: VERSION,
    run: (source, mode) => run(source, mode),
    async open(source, mode) {
      if (parseRoute(win.location.hash).name !== "studio") replaceHash("#/pracownia");
      studio.bindChallenge(null);
      showStudio();
      const result = await studio.open(source, mode, "window.logomocja.open");
      viewport.renderNow();
      await settle();
      return result;
    },
  };

  void applyRoute();

  return {
    api,
    destroy() {
      win.removeEventListener("hashchange", applyRoute);
      shell.remove();
    },
  };
}

function safeLocalStorage(win: Window): StorageLike {
  try {
    const s = win.localStorage;
    s.getItem("logomocja.probe");
    return s;
  } catch {
    const mem = new Map<string, string>();
    return {
      getItem: (k) => mem.get(k) ?? null,
      setItem: (k, v) => void mem.set(k, v),
      removeItem: (k) => void mem.delete(k),
    };
  }
}
