s=s.replace('''    if (s.status === "error" && s.error && !s.stale) {
      editor.setError(s.error);''','''    if (s.status === "error" && s.error && !s.stale) {
      if (lastStatus !== "error" && narrow() && s.error && pane === "view") setPane("code");
      editor.setError(s.error);''')
s=s.replace('''  function refresh() {
    const s = controller.getState();''','''  let lastStatus: ControllerState["status"] = "idle";
  function refresh() {
