s=s.replace('''    viewport.setScene({ segments: s.segments, turtle: s.status === "idle" && s.segments.length === 0 ? s.turtle : s.turtle, ghost });''','''    viewport.setScene({ segments: s.segments, turtle: s.turtle, ghost });''')
s=s.replace('''    viewport.renderNow();
