import { describe, expect, test } from "bun:test";
import { Window } from "happy-dom";
import { mountApp } from "../src/ui/app";
import { buildPermalink } from "../src/core/share";
import { EXAMPLES, exampleById } from "../src/core/examples";
import { SoftCanvas } from "../tools/softcanvas";

class MemoryStorage {
  data = new Map<string, string>();
  getItem(k: string) {
    return this.data.get(k) ?? null;
  }
  setItem(k: string, v: string) {
    this.data.set(k, v);
  }
  removeItem(k: string) {
    this.data.delete(k);
  }
}

function fakeScheduler() {
  let pending: (() => void) | null = null;
  return {
    schedule(cb: () => void) {
      pending = cb;
      return 1;
    },
    cancel() {
      pending = null;
    },
    get waiting() {
      return pending !== null;
    },
    fire() {
      const cb = pending;
      pending = null;
      cb?.();
    },
  };
}

interface Opts {
  storage?: MemoryStorage;
  hash?: string;
  noCanvas?: boolean;
}

async function boot(o: Opts = {}) {
  const storage = o.storage ?? new MemoryStorage();
  const win = new Window({ url: "https://example.org/Logomocja/builds/x/" + (o.hash ?? ""), width: 1200, height: 800 });
  const doc = win.document as unknown as Document;
  const root = doc.createElement("div");
  doc.body.appendChild(root);
  const sched = fakeScheduler();
  const app = mountApp(root, {
    storage,
    scheduler: sched,
    getContext: o.noCanvas ? () => null : () => new SoftCanvas(800, 500),
  });
  await tick(win);
  return { win, doc, app, storage, sched };
}

const tick = (win: Window, ms = 5) => new Promise<void>((r) => win.setTimeout(() => r(), ms));
type H = Awaited<ReturnType<typeof boot>>;
const q = (h: H, sel: string) => h.doc.querySelector(sel) as HTMLElement | null;
const qa = (h: H, sel: string) => [...h.doc.querySelectorAll(sel)] as HTMLElement[];
const text = (el: Element | null) => (el?.textContent ?? "").replace(/\s+/g, " ").trim();
const button = (h: H, label: string) =>
  qa(h, "button").find((b) => text(b).startsWith(label) || (b.getAttribute("aria-label") ?? "").startsWith(label));
const editor = (h: H) => q(h, "textarea[aria-label='Kod programu']") as unknown as HTMLTextAreaElement;
const type = (h: H, value: string) => {
  const ta = editor(h);
  ta.value = value;
  ta.dispatchEvent(new h.win.Event("input", { bubbles: true }) as unknown as Event);
};
const goto = async (h: H, hash: string) => {
  h.win.location.hash = hash;
  await tick(h.win, 20);
};
const status = (h: H) => text(q(h, "[data-role=status]"));

describe("pierwsze uruchomienie", () => {
  test("po wejściu rysunek początkowego programu jest już narysowany, a arkusz nie jest pusty", async () => {
    const h = await boot();
    expect(status(h)).toBe("Zakończono");
    expect(text(q(h, "[data-role=segment-count]"))).toContain("4");
    expect(q(h, "[data-role=empty-hint]")?.hasAttribute("hidden")).toBe(true);
  });
});

describe("sterowanie przyciskami", () => {
  test("Uruchom animuje, Pauza zatrzymuje, Wznów kontynuuje, Krok wykonuje jedno polecenie, Reset czyści", async () => {
    const h = await boot();
    type(h, "powtorz 4 [np 10 pw 90]");
    button(h, "Reset")!.click();
    expect(status(h)).toBe("Gotowy");
    button(h, "Uruchom")!.click();
    expect(status(h)).toBe("Działa");
    h.sched.fire();
    h.sched.fire();
    button(h, "Pauza")!.click();
    expect(status(h)).toBe("Wstrzymano");
    const drawn = text(q(h, "[data-role=segment-count]"));
    h.sched.fire();
    expect(text(q(h, "[data-role=segment-count]"))).toBe(drawn);
    expect(button(h, "Wznów")).toBeDefined();
    button(h, "Wznów")!.click();
    expect(status(h)).toBe("Działa");
    while (h.sched.waiting) h.sched.fire();
    expect(status(h)).toBe("Zakończono");
    expect(text(q(h, "[data-role=segment-count]"))).toContain("4");

    button(h, "Reset")!.click();
    button(h, "Krok")!.click();
    expect(status(h)).toBe("Wstrzymano");
    expect(text(q(h, "[data-role=line-col]"))).toContain("Linia 1");
    expect(q(h, "[data-role=exec-line]")).not.toBeNull();
  });

  test("skróty klawiszowe: Ctrl+Enter uruchamia, Alt+Enter robi krok, Alt+P wstrzymuje, Alt+R resetuje", async () => {
    const h = await boot();
    type(h, "powtorz 3 [np 10 pw 90]");
    const press = (init: KeyboardEventInit) =>
      h.win.dispatchEvent(new h.win.KeyboardEvent("keydown", { bubbles: true, cancelable: true, ...init }) as unknown as Event);
    press({ key: "Enter", ctrlKey: true });
    expect(status(h)).toBe("Działa");
    press({ key: "p", altKey: true });
    expect(status(h)).toBe("Wstrzymano");
    press({ key: "r", altKey: true });
    expect(status(h)).toBe("Gotowy");
    press({ key: "Enter", altKey: true });
    expect(status(h)).toBe("Wstrzymano");
    expect(text(q(h, "[data-role=step-count]"))).toContain("1");
  });

  test("prędkość jest zapamiętywana i opisana słownie", async () => {
    const storage = new MemoryStorage();
    const a = await boot({ storage });
    const speed = q(a, "#speed") as unknown as HTMLInputElement;
    speed.value = "8";
    speed.dispatchEvent(new a.win.Event("input", { bubbles: true }) as unknown as Event);
    expect(text(q(a, "#speed-out"))).toContain("1000");
    const b = await boot({ storage });
    expect((q(b, "#speed") as unknown as HTMLInputElement).value).toBe("8");
  });

  test("edycja w czasie animacji wstrzymuje ją i oznacza rysunek jako nieaktualny", async () => {
    const h = await boot();
    type(h, "powtorz 50 [np 1]");
    button(h, "Uruchom")!.click();
    h.sched.fire();
    type(h, "powtorz 50 [np 2]");
    expect(status(h)).toBe("Wstrzymano");
    expect(q(h, ".status-stale")?.hasAttribute("hidden")).toBe(false);
    expect(h.sched.waiting).toBe(false);
  });
});

