import { describe, expect, test } from "bun:test";
import { Window } from "happy-dom";
import { mountApp } from "../src/ui/app";
import { buildPermalink } from "../src/core/share";
import { EXAMPLES, exampleById } from "../src/core/examples";
import { SoftCanvas } from "../tools/softcanvas";

class MemoryStorage {
  data = new Map<string, string>();
  getItem(k: string) {
    return this.data.get(k) ?? null;
  }
  setItem(k: string, v: string) {
    this.data.set(k, v);
  }
  removeItem(k: string) {
    this.data.delete(k);
  }
}

function fakeScheduler() {
  let pending: (() => void) | null = null;
  return {
    schedule(cb: () => void) {
      pending = cb;
      return 1;
    },
    cancel() {
      pending = null;
    },
    get waiting() {
      return pending !== null;
    },
    fire() {
      const cb = pending;
      pending = null;
      cb?.();
    },
  };
}

interface Opts {
  storage?: MemoryStorage;
  hash?: string;
  noCanvas?: boolean;
}

async function boot(o: Opts = {}) {
  const storage = o.storage ?? new MemoryStorage();
  const win = new Window({ url: "https://example.org/Logomocja/builds/x/" + (o.hash ?? ""), width: 1200, height: 800 });
  const doc = win.document as unknown as Document;
  const root = doc.createElement("div");
  doc.body.appendChild(root);
  const sched = fakeScheduler();
  const app = mountApp(root, {
    storage,
    scheduler: sched,
    getContext: o.noCanvas ? () => null : () => new SoftCanvas(800, 500),
  });
  await tick(win);
  return { win, doc, app, storage, sched };
}

const tick = (win: Window, ms = 5) => new Promise<void>((r) => win.setTimeout(() => r(), ms));
type H = Awaited<ReturnType<typeof boot>>;
const q = (h: H, sel: string) => h.doc.querySelector(sel) as HTMLElement | null;
const qa = (h: H, sel: string) => [...h.doc.querySelectorAll(sel)] as HTMLElement[];
const text = (el: Element | null) => (el?.textContent ?? "").replace(/\s+/g, " ").trim();
const button = (h: H, label: string) =>
  qa(h, "button").find((b) => text(b).startsWith(label) || (b.getAttribute("aria-label") ?? "").startsWith(label));
