/** Bounding box of the stroke colour on the software canvas. */
function inkBox(cv: SoftCanvas, rgb: [number, number, number]) {
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity, n = 0;
  for (let y = 0; y < cv.height; y++) {
    for (let x = 0; x < cv.width; x++) {
      const [r, g, b, a] = cv.pixel(x, y);
      if (a > 200 && Math.abs(r - rgb[0]) < 10 && Math.abs(g - rgb[1]) < 10 && Math.abs(b - rgb[2]) < 10) {
        x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); n++;
      }
    }
  }
  return { x0, y0, x1, y1, n, w: x1 - x0, h: y1 - y0 };
}
