import { describe, expect, test } from "bun:test";
import { Window } from "happy-dom";
import { readFileSync, existsSync } from "node:fs";

describe("pakiet produkcyjny", () => {
  test("zbundlowany main.ts w czystym oknie tworzy window.logomocja z version, run i open", async () => {
    const out = await Bun.build({ entrypoints: ["./src/main.ts"], target: "browser", format: "iife", minify: true });
    expect(out.success).toBe(true);
    const code = await out.outputs.find((o) => o.path.endsWith(".js"))!.text();

    const win = new Window({ url: "https://example.org/Logomocja/builds/x/" });
    win.document.body.innerHTML = '<div id="app"></div>';
    // happy-dom ma localStorage, ale nie ma płótna 2D: to właśnie sprawdza ścieżkę „bez płótna”
    win.eval(code);
    const api = (win as unknown as { logomocja: { version: string; run: Function; open: Function } }).logomocja;
    expect(typeof api.version).toBe("string");
    expect(api.run("powtorz 4 [np 10 pw 90]", "2d")).toMatchObject({ error: null });
    const r = await api.open("np 25", "2d");
    expect(r.segments).toEqual([{ from: [0, 0, 0], to: [0, 25, 0], color: "#16866a", width: 3 }]);
    expect((win.document.querySelector("textarea[aria-label='Kod programu']") as HTMLTextAreaElement).value).toBe("np 25");
  });

  test("indeks HTML i zasoby są lokalne: brak adresów zewnętrznych w źródłach aplikacji", () => {
    const html = readFileSync("index.html", "utf8");
    expect(html).not.toMatch(/https?:\/\//);
    const css = readFileSync("src/styles.css", "utf8");
    expect(css).not.toMatch(/url\(\s*["']?https?:/);
    expect(css).not.toMatch(/@import/);
    expect(existsSync("public/favicon.svg")).toBe(true);
  });
});
EOF
