import { readFileSync, existsSync } from "node:fs";
const PREFIX = "/Logomocja/builds/x/";
const server = Bun.serve({
  port: 0,
  fetch(req) {
    const u = new URL(req.url);
    if (!u.pathname.startsWith(PREFIX)) return new Response("nope", { status: 404 });
    let rel = u.pathname.slice(PREFIX.length) || "index.html";
    const f = "/work/dist/" + rel;
    if (!existsSync(f)) return new Response("missing", { status: 404 });
    return new Response(readFileSync(f), { headers: { "content-type": f.endsWith(".js") ? "text/javascript" : f.endsWith(".css") ? "text/css" : f.endsWith(".svg") ? "image/svg+xml" : "text/html" } });
  },
});
const base = `http://localhost:${server.port}${PREFIX}`;
const html = await (await fetch(base)).text();
const urls = [...html.matchAll(/(?:src|href)="([^"]+)"/g)].map((m) => m[1]).filter((u) => !u.startsWith("data:"));
for (const u of urls) {
  const abs = u.startsWith("/") ? `http://localhost:${server.port}${u}` : new URL(u, base).href;
  const r = await fetch(abs);
  console.log(r.status, u);
}
// refresh on a deep hash route is the same document (hash routing)
console.log((await fetch(base + "#/wyzwania/kwadrat-100")).status, "index with hash");
const js = urls.find((u) => u.endsWith(".js"))!;
const code = await (await fetch(`http://localhost:${server.port}${js}`)).text();
console.log("bundle mentions external hosts:", /https?:\/\/(?!www\.w3\.org)[a-z0-9.-]+\.[a-z]{2,}/i.test(code));
server.stop();
EOF
