describe("odporność na długie wyrażenia (limit 10 000 tokenów)", () => {
  test("łańcuch 4990 dodawań liczy się bez przepełnienia stosu", () => {
    const r = run("np " + "1 + ".repeat(4990) + "1", "2d");
    expect(r.error).toBeNull();
    expect(r.segments[0].to[1]).toBe(4991);
  });
  test("tysiące znaków jednoargumentowych: parzysta liczba minusów to plus, nieparzysta to minus", () => {
    const even = run("np " + "-".repeat(8000) + "1", "2d");
    expect(even.error).toBeNull();
    expect(even.segments[0].to[1]).toBe(1);
    const odd = run("np " + "- ".repeat(7999) + "-1", "2d");
    expect(odd.segments[0].to[1]).toBe(-8000 % 2 === 0 ? -1 : 1);
  });
  test("długi łańcuch mieszanych działań i wywołanie z wieloma argumentami nie wywracają parsera", () => {
    const chain = "1 - 1 + ".repeat(2400) + "3";
    expect(run("np " + chain, "2d").segments[0].to[1]).toBe(3);
    const nest = "(".repeat(31) + "5" + ")".repeat(31);
    expect(run("np " + nest, "2d").segments[0].to[1]).toBe(5);
  });
  test("zagnieżdżenie nawiasów okrągłych głębsze niż 32 to błąd na 33. nawiasie", () => {
    const nest = "(".repeat(33) + "5" + ")".repeat(33);
    expect(run("np " + nest, "2d").error).toMatchObject({ line: 1, column: 3 + 33 });
  });
  test("stałe wyrażenie w literalnej liczbie powtórzeń też jest liczone bez rekursji", () => {
    const r = run("powtorz " + "1 + ".repeat(4000) + "1 [ ]", "2d");
    expect(r.error?.message).toMatch(/powtórze/);
  });
});
EOF
