import { Window } from "happy-dom";
import { mountApp } from "../src/ui/app";
import { SoftCanvas } from "../tools/softcanvas";

/** Minimal in-memory localStorage: the real boundary of the workspace. */
export class MemoryStorage {
  data = new Map<string, string>();
  getItem(k: string) {
    return this.data.get(k) ?? null;
  }
  setItem(k: string, v: string) {
    this.data.set(k, v);
  }
  removeItem(k: string) {
    this.data.delete(k);
  }
}

/** A scheduler driven by hand: time is the one external boundary of the controller. */
export function fakeScheduler() {
  let pending: (() => void) | null = null;
  return {
    schedule(cb: () => void, _ms?: number) {
      pending = cb;
      return 1;
    },
    cancel() {
      pending = null;
    },
    get waiting() {
      return pending !== null;
    },
    fire() {
      const cb = pending;
      pending = null;
      cb?.();
    },
  };
}

// One happy-dom window for the whole test process: creating a window costs hundreds of ms.
let shared: Window | null = null;
const live: { destroy(): void }[] = [];

export interface MountOpts {
  storage?: MemoryStorage;
  hash?: string;
  noCanvas?: boolean;
  scheduler?: ReturnType<typeof fakeScheduler>;
}

export async function mount(o: MountOpts = {}) {
  shared ??= new Window({ width: 1200, height: 800 });
  const win = shared;
  win.happyDOM.setURL("https://example.org/Logomocja/builds/x/" + (o.hash ?? ""));
  const doc = win.document as unknown as Document;
  doc.documentElement.removeAttribute("data-theme");
  const root = doc.createElement("div");
  doc.body.appendChild(root);
  const storage = o.storage ?? new MemoryStorage();
  const sched = o.scheduler ?? fakeScheduler();
  const canvases: SoftCanvas[] = [];
  const app = mountApp(root, {
    storage,
    scheduler: sched,
    getContext: o.noCanvas
      ? () => null
      : (c) => {
          const thumb = c.classList.contains("thumb");
          const cv = new SoftCanvas(thumb ? 56 : 800, thumb ? 38 : 500);
          canvases.push(cv);
          return cv;
        },
  });
  live.push({
    destroy() {
      app.destroy();
      root.remove();
    },
  });
  await new Promise<void>((r) => win.setTimeout(() => r(), 5));
  return { win, doc, app, storage, sched, canvases };
}

export function cleanup() {
  while (live.length) live.pop()!.destroy();
}
EOF
