cat >> test/flows.test.ts <<'EOF'

describe("pliki i eksport", () => {
  /** Records every blob handed to URL.createObjectURL and every download link that gets clicked. */
  function spyDownloads(h: Awaited<ReturnType<typeof boot>>) {
    const blobs: Blob[] = [];
    const names: string[] = [];
    const url = h.win.URL as unknown as { createObjectURL: (b: Blob) => string; revokeObjectURL: (u: string) => void };
    url.createObjectURL = (b: Blob) => (blobs.push(b), `blob:test/${blobs.length}`);
    url.revokeObjectURL = () => {};
    h.doc.addEventListener("click", (e) => {
      const a = (e.target as HTMLAnchorElement | null);
      if (a?.tagName === "A" && a.hasAttribute("download")) {
        names.push(a.getAttribute("download")!);
        e.preventDefault();
      }
    }, true);
    return { blobs, names };
  }

  test("Pobierz zapisuje program jako plik .logo z samym tekstem programu", async () => {
    const h = await boot();
    const spy = spyDownloads(h);
    type(h, "powtorz 3 [np 10 pw 120]");
    button(h, "Pobierz")!.click();
    expect(spy.names).toEqual(["program-2d.logo"]);
    expect(await spy.blobs[0].text()).toBe("powtorz 3 [np 10 pw 120]\n");
  });

  test("Otwórz plik .logo wczytuje program do edytora, a polecenia 3D przełączają tryb na 3D", async () => {
    const h = await boot();
    const input = q(h, "input[type=file]") as unknown as HTMLInputElement;
    const file = new h.win.File(["﻿gora 90\r\nnp 30\r\n"], "wieza.logo", { type: "text/plain" });
    Object.defineProperty(input, "files", { value: { 0: file, length: 1, item: () => file }, configurable: true });
    input.dispatchEvent(new h.win.Event("change", { bubbles: true }) as never);
    await tick(h.win, 40);
    expect(editor(h).value).toBe("gora 90\nnp 30\n");
    expect(q(h, "[role=radio][aria-checked=true]")?.textContent).toBe("3D");
    expect(status(h)).toBe("Zakończono");
  });

  test("zbyt duży plik jest odrzucany z komunikatem, a szkic zostaje", async () => {
    const h = await boot();
    const before = editor(h).value;
    const input = q(h, "input[type=file]") as unknown as HTMLInputElement;
    const file = new h.win.File(["x".repeat(300_000)], "duzy.logo");
    Object.defineProperty(input, "files", { value: { 0: file, length: 1, item: () => file }, configurable: true });
    input.dispatchEvent(new h.win.Event("change", { bubbles: true }) as never);
    await tick(h.win, 20);
    expect(editor(h).value).toBe(before);
    expect(text(q(h, "[data-role=toast]"))).toContain("za duży");
  });

  test("eksport PNG pobiera obraz z rysunkiem pod nazwą z trybem", async () => {
    const h = await boot();
    const spy = spyDownloads(h);
    await h.app.api.open("np 50", "2d");
    button(h, "Pobierz rysunek jako PNG")!.click();
    await tick(h.win, 30);
    expect(spy.names).toEqual(["logomocja-2d.png"]);
    expect(spy.blobs[0].type).toBe("image/png");
  });
});
EOF
