import { describe, expect, test } from "bun:test";
import { highlight } from "../src/ui/highlight";
import { EXAMPLES } from "../src/core/examples";
import { ALL_DOC_EXAMPLES } from "../src/ui/docs-data";

const text = (html: string) =>
  html.replace(/<[^>]+>/g, "").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&");
const classes = (html: string) => [...html.matchAll(/<span class="tk-([a-z]+)"[^>]*>([^<]*)<\/span>/g)].map((m) => [m[1], m[2]]);

describe("kolorowanie składni", () => {
  test("po usunięciu znaczników zostaje dokładnie ten sam tekst (nic nie ginie, nic nie dochodzi)", () => {
    for (const src of [...EXAMPLES.map((e) => e.source), ...ALL_DOC_EXAMPLES.map((e) => e.code), "np <script>alert(1)</script> & \"x\"", "\t\r\n; ąęłżźć"]) {
      expect(text(highlight(src))).toBe(src);
    }
  });

  test("rozróżnia polecenia, słowa sterujące, liczby, napisy-kolory, nawiasy, komentarze i nazwy", () => {
    const got = classes(highlight('powtorz 4 [np 12.5 kolor "#16866a"] ; koniec\noto kwadrat ma: bok\njuż'));
    const kind = (t: string) => got.find(([, x]) => x === t)?.[0];
    expect(kind("powtorz")).toBe("kw");
    expect(kind("4")).toBe("num");
    expect(kind("[")).toBe("br");
    expect(kind("np")).toBe("cmd");
    expect(kind("12.5")).toBe("num");
    expect(kind("kolor")).toBe("cmd");
    expect(kind('"#16866a"')).toBe("string");
    expect(kind("; koniec")).toBe("comment");
    expect(kind("oto")).toBe("kw");
    expect(kind("kwadrat")).toBe("name");
    expect(kind("ma:")).toBe("kw");
    expect(kind("już")).toBe("kw");
  });

  test("aliasy angielskie i wielkie litery są kolorowane jak polskie polecenia", () => {
    const got = classes(highlight("FORWARD 5 Pitchup 3 PW 1"));
    expect(got.filter(([k]) => k === "cmd").map(([, t]) => t)).toEqual(["FORWARD", "Pitchup", "PW"]);
  });

  test("błędne liczby (1e3) i niezamknięty napis są oznaczone jako błędne, a kolor „#16866a” zachowuje własny kolor podkreślenia", () => {
    expect(classes(highlight("np 1e3"))).toContainEqual(["bad", "1e3"]);
    expect(classes(highlight('kolor "#16866'))[1][0]).toBe("badstring");
    expect(highlight('"#c1763d"')).toContain("border-bottom-color:#c1763d");
  });
});
EOF
