import { afterEach, describe, expect, test } from "bun:test";
import { cleanup, mount } from "./helpers";

afterEach(cleanup);

const tick = (win: { setTimeout: (f: () => void, ms?: number) => unknown }, ms = 20) => new Promise<void>((r) => win.setTimeout(() => r(), ms));

/** Accessible name by the usual precedence: aria-labelledby, aria-label, label[for], content, title. */
function nameOf(doc: Document, el: Element): string {
  const by = el.getAttribute("aria-labelledby");
  if (by) return by.split(/\s+/).map((id) => doc.getElementById(id)?.textContent ?? "").join(" ").trim();
  const aria = el.getAttribute("aria-label");
  if (aria) return aria.trim();
  if (el.id) {
    const lab = doc.querySelector(`label[for="${el.id}"]`);
    if (lab?.textContent?.trim()) return lab.textContent.trim();
  }
  const content = (el.textContent ?? "").replace(/\s+/g, " ").trim();
  if (content) return content;
  return (el.getAttribute("title") ?? "").trim();
}

const ROUTES = ["#/pracownia", "#/przyklady", "#/wyzwania", "#/wyzwania/trojkat", "#/polecenia"];

describe("dostępność: struktura DOM na każdej trasie", () => {
  for (const route of ROUTES) {
    test(`${route}: każdy element sterujący ma nazwę, identyfikatory są unikalne, aria-controls wskazuje istniejące elementy`, async () => {
      const h = await mount({ hash: route });
      await tick(h.win, 30);
      const doc = h.doc;
      const visible = (el: Element) => !el.closest("[hidden]");

      const controls = [...doc.querySelectorAll("button, a[href], input, textarea, select, [role=radio], [role=tab], canvas[tabindex]")].filter(visible);
      expect(controls.length).toBeGreaterThan(5);
      for (const c of controls) {
        const type = c.getAttribute("type");
        if (type === "file") continue;
        expect(nameOf(doc, c), `${c.tagName.toLowerCase()} bez nazwy: ${c.outerHTML.slice(0, 120)}`).not.toBe("");
      }

      const ids = [...doc.querySelectorAll("[id]")].map((e) => e.id);
      expect(new Set(ids).size, `powtórzone id: ${ids.filter((x, i) => ids.indexOf(x) !== i)}`).toBe(ids.length);

      for (const el of doc.querySelectorAll("[aria-controls]")) {
        for (const id of el.getAttribute("aria-controls")!.split(/\s+/)) expect(doc.getElementById(id), `aria-controls → #${id}`).not.toBeNull();
      }
      for (const el of doc.querySelectorAll("[aria-describedby]")) {
        for (const id of el.getAttribute("aria-describedby")!.split(/\s+/)) expect(doc.getElementById(id), `aria-describedby → #${id}`).not.toBeNull();
      }
    });
  }

  test("strony pomocnicze mają dokładnie jeden nagłówek h1, a nagłówki nie przeskakują poziomów", async () => {
    for (const route of ["#/przyklady", "#/wyzwania", "#/polecenia"]) {
      const h = await mount({ hash: route });
      await tick(h.win, 30);
      const page = h.doc.querySelector(".page")!;
      expect(page.querySelectorAll("h1").length, route).toBe(1);
      const levels = [...page.querySelectorAll("h1,h2,h3")].map((x) => Number(x.tagName[1]));
      for (let i = 1; i < levels.length; i++) expect(levels[i] - levels[i - 1], `${route} skok nagłówków`).toBeLessThanOrEqual(1);
      cleanup();
    }
  });

  test("są landmarki: nawigacja z etykietą, główna treść oraz link pomijający nawigację", async () => {
    const h = await mount();
    expect(h.doc.querySelector("nav[aria-label]")).not.toBeNull();
    expect(h.doc.querySelector("main#main")).not.toBeNull();
    expect(h.doc.querySelector("a.skip-link[href='#main']")).not.toBeNull();
    expect(h.doc.querySelectorAll("header").length).toBeGreaterThanOrEqual(1);
  });

  test("grupa trybu to radiogroup z dokładnie jednym zaznaczonym i jednym tabindex=0 (roving)", async () => {
    const h = await mount();
    const group = h.doc.querySelector("[role=radiogroup]")!;
    const radios = [...group.querySelectorAll("[role=radio]")] as HTMLElement[];
    expect(radios).toHaveLength(2);
    expect(radios.filter((r) => r.getAttribute("aria-checked") === "true")).toHaveLength(1);
    expect(radios.filter((r) => r.tabIndex === 0)).toHaveLength(1);
    expect(group.getAttribute("aria-label")).toBeTruthy();
  });

  test("przyciski sterujące mają aria-keyshortcuts zgodne z listą skrótów", async () => {
    const h = await mount();
    const keys = new Map<string, string>();
    for (const b of h.doc.querySelectorAll("button[aria-keyshortcuts]")) keys.set((b.textContent ?? "").trim(), b.getAttribute("aria-keyshortcuts")!);
    expect(keys.get("Uruchom")).toBe("Control+Enter");
    expect(keys.get("Krok")).toBe("Alt+Enter");
    expect(keys.get("Pauza")).toBe("Alt+P");
    expect(keys.get("Reset")).toBe("Alt+R");
  });
});
EOF
