import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";

const css = readFileSync("src/styles.css", "utf8");

function block(selector: string): Record<string, string> {
  const start = css.indexOf(selector + " {");
  expect(start, selector).toBeGreaterThanOrEqual(0);
  const body = css.slice(css.indexOf("{", start) + 1, css.indexOf("\n}", start));
  const vars: Record<string, string> = {};
  for (const m of body.matchAll(/--([a-z0-9-]+):\s*([^;]+);/g)) vars[m[1]] = m[2].trim();
  return vars;
}

const lum = (hex: string) => {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255).map((c) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};
const ratio = (a: string, b: string) => {
  const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
};

const light = block(":root");
const dark = block(':root[data-theme="dark"]');
// the prefers-color-scheme block must stay identical to the manual dark theme
const mediaStart = css.indexOf('@media (prefers-color-scheme: dark)');
const media: Record<string, string> = {};
{
  const body = css.slice(css.indexOf("{", css.indexOf(":root:not", mediaStart)) + 1, css.indexOf("\n  }", mediaStart));
  for (const m of body.matchAll(/--([a-z0-9-]+):\s*([^;]+);/g)) media[m[1]] = m[2].trim();
}

type Theme = Record<string, string>;
const themes: [string, Theme][] = [["jasny", light], ["ciemny", dark]];

describe("kontrast tekstu i elementów interfejsu (WCAG AA)", () => {
  for (const [name, t] of themes) {
