describe("rozwiązanie wzorcowe", () => {
  test("wstawienie rozwiązania do wyzwania zachowuje własny tekst w kopiach i nie rusza szkicu pracowni", async () => {
    const h = await boot();
    type(h, "np 1 ; pracownia");
    await goto(h, "#/wyzwania/trojkat");
    type(h, "np 7 ; moja próba");
    button(h, "Pokaż rozwiązanie")!.click();
    await tick(h.win, 10);
    const dialog = q(h, "dialog")!;
    expect(text(dialog)).toContain("powtorz 3 [np 120 pw 120]");
    [...dialog.querySelectorAll("button")].find((b) => text(b) === "Wstaw do edytora")!.click();
    await tick(h.win, 30);
    expect(editor(h).value).toBe("powtorz 3 [np 120 pw 120]");
    const saved = JSON.parse(h.storage.getItem("logomocja.workspace.v1")!);
    expect(saved.backups.map((b: { source: string }) => b.source)).toContain("np 7 ; moja próba");
    expect(saved.drafts["2d"]).toBe("np 1 ; pracownia");
    button(h, "Sprawdź")!.click();
    expect(text(q(h, "[data-role=challenge-result]"))).toContain("Zaliczone");
  });
});
EOF
